-- Phase 3: real template design diversity
-- Regenerates structure.files (component source) and thumbnail for all live templates
-- so each template has a genuinely distinct layout, typography, palette, and section
-- arrangement instead of sharing 13 identical section-builder functions.
-- structure.pages and every other templates column are left untouched.

UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-0 z-40 border-b border-slate-100 bg-white/80 backdrop-blur\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-4\">\n        <a href=\"/\" className=\"font-['Courier_New',ui-monospace,monospace] text-lg font-bold tracking-tight text-slate-900\">Cast Iron Studio</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n          <a href=\"/work\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Work</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-sm bg-violet-600 px-4 py-2 text-sm font-semibold text-white hover:bg-violet-700 transition-colors\">Get in touch</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-4xl px-6 py-24 text-center md:py-28\">\n        <span className=\"inline-block rounded-sm bg-white px-3 py-1 text-xs font-semibold uppercase tracking-tight text-violet-700 shadow-sm\">CREATIVE AGENCY</span>\n        <h1 className=\"font-['Courier_New',ui-monospace,monospace] mx-auto mt-5 max-w-3xl text-4xl md:text-5xl font-bold leading-[1.05] tracking-tight text-slate-900\">Bold work for brands that refuse to play it safe.</h1>\n        <p className=\"mx-auto mt-5 max-w-xl text-lg text-slate-600\">Cast Iron takes on a handful of clients at a time, on purpose.</p>\n        <div className=\"mt-8 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-sm bg-violet-600 px-6 py-3 text-sm font-semibold text-white hover:bg-violet-700 transition-colors\">Start now</a>\n          <a href=\"#more\" className=\"rounded-sm border border-slate-300 px-6 py-3 text-sm font-semibold text-slate-700 hover:border-slate-400 transition-colors\">View details</a>\n        </div>\n        <div className=\"mx-auto mt-14 grid max-w-2xl grid-cols-3 gap-6 border-t border-slate-200 pt-8\">\n          <div><p className=\"text-2xl font-bold text-slate-900\">98%</p><p className=\"mt-1 text-xs uppercase tracking-tight text-slate-400\">Satisfaction</p></div>\n          <div><p className=\"text-2xl font-bold text-slate-900\">24/7</p><p className=\"mt-1 text-xs uppercase tracking-tight text-slate-400\">Support</p></div>\n          <div><p className=\"text-2xl font-bold text-slate-900\">50+</p><p className=\"mt-1 text-xs uppercase tracking-tight text-slate-400\">Team members</p></div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"border-t border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto flex max-w-6xl flex-col gap-8 px-6 py-14 md:flex-row md:items-start md:justify-between\">\n        <div className=\"max-w-sm\">\n          <p className=\"font-['Courier_New',ui-monospace,monospace] text-lg font-bold tracking-tight text-slate-900\">Cast Iron Studio</p>\n          <p className=\"mt-2 text-sm text-slate-500\">Cast Iron takes on a handful of clients at a time, on purpose.</p>\n        </div>\n        <div className=\"flex gap-8\">\n          <a href=\"/work\" className=\"text-sm text-slate-500 hover:text-slate-900\">Work</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a>\n        </div>\n      </div>\n      <div className=\"border-t border-slate-200\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center justify-between gap-3 px-6 py-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Cast Iron Studio. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-violet-600\"><span className=\"h-1.5 w-1.5 rounded-full bg-violet-600\" /> Built with webma</div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-['Courier_New',ui-monospace,monospace] text-xl md:text-2xl font-bold tracking-tight text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Questions, quotes, or just saying hello — we'd love to hear from you.</p>\n      <form className=\"mt-8 space-y-4\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-sm border border-slate-200 px-4 py-2.5 text-sm focus:border-violet-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-sm border border-slate-200 px-4 py-2.5 text-sm focus:border-violet-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-sm border border-slate-200 px-4 py-2.5 text-sm focus:border-violet-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-sm bg-violet-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-violet-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14 text-center\">\n        <span className=\"text-xs font-semibold uppercase tracking-tight text-violet-600\">Everything you need to know about how we approach creative agency.</span>\n        <h1 className=\"font-['Courier_New',ui-monospace,monospace] mx-auto mt-3 max-w-2xl text-xl md:text-2xl font-bold tracking-tight text-slate-900\">Work</h1>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid gap-10 md:grid-cols-[1fr_1fr]\">\n        <h2 className=\"font-['Courier_New',ui-monospace,monospace] text-xl md:text-2xl font-bold leading-tight tracking-tight text-slate-900\">About Cast Iron Studio</h2>\n        <div className=\"space-y-4\">\n          <p className=\"text-slate-600\">Behind Cast Iron Studio is a small, focused team that cares more about doing the work right than doing a lot of it. That's shaped everything about how we operate.</p>\n          <div className=\"h-1 w-16 rounded-sm bg-gradient-to-r from-violet-500 to-lime-500\" />\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Work.tsx":"export default function Work() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Courier_New',ui-monospace,monospace] text-xl md:text-2xl font-bold tracking-tight text-slate-900\">Selected work</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Cast Iron Studio does best.</p>\n      </div>\n      <div className=\"mt-10 grid gap-8 sm:grid-cols-2 lg:grid-cols-3\">\n        <div>\n          <p className=\"font-['Courier_New',ui-monospace,monospace] text-4xl font-bold text-violet-200\">01</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Brand identity</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Full rebrand systems, from logo to voice.</p>\n        </div>\n        <div>\n          <p className=\"font-['Courier_New',ui-monospace,monospace] text-4xl font-bold text-violet-200\">02</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Product design</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">End-to-end UX for apps people actually enjoy using.</p>\n        </div>\n        <div>\n          <p className=\"font-['Courier_New',ui-monospace,monospace] text-4xl font-bold text-violet-200\">03</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Campaign strategy</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Launch campaigns across print, digital, and social.</p>\n        </div>\n        <div>\n          <p className=\"font-['Courier_New',ui-monospace,monospace] text-4xl font-bold text-violet-200\">04</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Web design</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Conversion-focused marketing sites built to last.</p>\n        </div>\n        <div>\n          <p className=\"font-['Courier_New',ui-monospace,monospace] text-4xl font-bold text-violet-200\">05</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Motion & video</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Brand films, product demos, and social content.</p>\n        </div>\n        <div>\n          <p className=\"font-['Courier_New',ui-monospace,monospace] text-4xl font-bold text-violet-200\">06</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Packaging</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Shelf-ready design systems for physical products.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Work","About","Footer"]},{"name":"Work","path":"/work","slug":"work","sections":["Navbar","PageHeader","Work","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '51aa8eb3-9103-45bd-8bf8-a05359fc40f7'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-4 z-40 mx-auto max-w-4xl px-4\">\n      <nav className=\"flex items-center justify-between gap-4 rounded-full border border-slate-200 bg-white/95 px-6 py-3 shadow-sm backdrop-blur\">\n        <a href=\"/\" className=\"font-['Georgia',ui-serif,serif] text-sm font-bold tracking-tight text-slate-900\">Foundry & Co</a>\n        <div className=\"hidden items-center gap-6 md:flex\">\n          <a href=\"/work\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Work</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-full bg-sky-600 px-4 py-1.5 text-xs font-semibold text-white hover:bg-sky-700 transition-colors\">Get started</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"relative overflow-hidden bg-gradient-to-br from-sky-600 via-sky-500 to-fuchsia-500 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-24 md:py-32\">\n        <div className=\"max-w-2xl\">\n          <span className=\"inline-block rounded-full bg-white/15 px-3 py-1 text-xs font-semibold uppercase tracking-tight\">CREATIVE AGENCY</span>\n          <h1 className=\"font-['Georgia',ui-serif,serif] mt-5 text-5xl md:text-6xl font-bold leading-[1.05] tracking-tight\">Small studio, senior team, no handoffs.</h1>\n          <p className=\"mt-5 max-w-lg text-lg text-white/80\">The people who pitch your project are the people who ship it.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-md bg-white px-6 py-3 text-sm font-semibold text-sky-700 hover:bg-white/90 transition-colors\">Start now</a>\n            <a href=\"#more\" className=\"rounded-md border border-white/40 px-6 py-3 text-sm font-semibold text-white hover:border-white transition-colors\">View details</a>\n          </div>\n        </div>\n        <div className=\"mt-16 hidden max-w-sm rounded-md border border-white/20 bg-white/10 p-6 backdrop-blur md:block\">\n          <p className=\"text-sm text-white/70\">Trusted by teams who need it to just work.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-white\">\n      <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-4 border-t border-slate-100 px-6 py-10 text-center\">\n        <p className=\"font-['Georgia',ui-serif,serif] text-base font-bold tracking-tight text-slate-900\">Foundry & Co</p>\n        <div className=\"flex flex-wrap items-center justify-center gap-6\">\n          <a href=\"/work\" className=\"text-sm text-slate-500 hover:text-slate-900\">Work</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a>\n        </div>\n        <p className=\"text-xs text-slate-400\">&copy; {new Date().getFullYear()} Foundry & Co &middot; Built with <span className=\"text-sky-600\">webma</span></p>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto grid max-w-5xl gap-10 px-6 py-20 md:grid-cols-2\">\n        <div>\n          <h2 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Get in touch</h2>\n          <p className=\"mt-3 text-slate-500\">Questions, quotes, or just saying hello — we'd love to hear from you.</p>\n          <div className=\"mt-8 space-y-4 text-sm text-slate-600\">\n            <p><span className=\"font-semibold text-slate-900\">Address</span><br />123 Market Street, Suite 400</p>\n            <p><span className=\"font-semibold text-slate-900\">Hours</span><br />Mon–Fri, 9am–6pm</p>\n          </div>\n        </div>\n        <form className=\"space-y-4 rounded-md border border-slate-200 bg-white p-6\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n          <input name=\"name\" required placeholder=\"Your name\" className=\"w-full rounded-md border border-slate-200 px-4 py-2.5 text-sm focus:border-sky-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full rounded-md border border-slate-200 px-4 py-2.5 text-sm focus:border-sky-500 focus:outline-none\" />\n          <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-md border border-slate-200 px-4 py-2.5 text-sm focus:border-sky-500 focus:outline-none\" />\n          <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n          <button type=\"submit\" className=\"w-full rounded-md bg-sky-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-sky-700 transition-colors\">Send message</button>\n        </form>\n      </div>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"border-b border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Work</h1>\n        <p className=\"mt-3 max-w-xl text-slate-500\">Everything you need to know about how we approach creative agency.</p>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"grid items-center gap-12 md:grid-cols-2\">\n        <div className=\"aspect-[4/3] rounded-md bg-gradient-to-br from-sky-50 to-fuchsia-50 md:order-2\" />\n        <div>\n          <h2 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">About Foundry & Co</h2>\n          <p className=\"mt-4 text-slate-600\">Behind Foundry & Co is a small, focused team that cares more about doing the work right than doing a lot of it. That's shaped everything about how we operate.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Work.tsx":"import { Zap, Star, Shield, Sparkles, Target, Heart, Award, TrendingUp, Users, Clock, CheckCircle, Compass } from \"lucide-react\";\n\nexport default function Work() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-4xl px-6 py-20\">\n        <h2 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Selected work</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Foundry & Co does best.</p>\n        <div className=\"mt-10 divide-y divide-slate-200\">\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-md bg-white text-sky-600 shadow-sm\"><Zap size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Brand identity</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Full rebrand systems, from logo to voice.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-md bg-white text-sky-600 shadow-sm\"><Star size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Product design</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">End-to-end UX for apps people actually enjoy using.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-md bg-white text-sky-600 shadow-sm\"><Shield size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Campaign strategy</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Launch campaigns across print, digital, and social.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-md bg-white text-sky-600 shadow-sm\"><Sparkles size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Web design</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Conversion-focused marketing sites built to last.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-md bg-white text-sky-600 shadow-sm\"><Target size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Motion & video</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Brand films, product demos, and social content.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-md bg-white text-sky-600 shadow-sm\"><Heart size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Packaging</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Shelf-ready design systems for physical products.</p>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Work","About","Footer"]},{"name":"Work","path":"/work","slug":"work","sections":["Navbar","PageHeader","Work","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '6695b58d-84a1-44c1-bfec-e090175662fe'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"bg-rose-600\">\n      <nav className=\"mx-auto flex max-w-6xl flex-wrap items-center justify-between gap-4 px-6 py-4\">\n        <a href=\"/\" className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-lg font-bold tracking-tighter text-white\">Halo Creative</a>\n        <div className=\"flex items-center gap-6\">\n          <a href=\"/work\" className=\"text-sm font-medium text-white/80 hover:text-white transition-colors\">Work</a>\n          <a href=\"/contact\" className=\"text-sm font-medium text-white/80 hover:text-white transition-colors\">Contact</a>\n          <a href=\"/contact\" className=\"rounded-none bg-white px-4 py-2 text-sm font-semibold text-rose-700 hover:bg-white/90 transition-colors\">Contact</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-2 md:py-32\">\n        <div>\n          \n          <h1 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] mt-5 text-5xl md:text-7xl font-bold leading-[1.05] tracking-tighter text-slate-900\">Design that does more than look good.</h1>\n          <p className=\"mt-5 max-w-lg text-lg text-slate-600\">Halo ties every creative decision back to a business outcome.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-none bg-rose-600 px-6 py-3 text-sm font-semibold text-white hover:bg-rose-700 transition-colors\">Get started</a>\n            <a href=\"#more\" className=\"rounded-none border border-slate-200 px-6 py-3 text-sm font-semibold text-slate-700 hover:border-slate-400 transition-colors\">See how it works</a>\n          </div>\n        </div>\n        <div className=\"aspect-[4/3] rounded-none bg-gradient-to-br from-rose-100 via-rose-50 to-slate-50 ring-1 ring-rose-100\" />\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"border-t border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto flex max-w-6xl flex-col gap-8 px-6 py-14 md:flex-row md:items-start md:justify-between\">\n        <div className=\"max-w-sm\">\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-lg font-bold tracking-tighter text-slate-900\">Halo Creative</p>\n          <p className=\"mt-2 text-sm text-slate-500\">Halo ties every creative decision back to a business outcome.</p>\n        </div>\n        <div className=\"flex gap-8\">\n          <a href=\"/work\" className=\"text-sm text-slate-500 hover:text-slate-900\">Work</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a>\n        </div>\n      </div>\n      <div className=\"border-t border-slate-200\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center justify-between gap-3 px-6 py-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Halo Creative. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-rose-600\"><span className=\"h-1.5 w-1.5 rounded-full bg-rose-600\" /> Built with webma</div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto grid max-w-5xl gap-10 px-6 py-20 md:grid-cols-2\">\n        <div>\n          <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Get in touch</h2>\n          <p className=\"mt-3 text-slate-500\">Questions, quotes, or just saying hello — we'd love to hear from you.</p>\n          <div className=\"mt-8 space-y-4 text-sm text-slate-600\">\n            <p><span className=\"font-semibold text-slate-900\">Address</span><br />123 Market Street, Suite 400</p>\n            <p><span className=\"font-semibold text-slate-900\">Hours</span><br />Mon–Fri, 9am–6pm</p>\n          </div>\n        </div>\n        <form className=\"space-y-4 rounded-none border border-slate-200 bg-white p-6\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n          <input name=\"name\" required placeholder=\"Your name\" className=\"w-full rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-rose-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-rose-500 focus:outline-none\" />\n          <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-rose-500 focus:outline-none\" />\n          <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n          <button type=\"submit\" className=\"w-full rounded-none bg-rose-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-rose-700 transition-colors\">Send message</button>\n        </form>\n      </div>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14 text-center\">\n        <span className=\"text-xs font-semibold uppercase tracking-tighter text-rose-600\">Everything you need to know about how we approach creative agency.</span>\n        <h1 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] mx-auto mt-3 max-w-2xl text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Work</h1>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid gap-10 md:grid-cols-[1fr_1fr]\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold leading-tight tracking-tighter text-slate-900\">About Halo Creative</h2>\n        <div className=\"space-y-4\">\n          <p className=\"text-slate-600\">Behind Halo Creative is a small, focused team that cares more about doing the work right than doing a lot of it. That's shaped everything about how we operate.</p>\n          <div className=\"h-1 w-16 rounded-none bg-gradient-to-r from-rose-500 to-slate-500\" />\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Work.tsx":"export default function Work() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Selected work</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Halo Creative does best.</p>\n      </div>\n      <div className=\"mt-10 grid gap-8 sm:grid-cols-2 lg:grid-cols-3\">\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-4xl font-bold text-rose-200\">01</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Brand identity</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Full rebrand systems, from logo to voice.</p>\n        </div>\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-4xl font-bold text-rose-200\">02</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Product design</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">End-to-end UX for apps people actually enjoy using.</p>\n        </div>\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-4xl font-bold text-rose-200\">03</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Campaign strategy</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Launch campaigns across print, digital, and social.</p>\n        </div>\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-4xl font-bold text-rose-200\">04</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Web design</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Conversion-focused marketing sites built to last.</p>\n        </div>\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-4xl font-bold text-rose-200\">05</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Motion & video</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Brand films, product demos, and social content.</p>\n        </div>\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-4xl font-bold text-rose-200\">06</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Packaging</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Shelf-ready design systems for physical products.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Work","About","Footer"]},{"name":"Work","path":"/work","slug":"work","sections":["Navbar","PageHeader","Work","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = 'f045df87-a3f2-4b93-8da3-1a6b8fa616a3'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-0 z-40 border-b border-slate-100 bg-white/80 backdrop-blur\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-4\">\n        <a href=\"/\" className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-lg font-bold tracking-tighter text-slate-900\">Northlight Studio</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n          <a href=\"/work\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Work</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-none bg-rose-600 px-4 py-2 text-sm font-semibold text-white hover:bg-rose-700 transition-colors\">Get in touch</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-3xl px-6 py-28 text-center md:py-36\">\n        \n        <h1 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] mt-6 text-5xl md:text-7xl font-bold leading-[1.05] tracking-tighter\">We build brands people actually remember.</h1>\n        <p className=\"mx-auto mt-5 max-w-xl text-lg text-white/60\">Northlight partners with ambitious founders to design identities, products, and campaigns that don't blend in.</p>\n        <div className=\"mt-9 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-none bg-rose-500 px-7 py-3 text-sm font-semibold text-slate-950 hover:bg-rose-400 transition-colors\">Get started</a>\n          <a href=\"#more\" className=\"rounded-none border border-white/20 px-7 py-3 text-sm font-semibold hover:border-white/40 transition-colors\">See how it works</a>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-white\">\n      <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-4 border-t border-slate-100 px-6 py-10 text-center\">\n        <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-base font-bold tracking-tighter text-slate-900\">Northlight Studio</p>\n        <div className=\"flex flex-wrap items-center justify-center gap-6\">\n          <a href=\"/work\" className=\"text-sm text-slate-500 hover:text-slate-900\">Work</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a>\n        </div>\n        <p className=\"text-xs text-slate-400\">&copy; {new Date().getFullYear()} Northlight Studio &middot; Built with <span className=\"text-rose-600\">webma</span></p>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-xl px-6 py-24 text-center\">\n      <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Questions, quotes, or just saying hello — we'd love to hear from you.</p>\n      <form className=\"mt-10 space-y-3 text-left\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <input name=\"name\" required placeholder=\"Your name\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-rose-500 focus:outline-none\" />\n        <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-rose-500 focus:outline-none\" />\n        <textarea name=\"message\" required rows={3} placeholder=\"How can we help?\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-rose-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"mt-4 w-full rounded-none bg-rose-600 px-6 py-3 text-sm font-semibold text-white hover:bg-rose-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"border-b border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Work</h1>\n        <p className=\"mt-3 max-w-xl text-slate-500\">Everything you need to know about how we approach creative agency.</p>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"grid items-center gap-12 md:grid-cols-2\">\n        <div className=\"aspect-[4/3] rounded-none bg-gradient-to-br from-rose-50 to-slate-50 \" />\n        <div>\n          <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">About Northlight Studio</h2>\n          <p className=\"mt-4 text-slate-600\">Northlight Studio pairs real experience in creative agency with a genuine focus on the people we work with — no jargon, no unnecessary steps, just results.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Work.tsx":"export default function Work() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Selected work</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Northlight Studio does best.</p>\n      </div>\n      <div className=\"mt-10 space-y-14\">\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-none bg-gradient-to-br from-rose-100 to-slate-50 \" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Brand identity</h3>\n            <p className=\"mt-2 text-slate-500\">Full rebrand systems, from logo to voice.</p>\n          </div>\n        </div>\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-none bg-gradient-to-br from-slate-100 to-rose-50 md:order-2\" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Product design</h3>\n            <p className=\"mt-2 text-slate-500\">End-to-end UX for apps people actually enjoy using.</p>\n          </div>\n        </div>\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-none bg-gradient-to-br from-rose-100 to-slate-50 \" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Campaign strategy</h3>\n            <p className=\"mt-2 text-slate-500\">Launch campaigns across print, digital, and social.</p>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Work","About","Footer"]},{"name":"Work","path":"/work","slug":"work","sections":["Navbar","PageHeader","Work","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = 'a73ba213-7558-422b-8624-dd1ebf3bc868'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-0 z-40 border-b border-slate-100 bg-white/80 backdrop-blur\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-4\">\n        <a href=\"/\" className=\"font-sans text-lg font-bold tracking-wide text-slate-900\">Greystone Studio</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n          <a href=\"/work\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Work</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-full bg-amber-600 px-4 py-2 text-sm font-semibold text-white hover:bg-amber-700 transition-colors\">Get in touch</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-2 md:py-32\">\n        <div>\n          <span className=\"inline-block rounded-full bg-amber-100 px-3 py-1 text-xs font-semibold uppercase tracking-wide text-amber-700\">ARCHITECTURE</span>\n          <h1 className=\"font-sans mt-5 text-4xl md:text-5xl font-bold leading-[1.05] tracking-wide text-slate-900\">Modern forms, grounded materials.</h1>\n          <p className=\"mt-5 max-w-lg text-lg text-slate-600\">Greystone's work reads as calm, not loud.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-full bg-amber-600 px-6 py-3 text-sm font-semibold text-white hover:bg-amber-700 transition-colors\">Start now</a>\n            <a href=\"#more\" className=\"rounded-full border border-slate-200 px-6 py-3 text-sm font-semibold text-slate-700 hover:border-slate-400 transition-colors\">View details</a>\n          </div>\n        </div>\n        <div className=\"aspect-[4/3] rounded-3xl bg-gradient-to-br from-amber-100 via-amber-50 to-slate-50 ring-1 ring-amber-100\" />\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <div className=\"grid gap-10 md:grid-cols-[1.2fr_1fr]\">\n          <div>\n            <p className=\"font-sans text-xl font-bold tracking-wide\">Greystone Studio</p>\n            <p className=\"mt-2 max-w-sm text-sm text-white/50\">Greystone's work reads as calm, not loud.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wide text-white/40\">Stay in the loop</p>\n            <form className=\"mt-3 flex gap-2\" onSubmit={(e) => e.preventDefault()}>\n              <input type=\"email\" required placeholder=\"you@email.com\" className=\"w-full rounded-3xl border border-white/15 bg-white/5 px-4 py-2.5 text-sm text-white placeholder:text-white/30 focus:border-amber-400 focus:outline-none\" />\n              <button type=\"submit\" className=\"rounded-full bg-amber-500 px-5 py-2.5 text-sm font-semibold text-slate-950 hover:bg-amber-400 transition-colors\">Join</button>\n            </form>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-3 border-t border-white/10 pt-6 text-xs text-white/40 sm:flex-row\">\n          <div className=\"flex gap-6\">\n            <a href=\"/work\" className=\"hover:text-white\">Work</a>\n            <a href=\"/contact\" className=\"hover:text-white\">Contact</a>\n          </div>\n          <p>&copy; {new Date().getFullYear()} Greystone Studio</p>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-xl px-6 py-24 text-center\">\n      <h2 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Questions, quotes, or just saying hello — we'd love to hear from you.</p>\n      <form className=\"mt-10 space-y-3 text-left\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <input name=\"name\" required placeholder=\"Your name\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-amber-500 focus:outline-none\" />\n        <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-amber-500 focus:outline-none\" />\n        <textarea name=\"message\" required rows={3} placeholder=\"How can we help?\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-amber-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"mt-4 w-full rounded-full bg-amber-600 px-6 py-3 text-sm font-semibold text-white hover:bg-amber-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"border-b border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">Work</h1>\n        <p className=\"mt-3 max-w-xl text-slate-500\">Everything you need to know about how we approach architecture.</p>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"grid items-center gap-12 md:grid-cols-2\">\n        <div className=\"aspect-[4/3] rounded-3xl bg-gradient-to-br from-amber-50 to-slate-50 \" />\n        <div>\n          <h2 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">About Greystone Studio</h2>\n          <p className=\"mt-4 text-slate-600\">We started Greystone Studio because the existing options in architecture were either too slow or too generic. Every decision here is made with our clients' actual outcomes in mind.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-2xl px-6 py-20\">\n        <div className=\"rounded-3xl border border-slate-200 bg-white p-8 shadow-sm\">\n          <div className=\"flex gap-0.5 text-amber-500\">{\"★★★★★\"}</div>\n          <p className=\"mt-4 text-lg text-slate-700\">&ldquo;Space planning integrated from the ground up. That's exactly what Greystone Studio delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Alina Novak <span className=\"font-normal text-slate-400\">— Client</span></p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"export default function Features() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">What Greystone Studio offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Greystone Studio does best.</p>\n      </div>\n      <div className=\"mt-10 grid gap-8 sm:grid-cols-2 lg:grid-cols-3\">\n        <div>\n          <p className=\"font-sans text-4xl font-bold text-amber-200\">01</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Residential design</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">New builds and full-home renovations.</p>\n        </div>\n        <div>\n          <p className=\"font-sans text-4xl font-bold text-amber-200\">02</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Commercial projects</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Retail, office, and mixed-use developments.</p>\n        </div>\n        <div>\n          <p className=\"font-sans text-4xl font-bold text-amber-200\">03</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Interior architecture</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Space planning integrated from the ground up.</p>\n        </div>\n        <div>\n          <p className=\"font-sans text-4xl font-bold text-amber-200\">04</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Sustainable design</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Passive-house and net-zero project experience.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Features","About","Testimonial","Footer"]},{"name":"Work","path":"/work","slug":"work","sections":["Navbar","PageHeader","Features","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ 