UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"border-b border-slate-100 bg-white\">\n      <nav className=\"mx-auto grid max-w-6xl grid-cols-3 items-center px-6 py-5\">\n        <div className=\"flex items-center gap-6\">\n          <a href=\"/work\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Work</a>\n        </div>\n        <a href=\"/\" className=\"font-sans text-center text-xl font-bold tracking-wide text-slate-900\">Holt Architecture</a>\n        <div className=\"flex items-center justify-end gap-6\">\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n          <a href=\"/contact\" className=\"text-sm font-semibold text-slate-600 hover:text-slate-700\">Contact →</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-[0.9fr_1.1fr] md:py-28\">\n        <div className=\"aspect-square rounded-3xl bg-gradient-to-tr from-amber-100 to-slate-100 ring-1 ring-slate-100 md:order-1\" />\n        <div className=\"md:order-2\">\n          <span className=\"text-xs font-semibold uppercase tracking-wide text-slate-600\">ARCHITECTURE</span>\n          <h1 className=\"font-sans mt-3 text-4xl md:text-5xl font-bold leading-[1.02] tracking-wide text-slate-900\">Buildings that respond to how people actually live.</h1>\n          <p className=\"mt-5 max-w-md text-lg text-slate-600\">Holt designs from the inside out — function first, form following closely behind.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-full bg-slate-600 px-6 py-3 text-sm font-semibold text-white hover:bg-slate-700 transition-colors\">Start now</a>\n            <a href=\"#more\" className=\"text-sm font-semibold text-slate-700 underline decoration-slate-300 underline-offset-4 hover:decoration-slate-600\">View details</a>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <div className=\"grid gap-10 md:grid-cols-[1.2fr_1fr]\">\n          <div>\n            <p className=\"font-sans text-xl font-bold tracking-wide\">Holt Architecture</p>\n            <p className=\"mt-2 max-w-sm text-sm text-white/50\">Holt designs from the inside out — function first, form following closely behind.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wide text-white/40\">Stay in the loop</p>\n            <form className=\"mt-3 flex gap-2\" onSubmit={(e) => e.preventDefault()}>\n              <input type=\"email\" required placeholder=\"you@email.com\" className=\"w-full rounded-3xl border border-white/15 bg-white/5 px-4 py-2.5 text-sm text-white placeholder:text-white/30 focus:border-slate-400 focus:outline-none\" />\n              <button type=\"submit\" className=\"rounded-full bg-slate-500 px-5 py-2.5 text-sm font-semibold text-slate-950 hover:bg-slate-400 transition-colors\">Join</button>\n            </form>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-3 border-t border-white/10 pt-6 text-xs text-white/40 sm:flex-row\">\n          <div className=\"flex gap-6\">\n            <a href=\"/work\" className=\"hover:text-white\">Work</a>\n            <a href=\"/contact\" className=\"hover:text-white\">Contact</a>\n          </div>\n          <p>&copy; {new Date().getFullYear()} Holt Architecture</p>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-xl px-6 py-24 text-center\">\n      <h2 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Questions, quotes, or just saying hello — we'd love to hear from you.</p>\n      <form className=\"mt-10 space-y-3 text-left\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <input name=\"name\" required placeholder=\"Your name\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-slate-500 focus:outline-none\" />\n        <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-slate-500 focus:outline-none\" />\n        <textarea name=\"message\" required rows={3} placeholder=\"How can we help?\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-slate-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"mt-4 w-full rounded-full bg-slate-600 px-6 py-3 text-sm font-semibold text-white hover:bg-slate-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-slate-600 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide\">Work</h1>\n        <p className=\"mt-3 max-w-xl text-white/75\">Everything you need to know about how we approach architecture.</p>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid gap-10 md:grid-cols-[1fr_1fr]\">\n        <h2 className=\"font-sans text-2xl md:text-3xl font-bold leading-tight tracking-wide text-slate-900\">About Holt Architecture</h2>\n        <div className=\"space-y-4\">\n          <p className=\"text-slate-600\">Behind Holt Architecture is a small, focused team that cares more about doing the work right than doing a lot of it. That's shaped everything about how we operate.</p>\n          <div className=\"h-1 w-16 rounded-3xl bg-gradient-to-r from-slate-500 to-amber-500\" />\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid items-center gap-10 md:grid-cols-[0.8fr_1.2fr]\">\n        <div className=\"aspect-square rounded-3xl bg-gradient-to-br from-slate-100 to-amber-100\" />\n        <div>\n          <p className=\"font-sans text-2xl font-medium leading-snug text-slate-900\">&ldquo;Space planning integrated from the ground up. That's exactly what Holt Architecture delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Sofia Reyes</p>\n          <p className=\"text-xs text-slate-500\">Head of Growth</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"export default function Features() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">What Holt Architecture offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Holt Architecture does best.</p>\n      </div>\n      <div className=\"mt-10 space-y-14\">\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-3xl bg-gradient-to-br from-slate-100 to-amber-50 \" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Residential design</h3>\n            <p className=\"mt-2 text-slate-500\">New builds and full-home renovations.</p>\n          </div>\n        </div>\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-3xl bg-gradient-to-br from-amber-100 to-slate-50 md:order-2\" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Commercial projects</h3>\n            <p className=\"mt-2 text-slate-500\">Retail, office, and mixed-use developments.</p>\n          </div>\n        </div>\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-3xl bg-gradient-to-br from-slate-100 to-amber-50 \" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Interior architecture</h3>\n            <p className=\"mt-2 text-slate-500\">Space planning integrated from the ground up.</p>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Features","About","Testimonial","Footer"]},{"name":"Work","path":"/work","slug":"work","sections":["Navbar","PageHeader","Features","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = 'ec551d18-da79-453e-b09b-fbf3ca8e3b32'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-0 z-40 border-b border-slate-100 bg-white/80 backdrop-blur\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-4\">\n        <a href=\"/\" className=\"font-['Verdana',ui-sans-serif,sans-serif] text-lg font-bold tracking-tight text-slate-900\">Linea Design Office</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n          <a href=\"/work\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Work</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-full bg-violet-600 px-4 py-2 text-sm font-semibold text-white hover:bg-violet-700 transition-colors\">Get in touch</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-[0.9fr_1.1fr] md:py-28\">\n        <div className=\"aspect-square rounded-2xl bg-gradient-to-tr from-lime-100 to-violet-100 ring-1 ring-violet-100 md:order-1\" />\n        <div className=\"md:order-2\">\n          <span className=\"text-xs font-semibold uppercase tracking-tight text-violet-600\">ARCHITECTURE</span>\n          <h1 className=\"font-['Verdana',ui-sans-serif,sans-serif] mt-3 text-4xl md:text-6xl font-bold leading-[1.02] tracking-tight text-slate-900\">Light, proportion, and restraint.</h1>\n          <p className=\"mt-5 max-w-md text-lg text-slate-600\">Linea's projects favor a few right decisions over a hundred small ones.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-full bg-violet-600 px-6 py-3 text-sm font-semibold text-white hover:bg-violet-700 transition-colors\">Talk to us</a>\n            <a href=\"#more\" className=\"text-sm font-semibold text-slate-700 underline decoration-slate-300 underline-offset-4 hover:decoration-slate-600\">See examples</a>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer>\n      <div className=\"bg-violet-600 text-white\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-4 px-6 py-14 text-center md:flex-row md:justify-between md:text-left\">\n          <h2 className=\"font-['Verdana',ui-sans-serif,sans-serif] text-3xl md:text-4xl font-bold tracking-tight\">Ready when you are.</h2>\n          <a href=\"/contact\" className=\"rounded-full bg-white px-6 py-3 text-sm font-semibold text-violet-700 hover:bg-white/90 transition-colors\">Get in touch</a>\n        </div>\n      </div>\n      <div className=\"bg-white\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center justify-between gap-3 px-6 py-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Linea Design Office</p>\n          <div className=\"flex gap-6\">\n            <a href=\"/work\" className=\"text-slate-500 hover:text-slate-900\">Work</a>\n            <a href=\"/contact\" className=\"text-slate-500 hover:text-slate-900\">Contact</a>\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto grid max-w-5xl gap-10 px-6 py-20 md:grid-cols-2\">\n        <div>\n          <h2 className=\"font-['Verdana',ui-sans-serif,sans-serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Get in touch</h2>\n          <p className=\"mt-3 text-slate-500\">Questions, quotes, or just saying hello — we'd love to hear from you.</p>\n          <div className=\"mt-8 space-y-4 text-sm text-slate-600\">\n            <p><span className=\"font-semibold text-slate-900\">Address</span><br />123 Market Street, Suite 400</p>\n            <p><span className=\"font-semibold text-slate-900\">Hours</span><br />Mon–Fri, 9am–6pm</p>\n          </div>\n        </div>\n        <form className=\"space-y-4 rounded-2xl border border-slate-200 bg-white p-6\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n          <input name=\"name\" required placeholder=\"Your name\" className=\"w-full rounded-2xl border border-slate-200 px-4 py-2.5 text-sm focus:border-violet-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full rounded-2xl border border-slate-200 px-4 py-2.5 text-sm focus:border-violet-500 focus:outline-none\" />\n          <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-2xl border border-slate-200 px-4 py-2.5 text-sm focus:border-violet-500 focus:outline-none\" />\n          <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n          <button type=\"submit\" className=\"w-full rounded-full bg-violet-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-violet-700 transition-colors\">Send message</button>\n        </form>\n      </div>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14 text-center\">\n        <span className=\"text-xs font-semibold uppercase tracking-tight text-violet-600\">Everything you need to know about how we approach architecture.</span>\n        <h1 className=\"font-['Verdana',ui-sans-serif,sans-serif] mx-auto mt-3 max-w-2xl text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Work</h1>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"grid items-center gap-12 md:grid-cols-2\">\n        <div className=\"aspect-[4/3] rounded-2xl bg-gradient-to-br from-violet-50 to-lime-50 md:order-2\" />\n        <div>\n          <h2 className=\"font-['Verdana',ui-sans-serif,sans-serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">About Linea Design Office</h2>\n          <p className=\"mt-4 text-slate-600\">Linea Design Office is built around one idea: architecture shouldn't be complicated. We keep things clear, direct, and focused on what actually moves the needle.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid items-center gap-10 md:grid-cols-[0.8fr_1.2fr]\">\n        <div className=\"aspect-square rounded-2xl bg-gradient-to-br from-violet-100 to-lime-100\" />\n        <div>\n          <p className=\"font-['Verdana',ui-sans-serif,sans-serif] text-2xl font-medium leading-snug text-slate-900\">&ldquo;New builds and full-home renovations. That's exactly what Linea Design Office delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Nadia Farouk</p>\n          <p className=\"text-xs text-slate-500\">Founder</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"export default function Features() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Verdana',ui-sans-serif,sans-serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">What Linea Design Office offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Linea Design Office does best.</p>\n      </div>\n      <div className=\"mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3\">\n        <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-violet-100 to-lime-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Residential design</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">New builds and full-home renovations.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-violet-100 to-lime-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Commercial projects</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Retail, office, and mixed-use developments.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-violet-100 to-lime-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Interior architecture</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Space planning integrated from the ground up.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-violet-100 to-lime-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Sustainable design</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Passive-house and net-zero project experience.</p>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Features","About","Testimonial","Footer"]},{"name":"Work","path":"/work","slug":"work","sections":["Navbar","PageHeader","Features","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = 'eb332fcc-b257-494f-953d-3a65c5bbf28e'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-0 z-40 border-b border-slate-100 bg-white/80 backdrop-blur\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-4\">\n        <a href=\"/\" className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-lg font-bold tracking-tighter text-slate-900\">Studio Lumen</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n          <a href=\"/services\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Services</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-none bg-teal-600 px-4 py-2 text-sm font-semibold text-white hover:bg-teal-700 transition-colors\">Get in touch</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-[0.9fr_1.1fr] md:py-28\">\n        <div className=\"aspect-square rounded-none bg-gradient-to-tr from-rose-100 to-teal-100 ring-1 ring-teal-100 md:order-1\" />\n        <div className=\"md:order-2\">\n          \n          <h1 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] mt-3 text-5xl md:text-7xl font-bold leading-[1.02] tracking-tighter text-slate-900\">Skincare that starts with a real consultation.</h1>\n          <p className=\"mt-5 max-w-md text-lg text-slate-600\">Studio Lumen builds every treatment around your skin, not a menu item.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-none bg-teal-600 px-6 py-3 text-sm font-semibold text-white hover:bg-teal-700 transition-colors\">Get in touch</a>\n            <a href=\"#more\" className=\"text-sm font-semibold text-slate-700 underline decoration-slate-300 underline-offset-4 hover:decoration-slate-600\">Explore</a>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <div className=\"grid gap-10 md:grid-cols-[1.2fr_1fr]\">\n          <div>\n            <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-xl font-bold tracking-tighter\">Studio Lumen</p>\n            <p className=\"mt-2 max-w-sm text-sm text-white/50\">Studio Lumen builds every treatment around your skin, not a menu item.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-tighter text-white/40\">Stay in the loop</p>\n            <form className=\"mt-3 flex gap-2\" onSubmit={(e) => e.preventDefault()}>\n              <input type=\"email\" required placeholder=\"you@email.com\" className=\"w-full rounded-none border border-white/15 bg-white/5 px-4 py-2.5 text-sm text-white placeholder:text-white/30 focus:border-teal-400 focus:outline-none\" />\n              <button type=\"submit\" className=\"rounded-none bg-teal-500 px-5 py-2.5 text-sm font-semibold text-slate-950 hover:bg-teal-400 transition-colors\">Join</button>\n            </form>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-3 border-t border-white/10 pt-6 text-xs text-white/40 sm:flex-row\">\n          <div className=\"flex gap-6\">\n            <a href=\"/services\" className=\"hover:text-white\">Services</a>\n            <a href=\"/contact\" className=\"hover:text-white\">Contact</a>\n          </div>\n          <p>&copy; {new Date().getFullYear()} Studio Lumen</p>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Questions, quotes, or just saying hello — we'd love to hear from you.</p>\n      <form className=\"mt-8 space-y-4\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-teal-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-teal-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-teal-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-none bg-teal-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-teal-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14 text-center\">\n        <span className=\"text-xs font-semibold uppercase tracking-tighter text-teal-600\">Everything you need to know about how we approach beauty.</span>\n        <h1 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] mx-auto mt-3 max-w-2xl text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Services</h1>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid gap-10 md:grid-cols-[1fr_1fr]\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold leading-tight tracking-tighter text-slate-900\">About Studio Lumen</h2>\n        <div className=\"space-y-4\">\n          <p className=\"text-slate-600\">Behind Studio Lumen is a small, focused team that cares more about doing the work right than doing a lot of it. That's shaped everything about how we operate.</p>\n          <div className=\"h-1 w-16 rounded-none bg-gradient-to-r from-teal-500 to-rose-500\" />\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid items-center gap-10 md:grid-cols-[0.8fr_1.2fr]\">\n        <div className=\"aspect-square rounded-none bg-gradient-to-br from-teal-100 to-rose-100\" />\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl font-medium leading-snug text-slate-900\">&ldquo;Hand-painted color, gloss finish. That's exactly what Studio Lumen delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Marcus Webb</p>\n          <p className=\"text-xs text-slate-500\">Head of Growth</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Location.tsx":"export default function Location() {\n  return (\n    <section className=\"bg-teal-600 text-white\">\n      <div className=\"mx-auto grid max-w-6xl gap-6 px-6 py-16 md:grid-cols-3\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl font-bold\">Visit us</h2>\n        <p className=\"text-sm text-white/85\">123 Market Street, Suite 400</p>\n        <p className=\"text-sm text-white/85\"><span className=\"font-semibold text-white\">Hours</span><br />Mon–Fri, 9am–6pm</p>\n      </div>\n    </section>\n  );\n}\n","components/Catalog.tsx":"import { Zap, Star, Shield, Sparkles, Target, Heart, Award, TrendingUp, Users, Clock, CheckCircle, Compass } from \"lucide-react\";\n\nexport default function Catalog() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-4xl px-6 py-20\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">What we offer</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Studio Lumen does best.</p>\n        <div className=\"mt-10 divide-y divide-slate-200\">\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-none bg-white text-teal-600 shadow-sm\"><Zap size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Signature facial</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">60 minutes, tailored to your skin.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-none bg-white text-teal-600 shadow-sm\"><Star size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Balayage & color</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Hand-painted color, gloss finish.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-none bg-white text-teal-600 shadow-sm\"><Shield size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Precision haircut</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Consultation included.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-none bg-white text-teal-600 shadow-sm\"><Sparkles size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Gel manicure</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Two-week wear, no chips.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-none bg-white text-teal-600 shadow-sm\"><Target size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Brow shaping & tint</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Wax or thread, your choice.</p>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","About","Testimonial","Footer"]},{"name":"Services","path":"/services","slug":"services","sections":["Navbar","PageHeader","Catalog","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Location","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '3a1aa6d9-3a29-41c3-94da-d96537e8959c'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-4 z-40 mx-auto max-w-4xl px-4\">\n      <nav className=\"flex items-center justify-between gap-4 rounded-full border border-slate-200 bg-white/95 px-6 py-3 shadow-sm backdrop-blur\">\n        <a href=\"/\" className=\"font-['Palatino',ui-serif,serif] text-sm font-bold tracking-normal text-slate-900\">The Powder Room</a>\n        <div className=\"hidden items-center gap-6 md:flex\">\n          <a href=\"/services\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Services</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-full bg-sky-600 px-4 py-1.5 text-xs font-semibold text-white hover:bg-sky-700 transition-colors\">Get started</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"relative overflow-hidden bg-gradient-to-br from-sky-600 via-sky-500 to-fuchsia-500 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-24 md:py-32\">\n        <div className=\"max-w-2xl\">\n          \n          <h1 className=\"font-['Palatino',ui-serif,serif] mt-5 text-4xl md:text-5xl font-bold leading-[1.05] tracking-normal\">Beauty, without the upsell.</h1>\n          <p className=\"mt-5 max-w-lg text-lg text-white/80\">Honest recommendations from people who actually use the products.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-lg bg-white px-6 py-3 text-sm font-semibold text-sky-700 hover:bg-white/90 transition-colors\">Get in touch</a>\n            <a href=\"#more\" className=\"rounded-lg border border-white/40 px-6 py-3 text-sm font-semibold text-white hover:border-white transition-colors\">Explore</a>\n          </div>\n        </div>\n        <div className=\"mt-16 hidden max-w-sm rounded-lg border border-white/20 bg-white/10 p-6 backdrop-blur md:block\">\n          <p className=\"text-sm text-white/70\">Trusted by teams who need it to just work.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <div className=\"grid gap-10 md:grid-cols-[1.2fr_1fr]\">\n          <div>\n            <p className=\"font-['Palatino',ui-serif,serif] text-xl font-bold tracking-normal\">The Powder Room</p>\n            <p className=\"mt-2 max-w-sm text-sm text-white/50\">Honest recommendations from people who actually use the products.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-normal text-white/40\">Stay in the loop</p>\n            <form className=\"mt-3 flex gap-2\" onSubmit={(e) => e.preventDefault()}>\n              <input type=\"email\" required placeholder=\"you@email.com\" className=\"w-full rounded-lg border border-white/15 bg-white/5 px-4 py-2.5 text-sm text-white placeholder:text-white/30 focus:border-sky-400 focus:outline-none\" />\n              <button type=\"submit\" className=\"rounded-lg bg-sky-500 px-5 py-2.5 text-sm font-semibold text-slate-950 hover:bg-sky-400 transition-colors\">Join</button>\n            </form>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-3 border-t border-white/10 pt-6 text-xs text-white/40 sm:flex-row\">\n          <div className=\"flex gap-6\">\n            <a href=\"/services\" className=\"hover:text-white\">Services</a>\n            <a href=\"/contact\" className=\"hover:text-white\">Contact</a>\n          </div>\n          <p>&copy; {new Date().getFullYear()} The Powder Room</p>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Questions, quotes, or just saying hello — we'd love to hear from you.</p>\n      <form className=\"mt-8 space-y-4\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-sky-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-sky-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-sky-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-lg bg-sky-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-sky-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14 text-center\">\n        <span className=\"text-xs font-semibold uppercase tracking-normal text-sky-600\">Everything you need to know about how we approach beauty.</span>\n        <h1 className=\"font-['Palatino',ui-serif,serif] mx-auto mt-3 max-w-2xl text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">Services</h1>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-3xl px-6 py-20 text-center\">\n        <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">About The Powder Room</h2>\n        <p className=\"mx-auto mt-4 max-w-xl text-slate-600\">The Powder Room pairs real experience in beauty with a genuine focus on the people we work with — no jargon, no unnecessary steps, just results.</p>\n        <div className=\"mx-auto mt-10 grid max-w-lg grid-cols-3 gap-6\">\n          <div><p className=\"text-2xl font-bold text-sky-600\">500+</p><p className=\"mt-1 text-xs uppercase tracking-normal text-slate-400\">Clients served</p></div>\n          <div><p className=\"text-2xl font-bold text-sky-600\">10 yrs</p><p className=\"mt-1 text-xs uppercase tracking-normal text-slate-400\">In business</p></div>\n          <div><p className=\"text-2xl font-bold text-sky-600\">4.9/5</p><p className=\"mt-1 text-xs uppercase tracking-normal text-slate-400\">Avg. rating</p></div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-2xl px-6 py-20\">\n        <div className=\"rounded-lg border border-slate-200 bg-white p-8 shadow-sm\">\n          <div className=\"flex gap-0.5 text-sky-500\">{\"★★★★★\"}</div>\n          <p className=\"mt-4 text-lg text-slate-700\">&ldquo;60 minutes, tailored to your skin. That's exactly what The Powder Room delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Nadia Farouk <span className=\"font-normal text-slate-400\">— General Manager</span></p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Location.tsx":"export default function Location() {\n  return (\n    <section className=\"bg-sky-600 text-white\">\n      <div className=\"mx-auto grid max-w-6xl gap-6 px-6 py-16 md:grid-cols-3\">\n        <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl font-bold\">Visit us</h2>\n        <p className=\"text-sm text-white/85\">123 Market Street, Suite 400</p>\n        <p className=\"text-sm text-white/85\"><span className=\"font-semibold text-white\">Hours</span><br />Mon–Fri, 9am–6pm</p>\n      </div>\n    </section>\n  );\n}\n","components/Catalog.tsx":"export default function Catalog() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">What we offer</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what The Powder Room does best.</p>\n      </div>\n      <div className=\"mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3\">\n        <div className=\"overflow-hidden rounded-lg border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-sky-100 to-fuchsia-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Signature facial</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">60 minutes, tailored to your skin.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-lg border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-sky-100 to-fuchsia-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Balayage & color</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Hand-painted color, gloss finish.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-lg border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-sky-100 to-fuchsia-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Precision haircut</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Consultation included.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-lg border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-sky-100 to-fuchsia-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Gel manicure</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Two-week wear, no chips.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-lg border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-sky-100 to-fuchsia-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Brow shaping & tint</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Wax or thread, your choice.</p>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","About","Testimonial","Footer"]},{"name":"Services","path":"/services","slug":"services","sections":["Navbar","PageHeader","Catalog","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Location","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = 'dfa03174-e9cf-40ee-bb72-f7af780434ad'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"border-b border-slate-100 bg-white\">\n      <nav className=\"mx-auto grid max-w-6xl grid-cols-3 items-center px-6 py-5\">\n        <div className=\"flex items-center gap-6\">\n          <a href=\"/services\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Services</a>\n        </div>\n        <a href=\"/\" className=\"font-sans text-center text-xl font-bold tracking-wide text-slate-900\">Willow & Co Salon</a>\n        <div className=\"flex items-center justify-end gap-6\">\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n          <a href=\"/contact\" className=\"text-sm font-semibold text-slate-600 hover:text-slate-700\">Contact →</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-2 md:py-32\">\n        <div>\n          <span className=\"inline-block rounded-full bg-slate-100 px-3 py-1 text-xs font-semibold uppercase tracking-wide text-slate-700\">BEAUTY</span>\n          <h1 className=\"font-sans mt-5 text-4xl md:text-5xl font-bold leading-[1.05] tracking-wide text-slate-900\">An hour that's actually about you.</h1>\n          <p className=\"mt-5 max-w-lg text-lg text-slate-600\">Willow & Co keeps appointments unhurried, on purpose.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-full bg-slate-600 px-6 py-3 text-sm font-semibold text-white hover:bg-slate-700 transition-colors\">Get started</a>\n            <a href=\"#more\" className=\"rounded-full border border-slate-200 px-6 py-3 text-sm font-semibold text-slate-700 hover:border-slate-400 transition-colors\">See how it works</a>\n          </div>\n        </div>\n        <div className=\"aspect-[4/3] rounded-3xl bg-gradient-to-br from-slate-100 via-slate-50 to-amber-50 ring-1 ring-slate-100\" />\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"border-t border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto flex max-w-6xl flex-col gap-8 px-6 py-14 md:flex-row md:items-start md:justify-between\">\n        <div className=\"max-w-sm\">\n          <p className=\"font-sans text-lg font-bold tracking-wide text-slate-900\">Willow & Co Salon</p>\n          <p className=\"mt-2 text-sm text-slate-500\">Willow & Co keeps appointments unhurried, on purpose.</p>\n        </div>\n        <div className=\"flex gap-8\">\n          <a href=\"/services\" className=\"text-sm text-slate-500 hover:text-slate-900\">Services</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a>\n        </div>\n      </div>\n      <div className=\"border-t border-slate-200\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center justify-between gap-3 px-6 py-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Willow & Co Salon. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-slate-600\"><span className=\"h-1.5 w-1.5 rounded-full bg-slate-600\" /> Built with webma</div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Questions, quotes, or just saying hello — we'd love to hear from you.</p>\n      <form className=\"mt-8 space-y-4\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-3xl border border-slate-200 px-4 py-2.5 text-sm focus:border-slate-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-3xl border border-slate-200 px-4 py-2.5 text-sm focus:border-slate-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-3xl border border-slate-200 px-4 py-2.5 text-sm focus:border-slate-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-full bg-slate-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-slate-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"border-b border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">Services</h1>\n        <p className=\"mt-3 max-w-xl text-slate-500\">Everything you need to know about how we approach beauty.</p>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"grid items-center gap-12 md:grid-cols-2\">\n        <div className=\"aspect-[4/3] rounded-3xl bg-gradient-to-br from-slate-50 to-amber-50 \" />\n        <div>\n          <h2 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">About Willow & Co Salon</h2>\n          <p className=\"mt-4 text-slate-600\">We started Willow & Co Salon because the existing options in beauty were either too slow or too generic. Every decision here is made with our clients' actual outcomes in mind.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-3xl px-6 py-20 text-center\">\n      <p className=\"font-sans text-2xl md:text-3xl font-medium leading-snug text-slate-900\">&ldquo;Consultation included. That's exactly what Willow & Co Salon delivered.&rdquo;</p>\n      <div className=\"mt-6 flex items-center justify-center gap-3\">\n        <div className=\"h-10 w-10 rounded-3xl bg-slate-100\" />\n        <div className=\"text-left\">\n          <p className=\"text-sm font-semibold text-slate-900\">Marcus Webb</p>\n          <p className=\"text-xs text-slate-500\">Client</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Location.tsx":"export default function Location() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 pb-20\">\n      <div className=\"grid gap-6 rounded-3xl border border-slate-100 p-8 md:grid-cols-2\">\n        <div>\n          <h2 className=\"text-xl font-bold text-slate-900\">Visit us</h2>\n          <p className=\"mt-3 text-sm text-slate-600\">123 Market Street, Suite 400</p>\n          <p className=\"mt-4 text-xs font-semibold uppercase tracking-wider text-slate-600\">Hours</p>\n          <p className=\"mt-1 text-sm text-slate-500\">Mon–Fri, 9am–6pm</p>\n        </div>\n        <div className=\"aspect-[4/3] rounded-3xl bg-gradient-to-br from-slate-100 to-slate-50\" />\n      </div>\n    </section>\n  );\n}\n","components/Catalog.tsx":"export default function Catalog() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">What we offer</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Willow & Co Salon does best.</p>\n      </div>\n      <div className=\"mt-10 grid gap-8 sm:grid-cols-2 lg:grid-cols-3\">\n        <div>\n          <p className=\"font-sans text-4xl font-bold text-slate-200\">01</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Signature facial</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">60 minutes, tailored to your skin.</p>\n        </div>\n        <div>\n          <p className=\"font-sans text-4xl font-bold text-slate-200\">02</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Balayage & color</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Hand-painted color, gloss finish.</p>\n        </div>\n        <div>\n          <p className=\"font-sans text-4xl font-bold text-slate-200\">03</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Precision haircut</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Consultation included.</p>\n        </div>\n        <div>\n          <p className=\"font-sans text-4xl font-bold text-slate-200\">04</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Gel manicure</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Two-week wear, no chips.</p>\n        </div>\n        <div>\n          <p className=\"font-sans text-4xl font-bold text-slate-200\">05</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Brow shaping & tint</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Wax or thread, your choice.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","About","Testimonial","Footer"]},{"name":"Services","path":"/services","slug":"services","sections":["Navbar","PageHeader","Catalog","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Location","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = 'b6ac594c-07ac-4ca9-9db8-a5794dd3524a'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"border-b border-slate-100 bg-white\">\n      <nav className=\"mx-auto grid max-w-6xl grid-cols-3 items-center px-6 py-5\">\n        <div className=\"flex items-center gap-6\">\n          <a href=\"/archive\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Archive</a>\n        </div>\n        <a href=\"/\" className=\"font-['Verdana',ui-sans-serif,sans-serif] text-center text-xl font-bold tracking-tight text-slate-900\">Field Notes</a>\n        <div className=\"flex items-center justify-end gap-6\">\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Subscribe</a>\n          <a href=\"/contact\" className=\"text-sm font-semibold text-rose-600 hover:text-rose-700\">Contact →</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-3xl px-6 py-28 text-center md:py-36\">\n        <span className=\"inline-block rounded-full border border-white/15 px-3 py-1 text-xs font-semibold uppercase tracking-tight text-rose-300\">PUBLISHING</span>\n        <h1 className=\"font-['Verdana',ui-sans-serif,sans-serif] mt-6 text-4xl md:text-6xl font-bold leading-[1.05] tracking-tight\">Observations from actually doing the work.</h1>\n        <p className=\"mx-auto mt-5 max-w-xl text-lg text-white/60\">Less advice, more what happened and why.</p>\n        <div className=\"mt-9 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-full bg-rose-500 px-7 py-3 text-sm font-semibold text-slate-950 hover:bg-rose-400 transition-colors\">Get started</a>\n          <a href=\"#more\" className=\"rounded-full border border-white/20 px-7 py-3 text-sm font-semibold hover:border-white/40 transition-colors\">See how it works</a>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"border-t border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto flex max-w-6xl flex-col gap-8 px-6 py-14 md:flex-row md:items-start md:justify-between\">\n        <div className=\"max-w-sm\">\n          <p className=\"font-['Verdana',ui-sans-serif,sans-serif] text-lg font-bold tracking-tight text-slate-900\">Field Notes</p>\n          <p className=\"mt-2 text-sm text-slate-500\">Less advice, more what happened and why.</p>\n        </div>\n        <div className=\"flex gap-8\">\n          <a href=\"/archive\" className=\"text-sm text-slate-500 hover:text-slate-900\">Archive</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Subscribe</a>\n        </div>\n      </div>\n      <div className=\"border-t border-slate-200\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center justify-between gap-3 px-6 py-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Field Notes. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-rose-600\"><span className=\"h-1.5 w-1.5 rounded-full bg-rose-600\" /> Built with webma</div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-['Verdana',ui-sans-serif,sans-serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Questions, quotes, or just saying hello — we'd love to hear from you.</p>\n      <form className=\"mt-8 space-y-4\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-2xl border border-slate-200 px-4 py-2.5 text-sm focus:border-rose-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-2xl border border-slate-200 px-4 py-2.5 text-sm focus:border-rose-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-2xl border border-slate-200 px-4 py-2.5 text-sm focus:border-rose-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-full bg-rose-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-rose-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-rose-600 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-['Verdana',ui-sans-serif,sans-serif] text-3xl md:text-4xl font-bold tracking-tight\">Archive</h1>\n        <p className=\"mt-3 max-w-xl text-white/75\">Everything you need to know about how we approach publishing.</p>\n      </div>\n    </section>\n  );\n}\n","components/Latest.tsx":"export default function Latest() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Verdana',ui-sans-serif,sans-serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Latest updates</h2>\n        <p className=\"mt-3 text-slate-500\">Recent posts and announcements.</p>\n      </div>\n      <div className=\"mt-10 grid gap-8 sm:grid-cols-2 lg:grid-cols-3\">\n        <div>\n          <p className=\"font-['Verdana',ui-sans-serif,sans-serif] text-4xl font-bold text-rose-200\">01</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">On slow growth</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Why the compounding path beats the shortcut.</p>\n        </div>\n        <div>\n          <p className=\"font-['Verdana',ui-sans-serif,sans-serif] text-4xl font-bold text-rose-200\">02</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Notes from the field</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">What actually happened this quarter.</p>\n        </div>\n        <div>\n          <p className=\"font-['Verdana',ui-sans-serif,sans-serif] text-4xl font-bold text-rose-200\">03</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">A framework for decisions</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">The four questions worth asking first.</p>\n        </div>\n        <div>\n          <p className=\"font-['Verdana',ui-sans-serif,sans-serif] text-4xl font-bold text-rose-200\">04</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Reading list</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">What's been worth the time lately.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Latest","Footer"]},{"name":"Archive","path":"/archive","slug":"archive","sections":["Navbar","PageHeader","Latest","Footer"]},{"name":"Subscribe","path":"/contact","slug":"subscribe","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '6bb4394b-a133-49c1-86ec-af4b16050b0c'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"bg-orange-600\">\n      <nav className=\"mx-auto flex max-w-6xl flex-wrap items-center justify-between gap-4 px-6 py-4\">\n        <a href=\"/\" className=\"font-['Georgia',ui-serif,serif] text-lg font-bold tracking-tight text-white\">Marginalia</a>\n        <div className=\"flex items-center gap-6\">\n          <a href=\"/archive\" className=\"text-sm font-medium text-white/80 hover:text-white transition-colors\">Archive</a>\n          <a href=\"/contact\" className=\"text-sm font-medium text-white/80 hover:text-white transition-colors\">Subscribe</a>\n          <a href=\"/contact\" className=\"rounded-md bg-white px-4 py-2 text-sm font-semibold text-orange-700 hover:bg-white/90 transition-colors\">Contact</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-3xl px-6 py-28 text-center md:py-36\">\n        <span className=\"inline-block rounded-full border border-white/15 px-3 py-1 text-xs font-semibold uppercase tracking-tight text-orange-300\">PUBLISHING</span>\n        <h1 className=\"font-['Georgia',ui-serif,serif] mt-6 text-5xl md:text-6xl font-bold leading-[1.05] tracking-tight\">Ideas worth sitting with.</h1>\n        <p className=\"mx-auto mt-5 max-w-xl text-lg text-white/60\">A weekly essay on the questions everyone skips past.</p>\n        <div className=\"mt-9 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-md bg-orange-500 px-7 py-3 text-sm font-semibold text-slate-950 hover:bg-orange-400 transition-colors\">Talk to us</a>\n          <a href=\"#more\" className=\"rounded-md border border-white/20 px-7 py-3 text-sm font-semibold hover:border-white/40 transition-colors\">See examples</a>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <div className=\"grid gap-10 md:grid-cols-[1.2fr_1fr]\">\n          <div>\n            <p className=\"font-['Georgia',ui-serif,serif] text-xl font-bold tracking-tight\">Marginalia</p>\n            <p className=\"mt-2 max-w-sm text-sm text-white/50\">A weekly essay on the questions everyone skips past.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-tight text-white/40\">Stay in the loop</p>\n            <form className=\"mt-3 flex gap-2\" onSubmit={(e) => e.preventDefault()}>\n              <input type=\"email\" required placeholder=\"you@email.com\" className=\"w-full rounded-md border border-white/15 bg-white/5 px-4 py-2.5 text-sm text-white placeholder:text-white/30 focus:border-orange-400 focus:outline-none\" />\n              <button type=\"submit\" className=\"rounded-md bg-orange-500 px-5 py-2.5 text-sm font-semibold text-slate-950 hover:bg-orange-400 transition-colors\">Join</button>\n            </form>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-3 border-t border-white/10 pt-6 text-xs text-white/40 sm:flex-row\">\n          <div className=\"flex gap-6\">\n            <a href=\"/archive\" className=\"hover:text-white\">Archive</a>\n            <a href=\"/contact\" className=\"hover:text-white\">Subscribe</a>\n          </div>\n          <p>&copy; {new Date().getFullYear()} Marginalia</p>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-xl px-6 py-24 text-center\">\n      <h2 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Questions, quotes, or just saying hello — we'd love to hear from you.</p>\n      <form className=\"mt-10 space-y-3 text-left\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <input name=\"name\" required placeholder=\"Your name\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-orange-500 focus:outline-none\" />\n        <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-orange-500 focus:outline-none\" />\n        <textarea name=\"message\" required rows={3} placeholder=\"How can we help?\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-orange-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"mt-4 w-full rounded-md bg-orange-600 px-6 py-3 text-sm font-semibold text-white hover:bg-orange-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-orange-600 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold tracking-tight\">Archive</h1>\n        <p className=\"mt-3 max-w-xl text-white/75\">Everything you need to know about how we approach publishing.</p>\n      </div>\n    </section>\n  );\n}\n","components/Latest.tsx":"export default function Latest() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Latest updates</h2>\n        <p className=\"mt-3 text-slate-500\">Recent posts and announcements.</p>\n      </div>\n      <div className=\"mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3\">\n        <div className=\"overflow-hidden rounded-md border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-orange-100 to-indigo-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">On slow growth</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Why the compounding path beats the shortcut.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-md border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-orange-100 to-indigo-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Notes from the field</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">What actually happened this quarter.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-md border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-orange-100 to-indigo-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">A framework for decisions</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">The four questions worth asking first.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-md border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-orange-100 to-indigo-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Reading list</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">What's been worth the time lately.</p>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Latest","Footer"]},{"name":"Archive","path":"/archive","slug":"archive","sections":["Navbar","PageHeader","Latest","Footer"]},{"name":"Subscribe","path":"/contact","slug":"subscribe","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '2604fdd2-da7f-420e-9050-a20d1675fe91'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"border-b border-slate-100 bg-white\">\n      <nav className=\"mx-auto grid max-w-6xl grid-cols-3 items-center px-6 py-5\">\n        <div className=\"flex items-center gap-6\">\n          <a href=\"/archive\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Archive</a>\n        </div>\n        <a href=\"/\" className=\"font-['Palatino',ui-serif,serif] text-center text-xl font-bold tracking-normal text-slate-900\">The Long Game</a>\n        <div className=\"flex items-center justify-end gap-6\">\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Subscribe</a>\n          <a href=\"/contact\" className=\"text-sm font-semibold text-emerald-600 hover:text-emerald-700\">Contact →</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-2 md:py-32\">\n        <div>\n          \n          <h1 className=\"font-['Palatino',ui-serif,serif] mt-5 text-4xl md:text-5xl font-bold leading-[1.05] tracking-normal text-slate-900\">Writing on building things that last.</h1>\n          <p className=\"mt-5 max-w-lg text-lg text-slate-600\">Essays on strategy, craft, and the slow parts nobody posts about.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-lg bg-emerald-600 px-6 py-3 text-sm font-semibold text-white hover:bg-emerald-700 transition-colors\">Get started</a>\n            <a href=\"#more\" className=\"rounded-lg border border-slate-200 px-6 py-3 text-sm font-semibold text-slate-700 hover:border-slate-400 transition-colors\">See how it works</a>\n          </div>\n        </div>\n        <div className=\"aspect-[4/3] rounded-lg bg-gradient-to-br from-emerald-100 via-emerald-50 to-orange-50 ring-1 ring-emerald-100\" />\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"border-t border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto flex max-w-6xl flex-col gap-8 px-6 py-14 md:flex-row md:items-start md:justify-between\">\n        <div className=\"max-w-sm\">\n          <p className=\"font-['Palatino',ui-serif,serif] text-lg font-bold tracking-normal text-slate-900\">The Long Game</p>\n          <p className=\"mt-2 text-sm text-slate-500\">Essays on strategy, craft, and the slow parts nobody posts about.</p>\n        </div>\n        <div className=\"flex gap-8\">\n          <a href=\"/archive\" className=\"text-sm text-slate-500 hover:text-slate-900\">Archive</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Subscribe</a>\n        </div>\n      </div>\n      <div className=\"border-t border-slate-200\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center justify-between gap-3 px-6 py-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} The Long Game. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-emerald-600\"><span className=\"h-1.5 w-1.5 rounded-full bg-emerald-600\" /> Built with webma</div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Questions, quotes, or just saying hello — we'd love to hear from you.</p>\n      <form className=\"mt-8 space-y-4\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-emerald-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-emerald-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-emerald-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-lg bg-emerald-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-emerald-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"border-b border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">Archive</h1>\n        <p className=\"mt-3 max-w-xl text-slate-500\">Everything you need to know about how we approach publishing.</p>\n      </div>\n    </section>\n  );\n}\n","components/Latest.tsx":"export default function Latest() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">Latest updates</h2>\n        <p className=\"mt-3 text-slate-500\">Recent posts and announcements.</p>\n      </div>\n      <div className=\"mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3\">\n        <div className=\"overflow-hidden rounded-lg border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-emerald-100 to-orange-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">On slow growth</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Why the compounding path beats the shortcut.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-lg border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-emerald-100 to-orange-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Notes from the field</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">What actually happened this quarter.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-lg border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-emerald-100 to-orange-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">A framework for decisions</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">The four questions worth asking first.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-lg border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-emerald-100 to-orange-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Reading list</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">What's been worth the time lately.</p>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Latest","Footer"]},{"name":"Archive","path":"/archive","slug":"archive","sections":["Navbar","PageHeader","Latest","Footer"]},{"name":"Subscribe","path":"/contact","slug":"subscribe","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = 'd2a3c125-44a7-4d2c-9bc7-1ed1dd56eecc'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"bg-white\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-6\">\n        <a href=\"/\" className=\"font-['Courier_New',ui-monospace,monospace] text-base font-bold uppercase tracking-tight text-slate-900\">Ashcroft & Partners</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n          <a href=\"/services\" className=\"border-b-2 border-transparent pb-1 text-sm font-medium text-slate-500 hover:border-violet-500 hover:text-slate-900 transition-colors\">Services</a>\n          <a href=\"/contact\" className=\"border-b-2 border-transparent pb-1 text-sm font-medium text-slate-500 hover:border-violet-500 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"relative overflow-hidden bg-gradient-to-br from-violet-600 via-violet-500 to-lime-500 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-24 md:py-32\">\n        <div className=\"max-w-2xl\">\n          <span className=\"inline-block rounded-full bg-white/15 px-3 py-1 text-xs font-semibold uppercase tracking-tight\">CONSULTING</span>\n          <h1 className=\"font-['Courier_New',ui-monospace,monospace] mt-5 text-4xl md:text-5xl font-bold leading-[1.05] tracking-tight\">Decisions your board will actually stand behind.</h1>\n          <p className=\"mt-5 max-w-lg text-lg text-white/80\">Ashcroft brings rigor to the calls that are too important to get wrong.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-sm bg-white px-6 py-3 text-sm font-semibold text-violet-700 hover:bg-white/90 transition-colors\">Book a call</a>\n            <a href=\"#more\" className=\"rounded-sm border border-white/40 px-6 py-3 text-sm font-semibold text-white hover:border-white transition-colors\">Learn more</a>\n          </div>\n        </div>\n        <div className=\"mt-16 hidden max-w-sm rounded-sm border border-white/20 bg-white/10 p-6 backdrop-blur md:block\">\n          <p className=\"text-sm text-white/70\">Trusted by teams who need it to just work.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-white\">\n      <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-4 border-t border-slate-100 px-6 py-10 text-center\">\n        <p className=\"font-['Courier_New',ui-monospace,monospace] text-base font-bold tracking-tight text-slate-900\">Ashcroft & Partners</p>\n        <div className=\"flex flex-wrap items-center justify-center gap-6\">\n          <a href=\"/services\" className=\"text-sm text-slate-500 hover:text-slate-900\">Services</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a>\n        </div>\n        <p className=\"text-xs text-slate-400\">&copy; {new Date().getFullYear()} Ashcroft & Partners &middot; Built with <span className=\"text-violet-600\">webma</span></p>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto grid max-w-5xl gap-10 px-6 py-20 md:grid-cols-2\">\n        <div>\n          <h2 className=\"font-['Courier_New',ui-monospace,monospace] text-xl md:text-2xl font-bold tracking-tight text-slate-900\">Get in touch</h2>\n          <p className=\"mt-3 text-slate-500\">Questions, quotes, or just saying hello — we'd love to hear from you.</p>\n          <div className=\"mt-8 space-y-4 text-sm text-slate-600\">\n            <p><span className=\"font-semibold text-slate-900\">Address</span><br />123 Market Street, Suite 400</p>\n            <p><span className=\"font-semibold text-slate-900\">Hours</span><br />Mon–Fri, 9am–6pm</p>\n          </div>\n        </div>\n        <form className=\"space-y-4 rounded-sm border border-slate-200 bg-white p-6\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n          <input name=\"name\" required placeholder=\"Your name\" className=\"w-full rounded-sm border border-slate-200 px-4 py-2.5 text-sm focus:border-violet-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full rounded-sm border border-slate-200 px-4 py-2.5 text-sm focus:border-violet-500 focus:outline-none\" />\n          <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-sm border border-slate-200 px-4 py-2.5 text-sm focus:border-violet-500 focus:outline-none\" />\n          <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n          <button type=\"submit\" className=\"w-full rounded-sm bg-violet-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-violet-700 transition-colors\">Send message</button>\n        </form>\n      </div>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-violet-600 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-['Courier_New',ui-monospace,monospace] text-xl md:text-2xl font-bold tracking-tight\">Services</h1>\n        <p className=\"mt-3 max-w-xl text-white/75\">Real work, real results — see it for yourself.</p>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid gap-10 md:grid-cols-[1fr_1fr]\">\n        <h2 className=\"font-['Courier_New',ui-monospace,monospace] text-xl md:text-2xl font-bold leading-tight tracking-tight text-slate-900\">About Ashcroft & Partners</h2>\n        <div className=\"space-y-4\">\n          <p className=\"text-slate-600\">Ashcroft & Partners pairs real experience in consulting with a genuine focus on the people we work with — no jargon, no unnecessary steps, just results.</p>\n          <div className=\"h-1 w-16 rounded-sm bg-gradient-to-r from-violet-500 to-lime-500\" />\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-3xl px-6 py-20 text-center\">\n      <p className=\"font-['Courier_New',ui-monospace,monospace] text-xl md:text-2xl font-medium leading-snug text-slate-900\">&ldquo;Getting your team aligned behind the plan, not just informed of it. That's exactly what Ashcroft & Partners delivered.&rdquo;</p>\n      <div className=\"mt-6 flex items-center justify-center gap-3\">\n        <div className=\"h-10 w-10 rounded-sm bg-violet-100\" />\n        <div className=\"text-left\">\n          <p className=\"text-sm font-semibold text-slate-900\">Priya Shah</p>\n          <p className=\"text-xs text-slate-500\">Client</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"export default function Features() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Courier_New',ui-monospace,monospace] text-xl md:text-2xl font-bold tracking-tight text-slate-900\">What Ashcroft & Partners offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Ashcroft & Partners does best.</p>\n      </div>\n      <div className=\"mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3\">\n        <div className=\"overflow-hidden rounded-sm border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-violet-100 to-lime-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Strategy</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Market analysis, competitive positioning, and growth planning.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-sm border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-violet-100 to-lime-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Operations</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Process redesign that actually survives contact with reality.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-sm border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-violet-100 to-lime-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Change management</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Getting your team aligned behind the plan, not just informed of it.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-sm border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-violet-100 to-lime-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Financial planning</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Budgets and forecasts leadership can actually trust.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-sm border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-violet-100 to-lime-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Market entry</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Structured playbooks for entering a new region or segment.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-sm border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-violet-100 to-lime-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Risk assessment</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Identify what could go wrong before it does.</p>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Features","About","Testimonial","Footer"]},{"name":"Services","path":"/services","slug":"services","sections":["Navbar","PageHeader","Features","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '0571df3f-d07f-448a-b7d3-c82951f8d02a'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-4 z-40 mx-auto max-w-4xl px-4\">\n      <nav className=\"flex items-center justify-between gap-4 rounded-full border border-slate-200 bg-white/95 px-6 py-3 shadow-sm backdrop-blur\">\n        <a href=\"/\" className=\"font-['Palatino',ui-serif,serif] text-sm font-bold tracking-normal text-slate-900\">Kellerman Advisory</a>\n        <div className=\"hidden items-center gap-6 md:flex\">\n          <a href=\"/services\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Services</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-full bg-violet-600 px-4 py-1.5 text-xs font-semibold text-white hover:bg-violet-700 transition-colors\">Get started</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-[0.9fr_1.1fr] md:py-28\">\n        <div className=\"aspect-square rounded-lg bg-gradient-to-tr from-lime-100 to-violet-100 ring-1 ring-violet-100 md:order-1\" />\n        <div className=\"md:order-2\">\n          \n          <h1 className=\"font-['Palatino',ui-serif,serif] mt-3 text-4xl md:text-5xl font-bold leading-[1.02] tracking-normal text-slate-900\">The plan gets written with you, not for you.</h1>\n          <p className=\"mt-5 max-w-md text-lg text-slate-600\">Kellerman embeds with leadership until the strategy is actually theirs.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-lg bg-violet-600 px-6 py-3 text-sm font-semibold text-white hover:bg-violet-700 transition-colors\">Talk to us</a>\n            <a href=\"#more\" className=\"text-sm font-semibold text-slate-700 underline decoration-slate-300 underline-offset-4 hover:decoration-slate-600\">See examples</a>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"border-t border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto flex max-w-6xl flex-col gap-8 px-6 py-14 md:flex-row md:items-start md:justify-between\">\n        <div className=\"max-w-sm\">\n          <p className=\"font-['Palatino',ui-serif,serif] text-lg font-bold tracking-normal text-slate-900\">Kellerman Advisory</p>\n          <p className=\"mt-2 text-sm text-slate-500\">Kellerman embeds with leadership until the strategy is actually theirs.</p>\n        </div>\n        <div className=\"flex gap-8\">\n          <a href=\"/services\" className=\"text-sm text-slate-500 hover:text-slate-900\">Services</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a>\n        </div>\n      </div>\n      <div className=\"border-t border-slate-200\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center justify-between gap-3 px-6 py-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Kellerman Advisory. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-violet-600\"><span className=\"h-1.5 w-1.5 rounded-full bg-violet-600\" /> Built with webma</div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Questions, quotes, or just saying hello — we'd love to hear from you.</p>\n      <form className=\"mt-8 space-y-4\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-violet-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-violet-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-violet-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-lg bg-violet-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-violet-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"border-b border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">Services</h1>\n        <p className=\"mt-3 max-w-xl text-slate-500\">Real work, real results — see it for yourself.</p>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid gap-10 md:grid-cols-[1fr_1fr]\">\n        <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold leading-tight tracking-normal text-slate-900\">About Kellerman Advisory</h2>\n        <div className=\"space-y-4\">\n          <p className=\"text-slate-600\">Behind Kellerman Advisory is a small, focused team that cares more about doing the work right than doing a lot of it. That's shaped everything about how we operate.</p>\n          <div className=\"h-1 w-16 rounded-lg bg-gradient-to-r from-violet-500 to-lime-500\" />\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-2xl px-6 py-20\">\n        <div className=\"rounded-lg border border-slate-200 bg-white p-8 shadow-sm\">\n          <div className=\"flex gap-0.5 text-violet-500\">{\"★★★★★\"}</div>\n          <p className=\"mt-4 text-lg text-slate-700\">&ldquo;Process redesign that actually survives contact with reality. That's exactly what Kellerman Advisory delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Jordan Lee <span className=\"font-normal text-slate-400\">— Head of Growth</span></p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"export default function Features() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">What Kellerman Advisory offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Kellerman Advisory does best.</p>\n      </div>\n      <div className=\"mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3\">\n        <div className=\"overflow-hidden rounded-lg border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-violet-100 to-lime-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Strategy</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Market analysis, competitive positioning, and growth planning.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-lg border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-violet-100 to-lime-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Operations</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Process redesign that actually survives contact with reality.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-lg border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-violet-100 to-lime-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Change management</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Getting your team aligned behind the plan, not just informed of it.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-lg border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-violet-100 to-lime-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Financial planning</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Budgets and forecasts leadership can actually trust.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-lg border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-violet-100 to-lime-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Market entry</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Structured playbooks for entering a new region or segment.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-lg border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-violet-100 to-lime-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Risk assessment</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Identify what could go wrong before it does.</p>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Features","About","Testimonial","Footer"]},{"name":"Services","path":"/services","slug":"services","sections":["Navbar","PageHeader","Features","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '13803790-9314-457b-b462-d2855fcafaa5'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"bg-emerald-600\">\n      <nav className=\"mx-auto flex max-w-6xl flex-wrap items-center justify-between gap-4 px-6 py-4\">\n        <a href=\"/\" className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-lg font-bold tracking-tighter text-white\">Meridian Consulting</a>\n        <div className=\"flex items-center gap-6\">\n          <a href=\"/services\" className=\"text-sm font-medium text-white/80 hover:text-white transition-colors\">Services</a>\n          <a href=\"/contact\" className=\"text-sm font-medium text-white/80 hover:text-white transition-colors\">Contact</a>\n          <a href=\"/contact\" className=\"rounded-none bg-white px-4 py-2 text-sm font-semibold text-emerald-700 hover:bg-white/90 transition-colors\">Contact</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-3xl px-6 py-28 text-center md:py-36\">\n        \n        <h1 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] mt-6 text-5xl md:text-7xl font-bold leading-[1.05] tracking-tighter\">Clarity for complex decisions.</h1>\n        <p className=\"mx-auto mt-5 max-w-xl text-lg text-white/60\">Meridian helps mid-market leadership teams cut through noise and commit to a plan.</p>\n        <div className=\"mt-9 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-none bg-emerald-500 px-7 py-3 text-sm font-semibold text-slate-950 hover:bg-emerald-400 transition-colors\">Get started</a>\n          <a href=\"#more\" className=\"rounded-none border border-white/20 px-7 py-3 text-sm font-semibold hover:border-white/40 transition-colors\">See how it works</a>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-white\">\n      <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-4 border-t border-slate-100 px-6 py-10 text-center\">\n        <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-base font-bold tracking-tighter text-slate-900\">Meridian Consulting</p>\n        <div className=\"flex flex-wrap items-center justify-center gap-6\">\n          <a href=\"/services\" className=\"text-sm text-slate-500 hover:text-slate-900\">Services</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a>\n        </div>\n        <p className=\"text-xs text-slate-400\">&copy; {new Date().getFullYear()} Meridian Consulting &middot; Built with <span className=\"text-emerald-600\">webma</span></p>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Questions, quotes, or just saying hello — we'd love to hear from you.</p>\n      <form className=\"mt-8 space-y-4\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-emerald-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-emerald-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-emerald-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-none bg-emerald-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-emerald-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"border-b border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Services</h1>\n        <p className=\"mt-3 max-w-xl text-slate-500\">Real work, real results — see it for yourself.</p>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid gap-10 md:grid-cols-[1fr_1fr]\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold leading-tight tracking-tighter text-slate-900\">About Meridian Consulting</h2>\n        <div className=\"space-y-4\">\n          <p className=\"text-slate-600\">Meridian Consulting pairs real experience in consulting with a genuine focus on the people we work with — no jargon, no unnecessary steps, just results.</p>\n          <div className=\"h-1 w-16 rounded-none bg-gradient-to-r from-emerald-500 to-orange-500\" />\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-2xl px-6 py-20\">\n        <div className=\"rounded-none border border-slate-200 bg-white p-8 shadow-sm\">\n          <div className=\"flex gap-0.5 text-emerald-500\">{\"★★★★★\"}</div>\n          <p className=\"mt-4 text-lg text-slate-700\">&ldquo;Getting your team aligned behind the plan, not just informed of it. That's exactly what Meridian Consulting delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Alina Novak <span className=\"font-normal text-slate-400\">— Founder</span></p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"export default function Features() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">What Meridian Consulting offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Meridian Consulting does best.</p>\n      </div>\n      <div className=\"mt-10 space-y-14\">\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-none bg-gradient-to-br from-emerald-100 to-orange-50 \" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Strategy</h3>\n            <p className=\"mt-2 text-slate-500\">Market analysis, competitive positioning, and growth planning.</p>\n          </div>\n        </div>\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-none bg-gradient-to-br from-orange-100 to-emerald-50 md:order-2\" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Operations</h3>\n            <p className=\"mt-2 text-slate-500\">Process redesign that actually survives contact with reality.</p>\n          </div>\n        </div>\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-none bg-gradient-to-br from-emerald-100 to-orange-50 \" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Change management</h3>\n            <p className=\"mt-2 text-slate-500\">Getting your team aligned behind the plan, not just informed of it.</p>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Features","About","Testimonial","Footer"]},{"name":"Services","path":"/services","slug":"services","sections":["Navbar","PageHeader","Features","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = 'ac3e2b3c-5072-48e9-892d-f1a3593a43ea'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"bg-white\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-6\">\n        <a href=\"/\" className=\"font-sans text-base font-bold uppercase tracking-wide text-slate-900\">Vantage Group</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n          <a href=\"/services\" className=\"border-b-2 border-transparent pb-1 text-sm font-medium text-slate-500 hover:border-fuchsia-500 hover:text-slate-900 transition-colors\">Services</a>\n          <a href=\"/contact\" className=\"border-b-2 border-transparent pb-1 text-sm font-medium text-slate-500 hover:border-fuchsia-500 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-[0.9fr_1.1fr] md:py-28\">\n        <div className=\"aspect-square rounded-3xl bg-gradient-to-tr from-emerald-100 to-fuchsia-100 ring-1 ring-fuchsia-100 md:order-1\" />\n        <div className=\"md:order-2\">\n          <span className=\"text-xs font-semibold uppercase tracking-wide text-fuchsia-600\">CONSULTING</span>\n          <h1 className=\"font-sans mt-3 text-4xl md:text-5xl font-bold leading-[1.02] tracking-wide text-slate-900\">The outside perspective your team is too close to see.</h1>\n          <p className=\"mt-5 max-w-md text-lg text-slate-600\">Vantage pairs senior operators with your leadership team, not just a slide deck.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-full bg-fuchsia-600 px-6 py-3 text-sm font-semibold text-white hover:bg-fuchsia-700 transition-colors\">Get started</a>\n            <a href=\"#more\" className=\"text-sm font-semibold text-slate-700 underline decoration-slate-300 underline-offset-4 hover:decoration-slate-600\">See how it works</a>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-white\">\n      <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-4 border-t border-slate-100 px-6 py-10 text-center\">\n        <p className=\"font-sans text-base font-bold tracking-wide text-slate-900\">Vantage Group</p>\n        <div className=\"flex flex-wrap items-center justify-center gap-6\">\n          <a href=\"/services\" className=\"text-sm text-slate-500 hover:text-slate-900\">Services</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a>\n        </div>\n        <p className=\"text-xs text-slate-400\">&copy; {new Date().getFullYear()} Vantage Group &middot; Built with <span className=\"text-fuchsia-600\">webma</span></p>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-xl px-6 py-24 text-center\">\n      <h2 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Questions, quotes, or just saying hello — we'd love to hear from you.</p>\n      <form className=\"mt-10 space-y-3 text-left\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <input name=\"name\" required placeholder=\"Your name\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-fuchsia-500 focus:outline-none\" />\n        <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-fuchsia-500 focus:outline-none\" />\n        <textarea name=\"message\" required rows={3} placeholder=\"How can we help?\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-fuchsia-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"mt-4 w-full rounded-full bg-fuchsia-600 px-6 py-3 text-sm font-semibold text-white hover:bg-fuchsia-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-fuchsia-600 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide\">Services</h1>\n        <p className=\"mt-3 max-w-xl text-white/75\">Real work, real results — see it for yourself.</p>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"grid items-center gap-12 md:grid-cols-2\">\n        <div className=\"aspect-[4/3] rounded-3xl bg-gradient-to-br from-fuchsia-50 to-emerald-50 \" />\n        <div>\n          <h2 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">About Vantage Group</h2>\n          <p className=\"mt-4 text-slate-600\">We started Vantage Group because the existing options in consulting were either too slow or too generic. Every decision here is made with our clients' actual outcomes in mind.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-3xl px-6 py-20 text-center\">\n      <p className=\"font-sans text-2xl md:text-3xl font-medium leading-snug text-slate-900\">&ldquo;Structured playbooks for entering a new region or segment. That's exactly what Vantage Group delivered.&rdquo;</p>\n      <div className=\"mt-6 flex items-center justify-center gap-3\">\n        <div className=\"h-10 w-10 rounded-3xl bg-fuchsia-100\" />\n        <div className=\"text-left\">\n          <p className=\"text-sm font-semibold text-slate-900\">Alina Novak</p>\n          <p className=\"text-xs text-slate-500\">Client</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"export default function Features() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">What Vantage Group offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Vantage Group does best.</p>\n      </div>\n      <div className=\"mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3\">\n        <div className=\"overflow-hidden rounded-3xl border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-fuchsia-100 to-emerald-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Strategy</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Market analysis, competitive positioning, and growth planning.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-3xl border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-fuchsia-100 to-emerald-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Operations</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Process redesign that actually survives contact with reality.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-3xl border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-fuchsia-100 to-emerald-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Change management</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Getting your team aligned behind the plan, not just informed of it.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-3xl border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-fuchsia-100 to-emerald-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Financial planning</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Budgets and forecasts leadership can actually trust.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-3xl border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-fuchsia-100 to-emerald-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Market entry</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Structured playbooks for entering a new region or segment.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-3xl border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-fuchsia-100 to-emerald-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Risk assessment</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Identify what could go wrong before it does.</p>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Features","About","Testimonial","Footer"]},{"name":"Services","path":"/services","slug":"services","sections":["Navbar","PageHeader","Features","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '2f038cad-e936-4b2d-a607-6be5d06d914b'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"border-b border-slate-100 bg-white\">\n      <nav className=\"mx-auto grid max-w-6xl grid-cols-3 items-center px-6 py-5\">\n        <div className=\"flex items-center gap-6\">\n          <a href=\"/events\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Events</a>\n        </div>\n        <a href=\"/\" className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-center text-xl font-bold tracking-tighter text-slate-900\">Basecamp Circle</a>\n        <div className=\"flex items-center justify-end gap-6\">\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Subscribe</a>\n          <a href=\"/contact\" className=\"text-sm font-semibold text-emerald-600 hover:text-emerald-700\">Contact →</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-[0.9fr_1.1fr] md:py-28\">\n        <div className=\"aspect-square rounded-none bg-gradient-to-tr from-orange-100 to-emerald-100 ring-1 ring-emerald-100 md:order-1\" />\n        <div className=\"md:order-2\">\n          \n          <h1 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] mt-3 text-5xl md:text-7xl font-bold leading-[1.02] tracking-tighter text-slate-900\">Find your people, not just your feed.</h1>\n          <p className=\"mt-5 max-w-md text-lg text-slate-600\">Real conversations, not another group chat that goes quiet.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-none bg-emerald-600 px-6 py-3 text-sm font-semibold text-white hover:bg-emerald-700 transition-colors\">Get in touch</a>\n            <a href=\"#more\" className=\"text-sm font-semibold text-slate-700 underline decoration-slate-300 underline-offset-4 hover:decoration-slate-600\">Explore</a>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer>\n      <div className=\"bg-emerald-600 text-white\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-4 px-6 py-14 text-center md:flex-row md:justify-between md:text-left\">\n          <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter\">Ready when you are.</h2>\n          <a href=\"/contact\" className=\"rounded-none bg-white px-6 py-3 text-sm font-semibold text-emerald-700 hover:bg-white/90 transition-colors\">Get in touch</a>\n        </div>\n      </div>\n      <div className=\"bg-white\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center justify-between gap-3 px-6 py-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Basecamp Circle</p>\n          <div className=\"flex gap-6\">\n            <a href=\"/events\" className=\"text-slate-500 hover:text-slate-900\">Events</a>\n            <a href=\"/contact\" className=\"text-slate-500 hover:text-slate-900\">Subscribe</a>\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Questions, quotes, or just saying hello — we'd love to hear from you.</p>\n      <form className=\"mt-8 space-y-4\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-emerald-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-emerald-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-emerald-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-none bg-emerald-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-emerald-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14 text-center\">\n        <span className=\"text-xs font-semibold uppercase tracking-tighter text-emerald-600\">A closer look at what we do and how we do it.</span>\n        <h1 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] mx-auto mt-3 max-w-2xl text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Events</h1>\n      </div>\n    </section>\n  );\n}\n","components/Latest.tsx":"import { Zap, Star, Shield, Sparkles, Target, Heart, Award, TrendingUp, Users, Clock, CheckCircle, Compass } from \"lucide-react\";\n\nexport default function Latest() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Latest updates</h2>\n        <p className=\"mt-3 text-slate-500\">Recent posts and announcements.</p>\n      </div>\n      <div className=\"mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-3\">\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-emerald-100 text-emerald-600\">\n            <Zap size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Weekly meetups</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Every Thursday, open to all members.</p>\n        </div>\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-emerald-100 text-emerald-600\">\n            <Star size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Mentorship program</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Paired mentorship across experience levels.</p>\n        </div>\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-emerald-100 text-emerald-600\">\n            <Shield size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Member directory</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Find and connect with people in your field.</p>\n        </div>\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-emerald-100 text-emerald-600\">\n            <Sparkles size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Resource library</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Guides, templates, and recordings from past sessions.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Latest","Footer"]},{"name":"Events","path":"/events","slug":"events","sections":["Navbar","PageHeader","Latest","Footer"]},{"name":"Subscribe","path":"/contact","slug":"subscribe","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '551ebeeb-e505-4467-a4f7-665e8233d24e'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"bg-teal-600\">\n      <nav className=\"mx-auto flex max-w-6xl flex-wrap items-center justify-between gap-4 px-6 py-4\">\n        <a href=\"/\" className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-lg font-bold tracking-tighter text-white\">The Guild</a>\n        <div className=\"flex items-center gap-6\">\n          <a href=\"/events\" className=\"text-sm font-medium text-white/80 hover:text-white transition-colors\">Events</a>\n          <a href=\"/contact\" className=\"text-sm font-medium text-white/80 hover:text-white transition-colors\">Subscribe</a>\n          <a href=\"/contact\" className=\"rounded-none bg-white px-4 py-2 text-sm font-semibold text-teal-700 hover:bg-white/90 transition-colors\">Contact</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"relative overflow-hidden bg-gradient-to-br from-teal-600 via-teal-500 to-rose-500 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-24 md:py-32\">\n        <div className=\"max-w-2xl\">\n          \n          <h1 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] mt-5 text-5xl md:text-7xl font-bold leading-[1.05] tracking-tighter\">A community for people who take the craft seriously.</h1>\n          <p className=\"mt-5 max-w-lg text-lg text-white/80\">The Guild is 2,000 members deep, and still invite-only for a reason.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-none bg-white px-6 py-3 text-sm font-semibold text-teal-700 hover:bg-white/90 transition-colors\">Get started</a>\n            <a href=\"#more\" className=\"rounded-none border border-white/40 px-6 py-3 text-sm font-semibold text-white hover:border-white transition-colors\">See how it works</a>\n          </div>\n        </div>\n        <div className=\"mt-16 hidden max-w-sm rounded-none border border-white/20 bg-white/10 p-6 backdrop-blur md:block\">\n          <p className=\"text-sm text-white/70\">Trusted by teams who need it to just work.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer>\n      <div className=\"bg-teal-600 text-white\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-4 px-6 py-14 text-center md:flex-row md:justify-between md:text-left\">\n          <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter\">Ready when you are.</h2>\n          <a href=\"/contact\" className=\"rounded-none bg-white px-6 py-3 text-sm font-semibold text-teal-700 hover:bg-white/90 transition-colors\">Get in touch</a>\n        </div>\n      </div>\n      <div className=\"bg-white\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center justify-between gap-3 px-6 py-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} The Guild</p>\n          <div className=\"flex gap-6\">\n            <a href=\"/events\" className=\"text-slate-500 hover:text-slate-900\">Events</a>\n            <a href=\"/contact\" className=\"text-slate-500 hover:text-slate-900\">Subscribe</a>\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto grid max-w-5xl gap-10 px-6 py-20 md:grid-cols-2\">\n        <div>\n          <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Get in touch</h2>\n          <p className=\"mt-3 text-slate-500\">Questions, quotes, or just saying hello — we'd love to hear from you.</p>\n          <div className=\"mt-8 space-y-4 text-sm text-slate-600\">\n            <p><span className=\"font-semibold text-slate-900\">Address</span><br />123 Market Street, Suite 400</p>\n            <p><span className=\"font-semibold text-slate-900\">Hours</span><br />Mon–Fri, 9am–6pm</p>\n          </div>\n        </div>\n        <form className=\"space-y-4 rounded-none border border-slate-200 bg-white p-6\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n          <input name=\"name\" required placeholder=\"Your name\" className=\"w-full rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-teal-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-teal-500 focus:outline-none\" />\n          <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-teal-500 focus:outline-none\" />\n          <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n          <button type=\"submit\" className=\"w-full rounded-none bg-teal-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-teal-700 transition-colors\">Send message</button>\n        </form>\n      </div>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14 text-center\">\n        <span className=\"text-xs font-semibold uppercase tracking-tighter text-teal-600\">A closer look at what we do and how we do it.</span>\n        <h1 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] mx-auto mt-3 max-w-2xl text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Events</h1>\n      </div>\n    </section>\n  );\n}\n","components/Latest.tsx":"import { Zap, Star, Shield, Sparkles, Target, Heart, Award, TrendingUp, Users, Clock, CheckCircle, Compass } from \"lucide-react\";\n\nexport default function Latest() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-4xl px-6 py-20\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Latest updates</h2>\n        <p className=\"mt-3 text-slate-500\">Recent posts and announcements.</p>\n        <div className=\"mt-10 divide-y divide-slate-200\">\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-none bg-white text-teal-600 shadow-sm\"><Zap size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Weekly meetups</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Every Thursday, open to all members.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-none bg-white text-teal-600 shadow-sm\"><Star size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Mentorship program</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Paired mentorship across experience levels.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-none bg-white text-teal-600 shadow-sm\"><Shield size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Member directory</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Find and connect with people in your field.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-none bg-white text-teal-600 shadow-sm\"><Sparkles size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Resource library</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Guides, templates, and recordings from past sessions.</p>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Latest","Footer"]},{"name":"Events","path":"/events","slug":"events","sections":["Navbar","PageHeader","Latest","Footer"]},{"name":"Subscribe","path":"/contact","slug":"subscribe","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '15191a48-80c9-433e-a778-32b0e2fbb513'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"border-b border-slate-100 bg-white\">\n      <nav className=\"mx-auto grid max-w-6xl grid-cols-3 items-center px-6 py-5\">\n        <div className=\"flex items-center gap-6\">\n          <a href=\"/events\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Events</a>\n        </div>\n        <a href=\"/\" className=\"font-['Courier_New',ui-monospace,monospace] text-center text-xl font-bold tracking-tight text-slate-900\">The Roundtable</a>\n        <div className=\"flex items-center justify-end gap-6\">\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Subscribe</a>\n          <a href=\"/contact\" className=\"text-sm font-semibold text-sky-600 hover:text-sky-700\">Contact →</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-sky-600 text-white\">\n      <div className=\"mx-auto max-w-4xl px-6 py-28 text-center md:py-32\">\n        <span className=\"text-xs font-semibold uppercase tracking-tight text-white/70\">COMMUNITY</span>\n        <h1 className=\"font-['Courier_New',ui-monospace,monospace] mt-4 text-4xl md:text-5xl font-bold leading-[0.98] tracking-tight\">Peers who'll actually tell you the truth.</h1>\n        <p className=\"mx-auto mt-6 max-w-lg text-lg text-white/85\">A small, curated group meeting monthly, in person and online.</p>\n        <div className=\"mt-9 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-sm bg-white px-7 py-3 text-sm font-semibold text-sky-700 hover:bg-white/90 transition-colors\">Get started</a>\n          <a href=\"#more\" className=\"rounded-sm border border-white/50 px-7 py-3 text-sm font-semibold hover:border-white transition-colors\">See how it works</a>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"border-t border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto flex max-w-6xl flex-col gap-8 px-6 py-14 md:flex-row md:items-start md:justify-between\">\n        <div className=\"max-w-sm\">\n          <p className=\"font-['Courier_New',ui-monospace,monospace] text-lg font-bold tracking-tight text-slate-900\">The Roundtable</p>\n          <p className=\"mt-2 text-sm text-slate-500\">A small, curated group meeting monthly, in person and online.</p>\n        </div>\n        <div className=\"flex gap-8\">\n          <a href=\"/events\" className=\"text-sm text-slate-500 hover:text-slate-900\">Events</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Subscribe</a>\n        </div>\n      </div>\n      <div className=\"border-t border-slate-200\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center justify-between gap-3 px-6 py-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} The Roundtable. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-sky-600\"><span className=\"h-1.5 w-1.5 rounded-full bg-sky-600\" /> Built with webma</div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-xl px-6 py-24 text-center\">\n      <h2 className=\"font-['Courier_New',ui-monospace,monospace] text-xl md:text-2xl font-bold tracking-tight text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Questions, quotes, or just saying hello — we'd love to hear from you.</p>\n      <form className=\"mt-10 space-y-3 text-left\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <input name=\"name\" required placeholder=\"Your name\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-sky-500 focus:outline-none\" />\n        <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-sky-500 focus:outline-none\" />\n        <textarea name=\"message\" required rows={3} placeholder=\"How can we help?\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-sky-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"mt-4 w-full rounded-sm bg-sky-600 px-6 py-3 text-sm font-semibold text-white hover:bg-sky-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"border-b border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-['Courier_New',ui-monospace,monospace] text-xl md:text-2xl font-bold tracking-tight text-slate-900\">Events</h1>\n        <p className=\"mt-3 max-w-xl text-slate-500\">A closer look at what we do and how we do it.</p>\n      </div>\n    </section>\n  );\n}\n","components/Latest.tsx":"export default function Latest() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Courier_New',ui-monospace,monospace] text-xl md:text-2xl font-bold tracking-tight text-slate-900\">Latest updates</h2>\n        <p className=\"mt-3 text-slate-500\">Recent posts and announcements.</p>\n      </div>\n      <div className=\"mt-10 space-y-14\">\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-sm bg-gradient-to-br from-sky-100 to-fuchsia-50 \" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Weekly meetups</h3>\n            <p className=\"mt-2 text-slate-500\">Every Thursday, open to all members.</p>\n          </div>\n        </div>\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-sm bg-gradient-to-br from-fuchsia-100 to-sky-50 md:order-2\" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Mentorship program</h3>\n            <p className=\"mt-2 text-slate-500\">Paired mentorship across experience levels.</p>\n          </div>\n        </div>\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-sm bg-gradient-to-br from-sky-100 to-fuchsia-50 \" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Member directory</h3>\n            <p className=\"mt-2 text-slate-500\">Find and connect with people in your field.</p>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Latest","Footer"]},{"name":"Events","path":"/events","slug":"events","sections":["Navbar","PageHeader","Latest","Footer"]},{"name":"Subscribe","path":"/contact","slug":"subscribe","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '115c43cf-9ea1-478b-a6ba-6e106b9fb39b'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-0 z-40 border-b border-slate-100 bg-white/80 backdrop-blur\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-4\">\n        <a href=\"/\" className=\"font-['Verdana',ui-sans-serif,sans-serif] text-lg font-bold tracking-tight text-slate-900\">Granite State Builders</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n          <a href=\"/services\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Services</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-full bg-fuchsia-600 px-4 py-2 text-sm font-semibold text-white hover:bg-fuchsia-700 transition-colors\">Get in touch</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-fuchsia-600 text-white\">\n      <div className=\"mx-auto max-w-4xl px-6 py-28 text-center md:py-32\">\n        <span className=\"text-xs font-semibold uppercase tracking-tight text-white/70\">CONSTRUCTION</span>\n        <h1 className=\"font-['Verdana',ui-sans-serif,sans-serif] mt-4 text-4xl md:text-6xl font-bold leading-[0.98] tracking-tight\">Craftsmanship that outlasts the warranty.</h1>\n        <p className=\"mx-auto mt-6 max-w-lg text-lg text-white/85\">Three generations building in this county.</p>\n        <div className=\"mt-9 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-full bg-white px-7 py-3 text-sm font-semibold text-fuchsia-700 hover:bg-white/90 transition-colors\">Get in touch</a>\n          <a href=\"#more\" className=\"rounded-full border border-white/50 px-7 py-3 text-sm font-semibold hover:border-white transition-colors\">Explore</a>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <div className=\"grid gap-10 md:grid-cols-[1.2fr_1fr]\">\n          <div>\n            <p className=\"font-['Verdana',ui-sans-serif,sans-serif] text-xl font-bold tracking-tight\">Granite State Builders</p>\n            <p className=\"mt-2 max-w-sm text-sm text-white/50\">Three generations building in this county.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-tight text-white/40\">Stay in the loop</p>\n            <form className=\"mt-3 flex gap-2\" onSubmit={(e) => e.preventDefault()}>\n              <input type=\"email\" required placeholder=\"you@email.com\" className=\"w-full rounded-2xl border border-white/15 bg-white/5 px-4 py-2.5 text-sm text-white placeholder:text-white/30 focus:border-fuchsia-400 focus:outline-none\" />\n              <button type=\"submit\" className=\"rounded-full bg-fuchsia-500 px-5 py-2.5 text-sm font-semibold text-slate-950 hover:bg-fuchsia-400 transition-colors\">Join</button>\n            </form>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-3 border-t border-white/10 pt-6 text-xs text-white/40 sm:flex-row\">\n          <div className=\"flex gap-6\">\n            <a href=\"/services\" className=\"hover:text-white\">Services</a>\n            <a href=\"/contact\" className=\"hover:text-white\">Contact</a>\n          </div>\n          <p>&copy; {new Date().getFullYear()} Granite State Builders</p>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-['Verdana',ui-sans-serif,sans-serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Tell us a bit about what you need — we'll take it from there.</p>\n      <form className=\"mt-8 space-y-4\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-2xl border border-slate-200 px-4 py-2.5 text-sm focus:border-fuchsia-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-2xl border border-slate-200 px-4 py-2.5 text-sm focus:border-fuchsia-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-2xl border border-slate-200 px-4 py-2.5 text-sm focus:border-fuchsia-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-full bg-fuchsia-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-fuchsia-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <secti