<br />123 Market Street, Suite 400</p>\n            <p><span className=\"font-semibold text-slate-900\">Hours</span><br />Mon–Fri, 9am–6pm</p>\n          </div>\n        </div>\n        <form className=\"space-y-4 rounded-lg border border-slate-200 bg-white p-6\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n          <input name=\"name\" required placeholder=\"Your name\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-fuchsia-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-fuchsia-500 focus:outline-none\" />\n          <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-fuchsia-500 focus:outline-none\" />\n          <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n          <button type=\"submit\" className=\"w-full rounded-lg bg-fuchsia-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-fuchsia-700 transition-colors\">Send message</button>\n        </form>\n      </div>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section c