t, Heart, Award, TrendingUp, Users, Clock, CheckCircle, Compass } from \"lucide-react\";\n\nexport default function Catalog() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-4xl px-6 py-20\">\n        <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">What we offer</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Summit Conference does best.</p>\n        <div className=\"mt-10 divide-y divide-slate-200\">\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-lg bg-white text-fuchsia-600 shadow-sm\"><Zap size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Opening keynote</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">9:00am — main stage.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-lg bg-white text-fuchsia-600 shadow-sm\"><Star size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Workshop track</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">11:00am–3:00pm — hands-on sessions.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-lg bg-white text-fuchsia-600 shadow-sm\"><Shield size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Networking reception</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">6:00pm — rooftop terrace.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-lg bg-white text-fuchsia-600 shadow-sm\"><Sparkles size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Closing panel</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">4:00pm — main stage.</p>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","About","Testimonial","Footer"]},{"name":"Schedule","path":"/schedule","slug":"schedule","sections":["Navbar","PageHeader","Catalog","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '4f9d845b-e2aa-45b5-9576-982a54e2e254'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-0 z-40 border-b border-slate-100 bg-white/80 backdrop-blur\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-4\">\n        <a href=\"/\" className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-lg font-bold tracking-tighter text-slate-900\">The Assembly</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n          <a href=\"/schedule\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Schedule</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-none bg-orange-600 px-4 py-2 text-sm font-semibold text-white hover:bg-orange-700 transition-colors\">Get in touch</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-3xl px-6 py-28 text-center md:py-36\">\n        \n        <h1 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] mt-6 text-5xl md:text-7xl font-bold leading-[1.05] tracking-tighter\">The event people plan their year around.</h1>\n        <p className=\"mx-auto mt-5 max-w-xl text-lg text-white/60\">The Assembly has sold out five years running.</p>\n        <div className=\"mt-9 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-none bg-orange-500 px-7 py-3 text-sm font-semibold text-slate-950 hover:bg-orange-400 transition-colors\">Book a call</a>\n          <a href=\"#more\" className=\"rounded-none border border-white/20 px-7 py-3 text-sm font-semibold hover:border-white/40 transition-colors\">Learn more</a>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-white\">\n      <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-4 border-t border-slate-100 px-6 py-10 text-center\">\n        <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-base font-bold tracking-tighter text-slate-900\">The Assembly</p>\n        <div className=\"flex flex-wrap items-center justify-center gap-6\">\n          <a href=\"/schedule\" className=\"text-sm text-slate-500 hover:text-slate-900\">Schedule</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a>\n        </div>\n        <p className=\"text-xs text-slate-400\">&copy; {new Date().getFullYear()} The Assembly &middot; Built with <span className=\"text-orange-600\">webma</span></p>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">We usually reply within one business day.</p>\n      <form className=\"mt-8 space-y-4\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-orange-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-orange-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-orange-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-none bg-orange-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-orange-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-orange-600 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter\">Schedule</h1>\n        <p className=\"mt-3 max-w-xl text-white/75\">Real work, real results — see it for yourself.</p>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid gap-10 md:grid-cols-[1fr_1fr]\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold leading-tight tracking-tighter text-slate-900\">About The Assembly</h2>\n        <div className=\"space-y-4\">\n          <p className=\"text-slate-600\">We started The Assembly because the existing options in events were either too slow or too generic. Every decision here is made with our clients' actual outcomes in mind.</p>\n          <div className=\"h-1 w-16 rounded-none bg-gradient-to-r from-orange-500 to-indigo-500\" />\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid items-center gap-10 md:grid-cols-[0.8fr_1.2fr]\">\n        <div className=\"aspect-square rounded-none bg-gradient-to-br from-orange-100 to-indigo-100\" />\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl font-medium leading-snug text-slate-900\">&ldquo;6:00pm — rooftop terrace. That's exactly what The Assembly delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Nadia Farouk</p>\n          <p className=\"text-xs text-slate-500\">Marketing Director</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Catalog.tsx":"import { Zap, Star, Shield, Sparkles, Target, Heart, Award, TrendingUp, Users, Clock, CheckCircle, Compass } from \"lucide-react\";\n\nexport default function Catalog() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">What we offer</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what The Assembly does best.</p>\n      </div>\n      <div className=\"mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-3\">\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-orange-100 text-orange-600\">\n            <Zap size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Opening keynote</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">9:00am — main stage.</p>\n        </div>\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-orange-100 text-orange-600\">\n            <Star size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Workshop track</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">11:00am–3:00pm — hands-on sessions.</p>\n        </div>\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-orange-100 text-orange-600\">\n            <Shield size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Networking reception</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">6:00pm — rooftop terrace.</p>\n        </div>\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-orange-100 text-orange-600\">\n            <Sparkles size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Closing panel</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">4:00pm — main stage.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","About","Testimonial","Footer"]},{"name":"Schedule","path":"/schedule","slug":"schedule","sections":["Navbar","PageHeader","Catalog","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = 'e9cb9658-eb5a-467f-8cc2-4a7cd819c0ac'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"border-b border-slate-100 bg-white\">\n      <nav className=\"mx-auto grid max-w-6xl grid-cols-3 items-center px-6 py-5\">\n        <div className=\"flex items-center gap-6\">\n          <a href=\"/collection\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Collection</a>\n        </div>\n        <a href=\"/\" className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-center text-xl font-bold tracking-tighter text-slate-900\">Maison Verre</a>\n        <div className=\"flex items-center justify-end gap-6\">\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n          <a href=\"/contact\" className=\"text-sm font-semibold text-amber-600 hover:text-amber-700\">Contact →</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-2 md:py-32\">\n        <div>\n          \n          <h1 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] mt-5 text-5xl md:text-7xl font-bold leading-[1.05] tracking-tighter text-slate-900\">Considered pieces, not seasonal noise.</h1>\n          <p className=\"mt-5 max-w-lg text-lg text-slate-600\">Maison Verre designs a small collection twice a year — nothing rushed, nothing disposable.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-none bg-amber-600 px-6 py-3 text-sm font-semibold text-white hover:bg-amber-700 transition-colors\">Get started</a>\n            <a href=\"#more\" className=\"rounded-none border border-slate-200 px-6 py-3 text-sm font-semibold text-slate-700 hover:border-slate-400 transition-colors\">See how it works</a>\n          </div>\n        </div>\n        <div className=\"aspect-[4/3] rounded-none bg-gradient-to-br from-amber-100 via-amber-50 to-slate-50 ring-1 ring-amber-100\" />\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <div className=\"grid gap-10 md:grid-cols-[1.2fr_1fr]\">\n          <div>\n            <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-xl font-bold tracking-tighter\">Maison Verre</p>\n            <p className=\"mt-2 max-w-sm text-sm text-white/50\">Maison Verre designs a small collection twice a year — nothing rushed, nothing disposable.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-tighter text-white/40\">Stay in the loop</p>\n            <form className=\"mt-3 flex gap-2\" onSubmit={(e) => e.preventDefault()}>\n              <input type=\"email\" required placeholder=\"you@email.com\" className=\"w-full rounded-none border border-white/15 bg-white/5 px-4 py-2.5 text-sm text-white placeholder:text-white/30 focus:border-amber-400 focus:outline-none\" />\n              <button type=\"submit\" className=\"rounded-none bg-amber-500 px-5 py-2.5 text-sm font-semibold text-slate-950 hover:bg-amber-400 transition-colors\">Join</button>\n            </form>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-3 border-t border-white/10 pt-6 text-xs text-white/40 sm:flex-row\">\n          <div className=\"flex gap-6\">\n            <a href=\"/collection\" className=\"hover:text-white\">Collection</a>\n            <a href=\"/contact\" className=\"hover:text-white\">Contact</a>\n          </div>\n          <p>&copy; {new Date().getFullYear()} Maison Verre</p>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-xl px-6 py-24 text-center\">\n      <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Tell us a bit about what you need — we'll take it from there.</p>\n      <form className=\"mt-10 space-y-3 text-left\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <input name=\"name\" required placeholder=\"Your name\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-amber-500 focus:outline-none\" />\n        <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-amber-500 focus:outline-none\" />\n        <textarea name=\"message\" required rows={3} placeholder=\"How can we help?\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-amber-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"mt-4 w-full rounded-none bg-amber-600 px-6 py-3 text-sm font-semibold text-white hover:bg-amber-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"border-b border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Collection</h1>\n        <p className=\"mt-3 max-w-xl text-slate-500\">Everything you need to know about how we approach fashion.</p>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"grid items-center gap-12 md:grid-cols-2\">\n        <div className=\"aspect-[4/3] rounded-none bg-gradient-to-br from-amber-50 to-slate-50 md:order-2\" />\n        <div>\n          <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">About Maison Verre</h2>\n          <p className=\"mt-4 text-slate-600\">Maison Verre pairs real experience in fashion with a genuine focus on the people we work with — no jargon, no unnecessary steps, just results.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-3xl px-6 py-20 text-center\">\n      <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-medium leading-snug text-slate-900\">&ldquo;Full-grain leather, stacked heel. That's exactly what Maison Verre delivered.&rdquo;</p>\n      <div className=\"mt-6 flex items-center justify-center gap-3\">\n        <div className=\"h-10 w-10 rounded-none bg-amber-100\" />\n        <div className=\"text-left\">\n          <p className=\"text-sm font-semibold text-slate-900\">Priya Shah</p>\n          <p className=\"text-xs text-slate-500\">Operations Lead</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Catalog.tsx":"export default function Catalog() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">What we offer</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Maison Verre does best.</p>\n      </div>\n      <div className=\"mt-10 grid gap-8 sm:grid-cols-2 lg:grid-cols-3\">\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-4xl font-bold text-amber-200\">01</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Tailored Blazer</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Structured shoulder, Italian wool.</p>\n        </div>\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-4xl font-bold text-amber-200\">02</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Silk Slip Dress</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Bias-cut, hand-finished hem.</p>\n        </div>\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-4xl font-bold text-amber-200\">03</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Leather Ankle Boot</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Full-grain leather, stacked heel.</p>\n        </div>\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-4xl font-bold text-amber-200\">04</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Cashmere Scarf</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Two-ply cashmere, hand-rolled edge.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","About","Testimonial","Footer"]},{"name":"Collection","path":"/collection","slug":"collection","sections":["Navbar","PageHeader","Catalog","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = 'b538abb7-8111-4cb8-909f-3bf7dcdf9772'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-4 z-40 mx-auto max-w-4xl px-4\">\n      <nav className=\"flex items-center justify-between gap-4 rounded-full border border-slate-200 bg-white/95 px-6 py-3 shadow-sm backdrop-blur\">\n        <a href=\"/\" className=\"font-['Courier_New',ui-monospace,monospace] text-sm font-bold tracking-tight text-slate-900\">Rowe Atelier</a>\n        <div className=\"hidden items-center gap-6 md:flex\">\n          <a href=\"/collection\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Collection</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-full bg-emerald-600 px-4 py-1.5 text-xs font-semibold text-white hover:bg-emerald-700 transition-colors\">Get started</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-[0.9fr_1.1fr] md:py-28\">\n        <div className=\"aspect-square rounded-sm bg-gradient-to-tr from-orange-100 to-emerald-100 ring-1 ring-emerald-100 md:order-1\" />\n        <div className=\"md:order-2\">\n          <span className=\"text-xs font-semibold uppercase tracking-tight text-emerald-600\">FASHION</span>\n          <h1 className=\"font-['Courier_New',ui-monospace,monospace] mt-3 text-4xl md:text-5xl font-bold leading-[1.02] tracking-tight text-slate-900\">Tailoring for a body that actually moves.</h1>\n          <p className=\"mt-5 max-w-md text-lg text-slate-600\">Rowe cuts every piece to be worn, not just photographed.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-sm bg-emerald-600 px-6 py-3 text-sm font-semibold text-white hover:bg-emerald-700 transition-colors\">Book a call</a>\n            <a href=\"#more\" className=\"text-sm font-semibold text-slate-700 underline decoration-slate-300 underline-offset-4 hover:decoration-slate-600\">Learn more</a>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer>\n      <div className=\"bg-emerald-600 text-white\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-4 px-6 py-14 text-center md:flex-row md:justify-between md:text-left\">\n          <h2 className=\"font-['Courier_New',ui-monospace,monospace] text-xl md:text-2xl font-bold tracking-tight\">Ready when you are.</h2>\n          <a href=\"/contact\" className=\"rounded-sm bg-white px-6 py-3 text-sm font-semibold text-emerald-700 hover:bg-white/90 transition-colors\">Get in touch</a>\n        </div>\n      </div>\n      <div className=\"bg-white\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center justify-between gap-3 px-6 py-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Rowe Atelier</p>\n          <div className=\"flex gap-6\">\n            <a href=\"/collection\" className=\"text-slate-500 hover:text-slate-900\">Collection</a>\n            <a href=\"/contact\" className=\"text-slate-500 hover:text-slate-900\">Contact</a>\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-xl px-6 py-24 text-center\">\n      <h2 className=\"font-['Courier_New',ui-monospace,monospace] text-xl md:text-2xl font-bold tracking-tight text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Tell us a bit about what you need — we'll take it from there.</p>\n      <form className=\"mt-10 space-y-3 text-left\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <input name=\"name\" required placeholder=\"Your name\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-emerald-500 focus:outline-none\" />\n        <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-emerald-500 focus:outline-none\" />\n        <textarea name=\"message\" required rows={3} placeholder=\"How can we help?\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-emerald-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"mt-4 w-full rounded-sm bg-emerald-600 px-6 py-3 text-sm font-semibold text-white hover:bg-emerald-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"border-b border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-['Courier_New',ui-monospace,monospace] text-xl md:text-2xl font-bold tracking-tight text-slate-900\">Collection</h1>\n        <p className=\"mt-3 max-w-xl text-slate-500\">Everything you need to know about how we approach fashion.</p>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-3xl px-6 py-20 text-center\">\n        <h2 className=\"font-['Courier_New',ui-monospace,monospace] text-xl md:text-2xl font-bold tracking-tight text-slate-900\">About Rowe Atelier</h2>\n        <p className=\"mx-auto mt-4 max-w-xl text-slate-600\">We started Rowe Atelier because the existing options in fashion were either too slow or too generic. Every decision here is made with our clients' actual outcomes in mind.</p>\n        <div className=\"mx-auto mt-10 grid max-w-lg grid-cols-3 gap-6\">\n          <div><p className=\"text-2xl font-bold text-emerald-600\">500+</p><p className=\"mt-1 text-xs uppercase tracking-tight text-slate-400\">Clients served</p></div>\n          <div><p className=\"text-2xl font-bold text-emerald-600\">10 yrs</p><p className=\"mt-1 text-xs uppercase tracking-tight text-slate-400\">In business</p></div>\n          <div><p className=\"text-2xl font-bold text-emerald-600\">4.9/5</p><p className=\"mt-1 text-xs uppercase tracking-tight text-slate-400\">Avg. rating</p></div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-2xl px-6 py-20\">\n        <div className=\"rounded-sm border border-slate-200 bg-white p-8 shadow-sm\">\n          <div className=\"flex gap-0.5 text-emerald-500\">{\"★★★★★\"}</div>\n          <p className=\"mt-4 text-lg text-slate-700\">&ldquo;Structured shoulder, Italian wool. That's exactly what Rowe Atelier delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Alina Novak <span className=\"font-normal text-slate-400\">— Founder</span></p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Catalog.tsx":"import { Zap, Star, Shield, Sparkles, Target, Heart, Award, TrendingUp, Users, Clock, CheckCircle, Compass } from \"lucide-react\";\n\nexport default function Catalog() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-4xl px-6 py-20\">\n        <h2 className=\"font-['Courier_New',ui-monospace,monospace] text-xl md:text-2xl font-bold tracking-tight text-slate-900\">What we offer</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Rowe Atelier does best.</p>\n        <div className=\"mt-10 divide-y divide-slate-200\">\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-sm bg-white text-emerald-600 shadow-sm\"><Zap size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Tailored Blazer</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Structured shoulder, Italian wool.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-sm bg-white text-emerald-600 shadow-sm\"><Star size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Silk Slip Dress</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Bias-cut, hand-finished hem.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-sm bg-white text-emerald-600 shadow-sm\"><Shield size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Leather Ankle Boot</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Full-grain leather, stacked heel.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-sm bg-white text-emerald-600 shadow-sm\"><Sparkles size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Cashmere Scarf</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Two-ply cashmere, hand-rolled edge.</p>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","About","Testimonial","Footer"]},{"name":"Collection","path":"/collection","slug":"collection","sections":["Navbar","PageHeader","Catalog","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '5fb693f1-7973-4011-a4ac-a917fff47f70'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-4 z-40 mx-auto max-w-4xl px-4\">\n      <nav className=\"flex items-center justify-between gap-4 rounded-full border border-slate-200 bg-white/95 px-6 py-3 shadow-sm backdrop-blur\">\n        <a href=\"/\" className=\"font-['Verdana',ui-sans-serif,sans-serif] text-sm font-bold tracking-tight text-slate-900\">Solstice Studio</a>\n        <div className=\"hidden items-center gap-6 md:flex\">\n          <a href=\"/collection\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Collection</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-full bg-sky-600 px-4 py-1.5 text-xs font-semibold text-white hover:bg-sky-700 transition-colors\">Get started</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-sky-600 text-white\">\n      <div className=\"mx-auto max-w-4xl px-6 py-28 text-center md:py-32\">\n        <span className=\"text-xs font-semibold uppercase tracking-tight text-white/70\">FASHION</span>\n        <h1 className=\"font-['Verdana',ui-sans-serif,sans-serif] mt-4 text-4xl md:text-6xl font-bold leading-[0.98] tracking-tight\">Color and cut, without the trend cycle.</h1>\n        <p className=\"mx-auto mt-6 max-w-lg text-lg text-white/85\">Solstice designs for a decade of wear, not a season of likes.</p>\n        <div className=\"mt-9 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-full bg-white px-7 py-3 text-sm font-semibold text-sky-700 hover:bg-white/90 transition-colors\">Book a call</a>\n          <a href=\"#more\" className=\"rounded-full border border-white/50 px-7 py-3 text-sm font-semibold hover:border-white transition-colors\">Learn more</a>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <div className=\"grid gap-10 md:grid-cols-[1.2fr_1fr]\">\n          <div>\n            <p className=\"font-['Verdana',ui-sans-serif,sans-serif] text-xl font-bold tracking-tight\">Solstice Studio</p>\n            <p className=\"mt-2 max-w-sm text-sm text-white/50\">Solstice designs for a decade of wear, not a season of likes.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-tight text-white/40\">Stay in the loop</p>\n            <form className=\"mt-3 flex gap-2\" onSubmit={(e) => e.preventDefault()}>\n              <input type=\"email\" required placeholder=\"you@email.com\" className=\"w-full rounded-2xl border border-white/15 bg-white/5 px-4 py-2.5 text-sm text-white placeholder:text-white/30 focus:border-sky-400 focus:outline-none\" />\n              <button type=\"submit\" className=\"rounded-full bg-sky-500 px-5 py-2.5 text-sm font-semibold text-slate-950 hover:bg-sky-400 transition-colors\">Join</button>\n            </form>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-3 border-t border-white/10 pt-6 text-xs text-white/40 sm:flex-row\">\n          <div className=\"flex gap-6\">\n            <a href=\"/collection\" className=\"hover:text-white\">Collection</a>\n            <a href=\"/contact\" className=\"hover:text-white\">Contact</a>\n          </div>\n          <p>&copy; {new Date().getFullYear()} Solstice Studio</p>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-xl px-6 py-24 text-center\">\n      <h2 className=\"font-['Verdana',ui-sans-serif,sans-serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Tell us a bit about what you need — we'll take it from there.</p>\n      <form className=\"mt-10 space-y-3 text-left\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <input name=\"name\" required placeholder=\"Your name\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-sky-500 focus:outline-none\" />\n        <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-sky-500 focus:outline-none\" />\n        <textarea name=\"message\" required rows={3} placeholder=\"How can we help?\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-sky-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"mt-4 w-full rounded-full bg-sky-600 px-6 py-3 text-sm font-semibold text-white hover:bg-sky-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"border-b border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-['Verdana',ui-sans-serif,sans-serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Collection</h1>\n        <p className=\"mt-3 max-w-xl text-slate-500\">Everything you need to know about how we approach fashion.</p>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"grid items-center gap-12 md:grid-cols-2\">\n        <div className=\"aspect-[4/3] rounded-2xl bg-gradient-to-br from-sky-50 to-fuchsia-50 md:order-2\" />\n        <div>\n          <h2 className=\"font-['Verdana',ui-sans-serif,sans-serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">About Solstice Studio</h2>\n          <p className=\"mt-4 text-slate-600\">We started Solstice Studio because the existing options in fashion were either too slow or too generic. Every decision here is made with our clients' actual outcomes in mind.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid items-center gap-10 md:grid-cols-[0.8fr_1.2fr]\">\n        <div className=\"aspect-square rounded-2xl bg-gradient-to-br from-sky-100 to-fuchsia-100\" />\n        <div>\n          <p className=\"font-['Verdana',ui-sans-serif,sans-serif] text-2xl font-medium leading-snug text-slate-900\">&ldquo;Structured shoulder, Italian wool. That's exactly what Solstice Studio delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Marcus Webb</p>\n          <p className=\"text-xs text-slate-500\">Client</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Catalog.tsx":"export default function Catalog() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Verdana',ui-sans-serif,sans-serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">What we offer</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Solstice Studio does best.</p>\n      </div>\n      <div className=\"mt-10 space-y-14\">\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-2xl bg-gradient-to-br from-sky-100 to-fuchsia-50 \" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Tailored Blazer</h3>\n            <p className=\"mt-2 text-slate-500\">Structured shoulder, Italian wool.</p>\n          </div>\n        </div>\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-2xl bg-gradient-to-br from-fuchsia-100 to-sky-50 md:order-2\" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Silk Slip Dress</h3>\n            <p className=\"mt-2 text-slate-500\">Bias-cut, hand-finished hem.</p>\n          </div>\n        </div>\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-2xl bg-gradient-to-br from-sky-100 to-fuchsia-50 \" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Leather Ankle Boot</h3>\n            <p className=\"mt-2 text-slate-500\">Full-grain leather, stacked heel.</p>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","About","Testimonial","Footer"]},{"name":"Collection","path":"/collection","slug":"collection","sections":["Navbar","PageHeader","Catalog","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = 'eed40e57-a4fd-4e2f-8e99-f41e946e3643'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"bg-white\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-6\">\n        <a href=\"/\" className=\"font-['Palatino',ui-serif,serif] text-base font-bold uppercase tracking-normal text-slate-900\">Anchor Financial Group</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n          <a href=\"/services\" className=\"border-b-2 border-transparent pb-1 text-sm font-medium text-slate-500 hover:border-slate-500 hover:text-slate-900 transition-colors\">Services</a>\n          <a href=\"/contact\" className=\"border-b-2 border-transparent pb-1 text-sm font-medium text-slate-500 hover:border-slate-500 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-2 md:py-32\">\n        <div>\n          \n          <h1 className=\"font-['Palatino',ui-serif,serif] mt-5 text-4xl md:text-5xl font-bold leading-[1.05] tracking-normal text-slate-900\">A second opinion on the decisions that matter.</h1>\n          <p className=\"mt-5 max-w-lg text-lg text-slate-600\">Fee-only advice, no products to sell you.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-lg bg-slate-600 px-6 py-3 text-sm font-semibold text-white hover:bg-slate-700 transition-colors\">Get started</a>\n            <a href=\"#more\" className=\"rounded-lg border border-slate-200 px-6 py-3 text-sm font-semibold text-slate-700 hover:border-slate-400 transition-colors\">See how it works</a>\n          </div>\n        </div>\n        <div className=\"aspect-[4/3] rounded-lg bg-gradient-to-br from-slate-100 via-slate-50 to-amber-50 ring-1 ring-slate-100\" />\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-white\">\n      <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-4 border-t border-slate-100 px-6 py-10 text-center\">\n        <p className=\"font-['Palatino',ui-serif,serif] text-base font-bold tracking-normal text-slate-900\">Anchor Financial Group</p>\n        <div className=\"flex flex-wrap items-center justify-center gap-6\">\n          <a href=\"/services\" className=\"text-sm text-slate-500 hover:text-slate-900\">Services</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a>\n        </div>\n        <p className=\"text-xs text-slate-400\">&copy; {new Date().getFullYear()} Anchor Financial Group &middot; Built with <span className=\"text-slate-600\">webma</span></p>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Tell us a bit about what you need — we'll take it from there.</p>\n      <form className=\"mt-8 space-y-4\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-slate-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-slate-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-slate-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-lg bg-slate-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-slate-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14 text-center\">\n        <span className=\"text-xs font-semibold uppercase tracking-normal text-slate-600\">Real work, real results — see it for yourself.</span>\n        <h1 className=\"font-['Palatino',ui-serif,serif] mx-auto mt-3 max-w-2xl text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">Services</h1>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"grid items-center gap-12 md:grid-cols-2\">\n        <div className=\"aspect-[4/3] rounded-lg bg-gradient-to-br from-slate-50 to-amber-50 \" />\n        <div>\n          <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">About Anchor Financial Group</h2>\n          <p className=\"mt-4 text-slate-600\">We started Anchor Financial Group because the existing options in financial services were either too slow or too generic. Every decision here is made with our clients' actual outcomes in mind.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-3xl px-6 py-20 text-center\">\n      <p className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-medium leading-snug text-slate-900\">&ldquo;Model your timeline, not just your balance. That's exactly what Anchor Financial Group delivered.&rdquo;</p>\n      <div className=\"mt-6 flex items-center justify-center gap-3\">\n        <div className=\"h-10 w-10 rounded-lg bg-slate-100\" />\n        <div className=\"text-left\">\n          <p className=\"text-sm font-semibold text-slate-900\">Theo Kwan</p>\n          <p className=\"text-xs text-slate-500\">Head of Growth</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"export default function Features() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">What Anchor Financial Group offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Anchor Financial Group does best.</p>\n      </div>\n      <div className=\"mt-10 space-y-14\">\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-lg bg-gradient-to-br from-slate-100 to-amber-50 \" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Retirement planning</h3>\n            <p className=\"mt-2 text-slate-500\">Model your timeline, not just your balance.</p>\n          </div>\n        </div>\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-lg bg-gradient-to-br from-amber-100 to-slate-50 md:order-2\" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Tax strategy</h3>\n            <p className=\"mt-2 text-slate-500\">Proactive planning, not just April filing.</p>\n          </div>\n        </div>\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-lg bg-gradient-to-br from-slate-100 to-amber-50 \" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Investment management</h3>\n            <p className=\"mt-2 text-slate-500\">Portfolios built around your actual risk tolerance.</p>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Features","About","Testimonial","Footer"]},{"name":"Services","path":"/services","slug":"services","sections":["Navbar","PageHeader","Features","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '612e183d-bf25-401d-aa3e-1485940d808f'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-4 z-40 mx-auto max-w-4xl px-4\">\n      <nav className=\"flex items-center justify-between gap-4 rounded-full border border-slate-200 bg-white/95 px-6 py-3 shadow-sm backdrop-blur\">\n        <a href=\"/\" className=\"font-['Georgia',ui-serif,serif] text-sm font-bold tracking-tight text-slate-900\">Birchgate Capital</a>\n        <div className=\"hidden items-center gap-6 md:flex\">\n          <a href=\"/services\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Services</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-full bg-slate-600 px-4 py-1.5 text-xs font-semibold text-white hover:bg-slate-700 transition-colors\">Get started</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-3xl px-6 py-28 text-center md:py-36\">\n        <span className=\"inline-block rounded-full border border-white/15 px-3 py-1 text-xs font-semibold uppercase tracking-tight text-slate-300\">FINANCIAL SERVICES</span>\n        <h1 className=\"font-['Georgia',ui-serif,serif] mt-6 text-5xl md:text-6xl font-bold leading-[1.05] tracking-tight\">Wealth planning that starts with your actual goals.</h1>\n        <p className=\"mx-auto mt-5 max-w-xl text-lg text-white/60\">Birchgate builds the plan around your life, not a model portfolio.</p>\n        <div className=\"mt-9 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-md bg-slate-500 px-7 py-3 text-sm font-semibold text-slate-950 hover:bg-slate-400 transition-colors\">Book a call</a>\n          <a href=\"#more\" className=\"rounded-md border border-white/20 px-7 py-3 text-sm font-semibold hover:border-white/40 transition-colors\">Learn more</a>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <div className=\"grid gap-10 md:grid-cols-[1.2fr_1fr]\">\n          <div>\n            <p className=\"font-['Georgia',ui-serif,serif] text-xl font-bold tracking-tight\">Birchgate Capital</p>\n            <p className=\"mt-2 max-w-sm text-sm text-white/50\">Birchgate builds the plan around your life, not a model portfolio.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-tight text-white/40\">Stay in the loop</p>\n            <form className=\"mt-3 flex gap-2\" onSubmit={(e) => e.preventDefault()}>\n              <input type=\"email\" required placeholder=\"you@email.com\" className=\"w-full rounded-md border border-white/15 bg-white/5 px-4 py-2.5 text-sm text-white placeholder:text-white/30 focus:border-slate-400 focus:outline-none\" />\n              <button type=\"submit\" className=\"rounded-md bg-slate-500 px-5 py-2.5 text-sm font-semibold text-slate-950 hover:bg-slate-400 transition-colors\">Join</button>\n            </form>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-3 border-t border-white/10 pt-6 text-xs text-white/40 sm:flex-row\">\n          <div className=\"flex gap-6\">\n            <a href=\"/services\" className=\"hover:text-white\">Services</a>\n            <a href=\"/contact\" className=\"hover:text-white\">Contact</a>\n          </div>\n          <p>&copy; {new Date().getFullYear()} Birchgate Capital</p>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Tell us a bit about what you need — we'll take it from there.</p>\n      <form className=\"mt-8 space-y-4\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-md border border-slate-200 px-4 py-2.5 text-sm focus:border-slate-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-md border border-slate-200 px-4 py-2.5 text-sm focus:border-slate-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-md border border-slate-200 px-4 py-2.5 text-sm focus:border-slate-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-md bg-slate-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-slate-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-slate-600 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold tracking-tight\">Services</h1>\n        <p className=\"mt-3 max-w-xl text-white/75\">Real work, real results — see it for yourself.</p>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid gap-10 md:grid-cols-[1fr_1fr]\">\n        <h2 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold leading-tight tracking-tight text-slate-900\">About Birchgate Capital</h2>\n        <div className=\"space-y-4\">\n          <p className=\"text-slate-600\">Behind Birchgate Capital is a small, focused team that cares more about doing the work right than doing a lot of it. That's shaped everything about how we operate.</p>\n          <div className=\"h-1 w-16 rounded-md bg-gradient-to-r from-slate-500 to-amber-500\" />\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-3xl px-6 py-20 text-center\">\n      <p className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-medium leading-snug text-slate-900\">&ldquo;Cash flow and growth planning for owners. That's exactly what Birchgate Capital delivered.&rdquo;</p>\n      <div className=\"mt-6 flex items-center justify-center gap-3\">\n        <div className=\"h-10 w-10 rounded-md bg-slate-100\" />\n        <div className=\"text-left\">\n          <p className=\"text-sm font-semibold text-slate-900\">Marcus Webb</p>\n          <p className=\"text-xs text-slate-500\">Operations Lead</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"import { Zap, Star, Shield, Sparkles, Target, Heart, Award, TrendingUp, Users, Clock, CheckCircle, Compass } from \"lucide-react\";\n\nexport default function Features() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">What Birchgate Capital offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Birchgate Capital does best.</p>\n      </div>\n      <div className=\"mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-3\">\n        <div className=\"rounded-md border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-md bg-slate-100 text-slate-600\">\n            <Zap size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Retirement planning</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Model your timeline, not just your balance.</p>\n        </div>\n        <div className=\"rounded-md border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-md bg-slate-100 text-slate-600\">\n            <Star size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Tax strategy</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Proactive planning, not just April filing.</p>\n        </div>\n        <div className=\"rounded-md border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-md bg-slate-100 text-slate-600\">\n            <Shield size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Investment management</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Portfolios built around your actual risk tolerance.</p>\n        </div>\n        <div className=\"rounded-md border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-md bg-slate-100 text-slate-600\">\n            <Sparkles size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Estate planning</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Coordinated with your attorney, not separate from it.</p>\n        </div>\n        <div className=\"rounded-md border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-md bg-slate-100 text-slate-600\">\n            <Target size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Business advisory</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Cash flow and growth planning for owners.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Features","About","Testimonial","Footer"]},{"name":"Services","path":"/services","slug":"services","sections":["Navbar","PageHeader","Features","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '3c40b7ff-3243-41c1-9c2c-39aefebe5ef3'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"border-b border-slate-100 bg-white\">\n      <nav className=\"mx-auto grid max-w-6xl grid-cols-3 items-center px-6 py-5\">\n        <div className=\"flex items-center gap-6\">\n          <a href=\"/services\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Services</a>\n        </div>\n        <a href=\"/\" className=\"font-['Palatino',ui-serif,serif] text-center text-xl font-bold tracking-normal text-slate-900\">Cascade Wealth Partners</a>\n        <div className=\"flex items-center justify-end gap-6\">\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n          <a href=\"/contact\" className=\"text-sm font-semibold text-rose-600 hover:text-rose-700\">Contact →</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-rose-600 text-white\">\n      <div className=\"mx-auto max-w-4xl px-6 py-28 text-center md:py-32\">\n        \n        <h1 className=\"font-['Palatino',ui-serif,serif] mt-4 text-4xl md:text-5xl font-bold leading-[0.98] tracking-normal\">Planning for the decade, not the quarter.</h1>\n        <p className=\"mx-auto mt-6 max-w-lg text-lg text-white/85\">Cascade is built for people who want a plan, not a stock tip.</p>\n        <div className=\"mt-9 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-lg bg-white px-7 py-3 text-sm font-semibold text-rose-700 hover:bg-white/90 transition-colors\">Get in touch</a>\n          <a href=\"#more\" className=\"rounded-lg border border-white/50 px-7 py-3 text-sm font-semibold hover:border-white transition-colors\">Explore</a>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer>\n      <div className=\"bg-rose-600 text-white\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-4 px-6 py-14 text-center md:flex-row md:justify-between md:text-left\">\n          <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal\">Ready when you are.</h2>\n          <a href=\"/contact\" className=\"rounded-lg bg-white px-6 py-3 text-sm font-semibold text-rose-700 hover:bg-white/90 transition-colors\">Get in touch</a>\n        </div>\n      </div>\n      <div className=\"bg-white\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center justify-between gap-3 px-6 py-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Cascade Wealth Partners</p>\n          <div className=\"flex gap-6\">\n            <a href=\"/services\" className=\"text-slate-500 hover:text-slate-900\">Services</a>\n            <a href=\"/contact\" className=\"text-slate-500 hover:text-slate-900\">Contact</a>\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Tell us a bit about what you need — we'll take it from there.</p>\n      <form className=\"mt-8 space-y-4\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-rose-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-rose-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-rose-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-lg bg-rose-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-rose-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14 text-center\">\n        <span className=\"text-xs font-semibold uppercase tracking-normal text-rose-600\">Real work, real results — see it for yourself.</span>\n        <h1 className=\"font-['Palatino',ui-serif,serif] mx-auto mt-3 max-w-2xl text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">Services</h1>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid gap-10 md:grid-cols-[1fr_1fr]\">\n        <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold leading-tight tracking-normal text-slate-900\">About Cascade Wealth Partners</h2>\n        <div className=\"space-y-4\">\n          <p className=\"text-slate-600\">Cascade Wealth Partners pairs real experience in financial services with a genuine focus on the people we work with — no jargon, no unnecessary steps, just results.</p>\n          <div className=\"h-1 w-16 rounded-lg bg-gradient-to-r from-rose-500 to-slate-500\" />\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid items-center gap-10 md:grid-cols-[0.8fr_1.2fr]\">\n        <div className=\"aspect-square rounded-lg bg-gradient-to-br from-rose-100 to-slate-100\" />\n        <div>\n          <p className=\"font-['Palatino',ui-serif,serif] text-2xl font-medium leading-snug text-slate-900\">&ldquo;Coordinated with your attorney, not separate from it. That's exactly what Cascade Wealth Partners delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Theo Kwan</p>\n          <p className=\"text-xs text-slate-500\">Founder</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"export default function Features() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">What Cascade Wealth Partners offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Cascade Wealth Partners does best.</p>\n      </div>\n      <div className=\"mt-10 space-y-14\">\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-lg bg-gradient-to-br from-rose-100 to-slate-50 \" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Retirement planning</h3>\n            <p className=\"mt-2 text-slate-500\">Model your timeline, not just your balance.</p>\n          </div>\n        </div>\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-lg bg-gradient-to-br from-slate-100 to-rose-50 md:order-2\" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Tax strategy</h3>\n            <p className=\"mt-2 text-slate-500\">Proactive planning, not just April filing.</p>\n          </div>\n        </div>\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-lg bg-gradient-to-br from-rose-100 to-slate-50 \" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Investment management</h3>\n            <p className=\"mt-2 text-slate-500\">Portfolios built around your actual risk tolerance.</p>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Features","About","Testimonial","Footer"]},{"name":"Services","path":"/services","slug":"services","sections":["Navbar","PageHeader","Features","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '2fb64662-210a-4140-997b-1907528c1ffa'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-0 z-40 border-b border-slate-100 bg-white/80 backdrop-blur\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-4\">\n        <a href=\"/\" className=\"font-['Palatino',ui-serif,serif] text-lg font-bold tracking-normal text-slate-900\">Ledger & Stone</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n          <a href=\"/services\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Services</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-lg bg-orange-600 px-4 py-2 text-sm font-semibold text-white hover:bg-orange-700 transition-colors\">Get in touch</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-4xl px-6 py-24 text-center md:py-28\">\n        \n        <h1 className=\"font-['Palatino',ui-serif,serif] mx-auto mt-5 max-w-3xl text-4xl md:text-5xl font-bold leading-[1.05] tracking-normal text-slate-900\">Financial advice that fits on one page.</h1>\n        <p className=\"mx-auto mt-5 max-w-xl text-lg text-slate-600\">Ledger & Stone builds plans clients actually understand and follow.</p>\n        <div className=\"mt-8 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-lg bg-orange-600 px-6 py-3 text-sm font-semibold text-white hover:bg-orange-700 transition-colors\">Get in touch</a>\n          <a href=\"#more\" className=\"rounded-lg border border-slate-300 px-6 py-3 text-sm font-semibold text-slate-700 hover:border-slate-400 transition-colors\">Explore</a>\n        </div>\n        <div className=\"mx-auto mt-14 grid max-w-2xl grid-cols-3 gap-6 border-t border-slate-200 pt-8\">\n          <div><p className=\"text-2xl font-bold text-slate-900\">98%</p><p className=\"mt-1 text-xs uppercase tracking-normal text-slate-400\">Satisfaction</p></div>\n          <div><p className=\"text-2xl font-bold text-slate-900\">24/7</p><p className=\"mt-1 text-xs uppercase tracking-normal text-slate-400\">Support</p></div>\n          <div><p className=\"text-2xl font-bold text-slate-900\">50+</p><p className=\"mt-1 text-xs uppercase tracking-normal text-slate-400\">Team members</p></div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <div className=\"grid gap-10 md:grid-cols-[1.2fr_1fr]\">\n          <div>\n            <p className=\"font-['Palatino',ui-serif,serif] text-xl font-bold tracking-normal\">Ledger & Stone</p>\n            <p className=\"mt-2 max-w-sm text-sm text-white/50\">Ledger & Stone builds plans clients actually understand and follow.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-normal text-white/40\">Stay in the loop</p>\n            <form className=\"mt-3 flex gap-2\" onSubmit={(e) => e.preventDefault()}>\n              <input type=\"email\" required placeholder=\"you@email.com\" className=\"w-full rounded-lg border border-white/15 bg-white/5 px-4 py-2.5 text-sm text-white placeholder:text-white/30 focus:border-orange-400 focus:outline-none\" />\n              <button type=\"submit\" className=\"rounded-lg bg-orange-500 px-5 py-2.5 text-sm font-semibold text-slate-950 hover:bg-orange-400 transition-colors\">Join</button>\n            </form>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-3 border-t border-white/10 pt-6 text-xs text-white/40 sm:flex-row\">\n          <div className=\"flex gap-6\">\n            <a href=\"/services\" className=\"hover:text-white\">Services</a>\n            <a href=\"/contact\" className=\"hover:text-white\">Contact</a>\n          </div>\n          <p>&copy; {new Date().getFullYear()} Ledger & Stone</p>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Tell us a bit about what you need — we'll take it from there.</p>\n      <form className=\"mt-8 space-y-4\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-orange-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-orange-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-orange-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-lg bg-orange-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-orange-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14 text-center\">\n        <span className=\"text-xs font-semibold uppercase tracking-normal text-orange-600\">Real work, real results — see it for yourself.</span>\n        <h1 className=\"font-['Palatino',ui-serif,serif] mx-auto mt-3 max-w-2xl text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">Services</h1>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-3xl px-6 py-20 text-center\">\n        <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">About Ledger & Stone</h2>\n        <p className=\"mx-auto mt-4 max-w-xl text-slate-600\">Behind Ledger & Stone is a small, focused team that cares more about doing the work right than doing a lot of it. That's shaped everything about how we operate.</p>\n        <div className=\"mx-auto mt-10 grid max-w-lg grid-cols-3 gap-6\">\n          <div><p className=\"text-2xl font-bold text-orange-600\">98%</p><p className=\"mt-1 text-xs uppercase tracking-normal text-slate-400\">Satisfaction</p></div>\n          <div><p className=\"text-2xl font-bold text-orange-600\">24/7</p><p className=\"mt-1 text-xs uppercase tracking-normal text-slate-400\">Support</p></div>\n          <div><p className=\"text-2xl font-bold text-orange-600\">50+</p><p className=\"mt-1 text-xs uppercase tracking-normal text-slate-400\">Team members</p></div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-2xl px-6 py-20\">\n        <div className=\"rounded-lg border border-slate-200 bg-white p-8 shadow-sm\">\n          <div className=\"flex gap-0.5 text-orange-500\">{\"★★★★★\"}</div>\n          <p className=\"mt-4 text-lg text-slate-700\">&ldquo;Proactive planning, not just April filing. That's exactly what Ledger & Stone delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Priya Shah <span className=\"font-normal text-slate-400\">— Marketing Director</span></p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"export default function Features() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">What Ledger & Stone offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Ledger & Stone does best.</p>\n      </div>\n      <div className=\"mt-10 space-y-14\">\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-lg bg-gradient-to-br from-orange-100 to-indigo-50 \" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Retirement planning</h3>\n            <p className=\"mt-2 text-slate-500\">Model your timeline, not just your balance.</p>\n          </div>\n        </div>\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-lg bg-gradient-to-br from-indigo-100 to-orange-50 md:order-2\" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Tax strategy</h3>\n            <p className=\"mt-2 text-slate-500\">Proactive planning, not just April filing.</p>\n          </div>\n        </div>\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-lg bg-gradient-to-br from-orange-100 to-indigo-50 \" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Investment management</h3>\n            <p className=\"mt-2 text-slate-500\">Portfolios built around your actual risk tolerance.</p>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Features","About","Testimonial","Footer"]},{"name":"Services","path":"/services","slug":"services","sections":["Navbar","PageHeader","Features","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '4230d3ca-d5cf-4327-ba13-0498724224a9'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"border-b border-slate-100 bg-white\">\n      <nav className=\"mx-auto grid max-w-6xl grid-cols-3 items-center px-6 py-5\">\n        <div className=\"flex items-center gap-6\">\n          <a href=\"/classes\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Classes</a>\n        </div>\n        <a href=\"/\" className=\"font-['Georgia',ui-serif,serif] text-center text-xl font-bold tracking-tight text-slate-900\">Anchor Athletics</a>\n        <div className=\"flex items-center justify-end gap-6\">\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n          <a href=\"/contact\" className=\"text-sm font-semibold text-orange-600 hover:text-orange-700\">Contact →</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-orange-600 text-white\">\n      <div className=\"mx-auto max-w-4xl px-6 py-28 text-center md:py-32\">\n        <span className=\"text-xs font-semibold uppercase tracking-tight text-white/70\">FITNESS</span>\n        <h1 className=\"font-['Georgia',ui-serif,serif] mt-4 text-5xl md:text-6xl font-bold leading-[0.98] tracking-tight\">Strength training for people who aren't twenty-five anymore.</h1>\n        <p className=\"mx-auto mt-6 max-w-lg text-lg text-white/85\">Anchor programs around real joints and real schedules.</p>\n        <div className=\"mt-9 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-md bg-white px-7 py-3 text-sm font-semibold text-orange-700 hover:bg-white/90 transition-colors\">Get in touch</a>\n          <a href=\"#more\" className=\"rounded-md border border-white/50 px-7 py-3 text-sm font-semibold hover:border-white transition-colors\">Explore</a>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-white\">\n      <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-4 border-t border-slate-100 px-6 py-10 text-center\">\n        <p className=\"font-['Georgia',ui-serif,serif] text-base font-bold tracking-tight text-slate-900\">Anchor Athletics</p>\n        <div className=\"flex flex-wrap items-center justify-center gap-6\">\n          <a href=\"/classes\" className=\"text-sm text-slate-500 hover:text-slate-900\">Classes</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a>\n        </div>\n        <p className=\"text-xs text-slate-400\">&copy; {new Date().getFullYear()} Anchor Athletics &middot; Built with <span className=\"text-orange-600\">webma</span></p>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto grid max-w-5xl gap-10 px-6 py-20 md:grid-cols-2\">\n        <div>\n          <h2 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Get in touch</h2>\n          <p className=\"mt-3 text-slate-500\">Tell us a bit about what you need — we'll take it from there.</p>\n          <div className=\"mt-8 space-y-4 text-sm text-slate-600\">\n            <p><span className=\"font-semibold text-slate-900\">Address</span><br />123 Market Street, Suite 400</p>\n            <p><span className=\"font-semibold text-slate-900\">Hours</span><br />Mon–Fri, 9am–6pm</p>\n          </div>\n        </div>\n        <form className=\"space-y-4 rounded-md border border-slate-200 bg-white p-6\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n          <input name=\"name\" required placeholder=\"Your name\" className=\"w-full rounded-md border border-slate-200 px-4 py-2.5 text-sm focus:border-orange-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full rounded-md border border-slate-200 px-4 py-2.5 text-sm focus:border-orange-500 focus:outline-none\" />\n          <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-md border border-slate-200 px-4 py-2.5 text-sm focus:border-orange-500 focus:outline-none\" />\n          <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n          <button type=\"submit\" className=\"w-full rounded-md bg-orange-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-orange-700 transition-colors\">Send message</button>\n        </form>\n      </div>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"border-b border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Classes</h1>\n        <p className=\"mt-3 max-w-xl text-slate-500\">Everything you need to know about how we approach fitness.</p>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid gap-10 md:grid-cols-[1fr_1fr]\">\n        <h2 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold leading-tight tracking-tight text-slate-900\">About Anchor Athletics</h2>\n        <div className=\"space-y-4\">\n          <p className=\"text-slate-600\">Anchor Athletics pairs real experience in fitness with a genuine focus on the people we work with — no jargon, no unnecessary steps, just results.</p>\n          <div className=\"h-1 w-16 rounded-md bg-gradient-to-r from-orange-500 to-indigo-500\" />\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-3xl px-6 py-20 text-center\">\n      <p className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-medium leading-snug text-slate-900\">&ldquo;Daily, 10:00am – 8:00pm — self-directed training. That's exactly what Anchor Athletics delivered.&rdquo;</p>\n      <div className=\"mt-6 flex items-center justify-center gap-3\">\n        <div className=\"h-10 w-10 rounded-md bg-orange-100\" />\n        <div className=\"text-left\">\n          <p className=\"text-sm font-semibold text-slate-900\">Owen Clarke</p>\n          <p className=\"text-xs text-slate-500\">General Manager</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Location.tsx":"export default function Location() {\n  return (\n    <section className=\"bg-orange-600 text-white\">\n      <div className=\"mx-auto grid max-w-6xl gap-6 px-6 py-16 md:grid-cols-3\">\n        <h2 className=\"font-['Georgia',ui-serif,serif] text-2xl font-bold\">Visit us</h2>\n        <p className=\"text-sm text-white/85\">123 Market Street, Suite 400</p>\n        <p className=\"text-sm text-white/85\"><span className=\"font-semibold text-white\">Hours</span><br />Mon–Fri, 9am–6pm</p>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"import { Zap, Star, Shield, Sparkles, Target, Heart, Award, TrendingUp, Users, Clock, CheckCircle, Compass } from \"lucide-react\";\n\nexport default function Features() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">What Anchor Athletics offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Anchor Athletics does best.</p>\n      </div>\n      <div className=\"mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-3\">\n        <div className=\"rounded-md border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-md bg-orange-100 text-orange-600\">\n            <Zap size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Strength Fundamentals</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Mon/Wed/Fri, 6:00am & 5:30pm — squat, press, pull.</p>\n        </div>\n        <div className=\"rounded-md border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-md bg-orange-100 text-orange-600\">\n            <Star size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Conditioning</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Tue/Thu, 6:00am & 6:00pm — high-intensity intervals.</p>\n        </div>\n        <div className=\"rounded-md border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-md bg-orange-100 text-orange-600\">\n            <Shield size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Open Gym</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Daily, 10:00am – 8:00pm — self-directed training.</p>\n        </div>\n        <div className=\"rounded-md border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-md bg-orange-100 text-orange-600\">\n            <Sparkles size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Mobility & Recovery</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Sat, 9:00am — guided mobility work.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Features","About","Testimonial","Footer"]},{"name":"Classes","path":"/classes","slug":"classes","sections":["Navbar","PageHeader","Features","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Location","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '991cfae5-b62c-407f-8256-134f26f26944'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"border-b border-slate-100 bg-white\">\n      <nav className=\"mx-auto grid max-w-6xl grid-cols-3 items-center px-6 py-5\">\n        <div className=\"flex items-center gap-6\">\n          <a href=\"/classes\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Classes</a>\n        </div>\n        <a href=\"/\" className=\"font-sans text-center text-xl font-bold tracking-wide text-slate-900\">Forge Fitness</a>\n        <div className=\"flex items-center justify-end gap-6\">\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n          <a href=\"/contact\" className=\"text-sm font-semibold text-fuchsia-600 hover:text-fuchsia-700\">Contact →</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-3xl px-6 py-28 text-center md:py-36\">\n        <span className=\"inline-block rounded-full border border-white/15 px-3 py-1 text-xs font-semibold uppercase tracking-wide text-fuchsia-300\">FITNESS</span>\n        <h1 className=\"font-sans mt-6 text-4xl md:text-5xl font-bold leading-[1.05] tracking-wide\">Train like the plan actually matters.</h1>\n        <p className=\"mx-auto mt-5 max-w-xl text-lg text-white/60\">Forge runs coached strength and conditioning classes — real programming, real coaching.</p>\n        <div className=\"mt-9 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-full bg-fuchsia-500 px-7 py-3 text-sm font-semibold text-slate-950 hover:bg-fuchsia-400 transition-colors\">Talk to us</a>\n          <a href=\"#more\" className=\"rounded-full border border-white/20 px-7 py-3 text-sm font-semibold hover:border-whit