t website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n          <input name=\"name\" required placeholder=\"Your name\" className=\"w-full rounded-3xl border border-slate-200 px-4 py-2.5 text-sm focus:border-fuchsia-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full rounded-3xl border border-slate-200 px-4 py-2.5 text-sm focus:border-fuchsia-500 focus:outline-none\" />\n          <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-3xl border border-slate-200 px-4 py-2.5 text-sm focus:border-fuchsia-500 focus:outline-none\" />\n          <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n          <button type=\"submit\" className=\"w-full rounded-full bg-fuchsia-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-fuchsia-700 transition-colors\">Send message</button>\n        </form>\n      </div>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14 text-center\">\n        <span className=\"text-xs font-semibold uppercase tracking-wide text-fuchsia-600\">Everything you need to know about how we approach fitness.</span>\n        <h1 className=\"font-sans mx-auto mt-3 max-w-2xl text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">Classes</h1>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-3xl px-6 py-20 text-center\">\n        <h2 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">About Forge Fitness</h2>\n        <p className=\"mx-auto mt-4 max-w-xl text-slate-600\">Forge Fitness pairs real experience in fitness with a genuine focus on the people we work with — no jargon, no unnecessary steps, just results.</p>\n        <div className=\"mx-auto mt-10 grid max-w-lg grid-cols-3 gap-6\">\n          <div><p className=\"text-2xl font-bold text-fuchsia-600\">1,200+</p><p className=\"mt-1 text-xs uppercase tracking-wide text-slate-400\">Projects delivered</p></div>\n          <div><p className=\"text-2xl font-bold text-fuchsia-600\">15</p><p className=\"mt-1 text-xs uppercase tracking-wide text-slate-400\">Industries served</p></div>\n          <div><p className=\"text-2xl font-bold text-fuchsia-600\">99%</p><p className=\"mt-1 text-xs uppercase tracking-wide text-slate-400\">On-time delivery</p></div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-2xl px-6 py-20\">\n        <div className=\"rounded-3xl border border-slate-200 bg-white p-8 shadow-sm\">\n          <div className=\"flex gap-0.5 text-fuchsia-500\">{\"★★★★★\"}</div>\n          <p className=\"mt-4 text-lg text-slate-700\">&ldquo;Tue/Thu, 6:00am & 6:00pm — high-intensity intervals. That's exactly what Forge Fitness delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Priya Shah <span className=\"font-normal text-slate-400\">— Client</span></p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Location.tsx":"export default function Location() {\n  return (\n    <section className=\"bg-fuchsia-600 text-white\">\n      <div className=\"mx-auto grid max-w-6xl gap-6 px-6 py-16 md:grid-cols-3\">\n        <h2 className=\"font-sans text-2xl font-bold\">Visit us</h2>\n        <p className=\"text-sm text-white/85\">123 Market Street, Suite 400</p>\n        <p className=\"text-sm text-white/85\"><span className=\"font-semibold text-white\">Hours</span><br />Mon–Fri, 9am–6pm</p>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"import { Zap, Star, Shield, Sparkles, Target, Heart, Award, TrendingUp, Users, Clock, CheckCircle, Compass } from \"lucide-react\";\n\nexport default function Features() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-4xl px-6 py-20\">\n        <h2 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">What Forge Fitness offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Forge Fitness does best.</p>\n        <div className=\"mt-10 divide-y divide-slate-200\">\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-3xl bg-white text-fuchsia-600 shadow-sm\"><Zap size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Strength Fundamentals</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Mon/Wed/Fri, 6:00am & 5:30pm — squat, press, pull.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-3xl bg-white text-fuchsia-600 shadow-sm\"><Star size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Conditioning</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Tue/Thu, 6:00am & 6:00pm — high-intensity intervals.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-3xl bg-white text-fuchsia-600 shadow-sm\"><Shield size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Open Gym</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Daily, 10:00am – 8:00pm — self-directed training.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-3xl bg-white text-fuchsia-600 shadow-sm\"><Sparkles size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Mobility & Recovery</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Sat, 9:00am — guided mobility work.</p>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Features","About","Testimonial","Footer"]},{"name":"Classes","path":"/classes","slug":"classes","sections":["Navbar","PageHeader","Features","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Location","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '73d79eaf-cba5-44ba-baf6-81d281f55ab3'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-4 z-40 mx-auto max-w-4xl px-4\">\n      <nav className=\"flex items-center justify-between gap-4 rounded-full border border-slate-200 bg-white/95 px-6 py-3 shadow-sm backdrop-blur\">\n        <a href=\"/\" className=\"font-sans text-sm font-bold tracking-wide text-slate-900\">Iron & Oak Gym</a>\n        <div className=\"hidden items-center gap-6 md:flex\">\n          <a href=\"/classes\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Classes</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-full bg-rose-600 px-4 py-1.5 text-xs font-semibold text-white hover:bg-rose-700 transition-colors\">Get started</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-2 md:py-32\">\n        <div>\n          <span className=\"inline-block rounded-full bg-rose-100 px-3 py-1 text-xs font-semibold uppercase tracking-wide text-rose-700\">FITNESS</span>\n          <h1 className=\"font-sans mt-5 text-4xl md:text-5xl font-bold leading-[1.05] tracking-wide text-slate-900\">No mirrors, no ego, just work.</h1>\n          <p className=\"mt-5 max-w-lg text-lg text-slate-600\">A gym built for people who want to get stronger, not seen.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-full bg-rose-600 px-6 py-3 text-sm font-semibold text-white hover:bg-rose-700 transition-colors\">Start now</a>\n            <a href=\"#more\" className=\"rounded-full border border-slate-200 px-6 py-3 text-sm font-semibold text-slate-700 hover:border-slate-400 transition-colors\">View details</a>\n          </div>\n        </div>\n        <div className=\"aspect-[4/3] rounded-3xl bg-gradient-to-br from-rose-100 via-rose-50 to-slate-50 ring-1 ring-rose-100\" />\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <div className=\"grid gap-10 md:grid-cols-[1.2fr_1fr]\">\n          <div>\n            <p className=\"font-sans text-xl font-bold tracking-wide\">Iron & Oak Gym</p>\n            <p className=\"mt-2 max-w-sm text-sm text-white/50\">A gym built for people who want to get stronger, not seen.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wide text-white/40\">Stay in the loop</p>\n            <form className=\"mt-3 flex gap-2\" onSubmit={(e) => e.preventDefault()}>\n              <input type=\"email\" required placeholder=\"you@email.com\" className=\"w-full rounded-3xl border border-white/15 bg-white/5 px-4 py-2.5 text-sm text-white placeholder:text-white/30 focus:border-rose-400 focus:outline-none\" />\n              <button type=\"submit\" className=\"rounded-full bg-rose-500 px-5 py-2.5 text-sm font-semibold text-slate-950 hover:bg-rose-400 transition-colors\">Join</button>\n            </form>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-3 border-t border-white/10 pt-6 text-xs text-white/40 sm:flex-row\">\n          <div className=\"flex gap-6\">\n            <a href=\"/classes\" className=\"hover:text-white\">Classes</a>\n            <a href=\"/contact\" className=\"hover:text-white\">Contact</a>\n          </div>\n          <p>&copy; {new Date().getFullYear()} Iron & Oak Gym</p>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-xl px-6 py-24 text-center\">\n      <h2 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Tell us a bit about what you need — we'll take it from there.</p>\n      <form className=\"mt-10 space-y-3 text-left\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <input name=\"name\" required placeholder=\"Your name\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-rose-500 focus:outline-none\" />\n        <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-rose-500 focus:outline-none\" />\n        <textarea name=\"message\" required rows={3} placeholder=\"How can we help?\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-rose-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"mt-4 w-full rounded-full bg-rose-600 px-6 py-3 text-sm font-semibold text-white hover:bg-rose-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-rose-600 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide\">Classes</h1>\n        <p className=\"mt-3 max-w-xl text-white/75\">Everything you need to know about how we approach fitness.</p>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-3xl px-6 py-20 text-center\">\n        <h2 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">About Iron & Oak Gym</h2>\n        <p className=\"mx-auto mt-4 max-w-xl text-slate-600\">We started Iron & Oak Gym because the existing options in fitness were either too slow or too generic. Every decision here is made with our clients' actual outcomes in mind.</p>\n        <div className=\"mx-auto mt-10 grid max-w-lg grid-cols-3 gap-6\">\n          <div><p className=\"text-2xl font-bold text-rose-600\">98%</p><p className=\"mt-1 text-xs uppercase tracking-wide text-slate-400\">Satisfaction</p></div>\n          <div><p className=\"text-2xl font-bold text-rose-600\">24/7</p><p className=\"mt-1 text-xs uppercase tracking-wide text-slate-400\">Support</p></div>\n          <div><p className=\"text-2xl font-bold text-rose-600\">50+</p><p className=\"mt-1 text-xs uppercase tracking-wide text-slate-400\">Team members</p></div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid items-center gap-10 md:grid-cols-[0.8fr_1.2fr]\">\n        <div className=\"aspect-square rounded-3xl bg-gradient-to-br from-rose-100 to-slate-100\" />\n        <div>\n          <p className=\"font-sans text-2xl font-medium leading-snug text-slate-900\">&ldquo;Sat, 9:00am — guided mobility work. That's exactly what Iron & Oak Gym delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Sofia Reyes</p>\n          <p className=\"text-xs text-slate-500\">General Manager</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Location.tsx":"export default function Location() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 pb-20\">\n      <div className=\"grid gap-6 rounded-3xl border border-slate-100 p-8 md:grid-cols-2\">\n        <div>\n          <h2 className=\"text-xl font-bold text-slate-900\">Visit us</h2>\n          <p className=\"mt-3 text-sm text-slate-600\">123 Market Street, Suite 400</p>\n          <p className=\"mt-4 text-xs font-semibold uppercase tracking-wider text-rose-600\">Hours</p>\n          <p className=\"mt-1 text-sm text-slate-500\">Mon–Fri, 9am–6pm</p>\n        </div>\n        <div className=\"aspect-[4/3] rounded-3xl bg-gradient-to-br from-rose-100 to-rose-50\" />\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"export default function Features() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">What Iron & Oak Gym offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Iron & Oak Gym does best.</p>\n      </div>\n      <div className=\"mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3\">\n        <div className=\"overflow-hidden rounded-3xl border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-rose-100 to-slate-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Strength Fundamentals</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Mon/Wed/Fri, 6:00am & 5:30pm — squat, press, pull.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-3xl border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-rose-100 to-slate-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Conditioning</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Tue/Thu, 6:00am & 6:00pm — high-intensity intervals.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-3xl border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-rose-100 to-slate-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Open Gym</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Daily, 10:00am – 8:00pm — self-directed training.</p>\n          </div>\n        </div>\n        <div className=\"overflow-hidden rounded-3xl border border-slate-100\">\n          <div className=\"aspect-[4/3] bg-gradient-to-br from-rose-100 to-slate-50\" />\n          <div className=\"p-5\">\n            <h3 className=\"font-semibold text-slate-900\">Mobility & Recovery</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Sat, 9:00am — guided mobility work.</p>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Features","About","Testimonial","Footer"]},{"name":"Classes","path":"/classes","slug":"classes","sections":["Navbar","PageHeader","Features","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Location","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = 'd928871d-f149-45c5-9ea1-8eeebd57ad9d'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"border-b border-slate-100 bg-white\">\n      <nav className=\"mx-auto grid max-w-6xl grid-cols-3 items-center px-6 py-5\">\n        <div className=\"flex items-center gap-6\">\n          <a href=\"/classes\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Classes</a>\n        </div>\n        <a href=\"/\" className=\"font-['Georgia',ui-serif,serif] text-center text-xl font-bold tracking-tight text-slate-900\">Pulse Studio</a>\n        <div className=\"flex items-center justify-end gap-6\">\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n          <a href=\"/contact\" className=\"text-sm font-semibold text-violet-600 hover:text-violet-700\">Contact →</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-3xl px-6 py-28 text-center md:py-36\">\n        <span className=\"inline-block rounded-full border border-white/15 px-3 py-1 text-xs font-semibold uppercase tracking-tight text-violet-300\">FITNESS</span>\n        <h1 className=\"font-['Georgia',ui-serif,serif] mt-6 text-5xl md:text-6xl font-bold leading-[1.05] tracking-tight\">Forty-five minutes, every time, no wasted reps.</h1>\n        <p className=\"mx-auto mt-5 max-w-xl text-lg text-white/60\">Pulse classes are programmed by coaches, not algorithms.</p>\n        <div className=\"mt-9 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-md bg-violet-500 px-7 py-3 text-sm font-semibold text-slate-950 hover:bg-violet-400 transition-colors\">Start now</a>\n          <a href=\"#more\" className=\"rounded-md border border-white/20 px-7 py-3 text-sm font-semibold ho