sName=\"aspect-[4/3] rounded-none bg-gradient-to-br from-violet-100 via-violet-50 to-lime-50 ring-1 ring-violet-100\" />\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer>\n      <div className=\"bg-violet-600 text-white\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-4 px-6 py-14 text-center md:flex-row md:justify-between md:text-left\">\n          <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter\">Ready when you are.</h2>\n          <a href=\"/contact\" className=\"rounded-none bg-white px-6 py-3 text-sm font-semibold text-violet-700 hover:bg-white/90 transition-colors\">Get in touch</a>\n        </div>\n      </div>\n      <div className=\"bg-white\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center justify-between gap-3 px-6 py-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Harborview Clinic</p>\n          <div className=\"flex gap-6\">\n            <a href=\"/services\" className=\"text-slate-500 hover:text-slate-900\">Services</a>\n            <a href=\"/contact\" className=\"text-slate-500 hover:text-slate-900\">Contact</a>\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">We usually reply within one business day.</p>\n      <form className=\"mt-8 space-y-4\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-violet-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-violet-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-violet-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-none bg-violet-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-violet-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-violet-600 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter\">Services</h1>\n        <p className=\"mt-3 max-w-xl text-white/75\">Everything you need to know about how we approach healthcare.</p>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid gap-10 md:grid-cols-[1fr_1fr]\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold leading-tight tracking-tighter text-slate-900\">About Harborview Clinic</h2>\n        <div className=\"space-y-4\">\n          <p className=\"text-slate-600\">Harborview Clinic is built around one idea: healthcare shouldn't be complicated. We keep things clear, direct, and focused on what actually moves the needle.</p>\n          <div className=\"h-1 w-16 rounded-none bg-gradient-to-r from-violet-500 to-lime-500\" />\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid items-center gap-10 md:grid-cols-[0.8fr_1.2fr]\">\n        <div className=\"aspect-square rounded-none bg-gradient-to-br from-violet-100 to-lime-100\" />\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl font-medium leading-snug text-slate-900\">&ldquo;From newborn checkups through adolescence. That's exactly what Harborview Clinic delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Theo Kwan</p>\n          <p className=\"text-xs text-slate-500\">Client</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Location.tsx":"export default function Location() {\n  return (\n    <section className=\"bg-violet-600 text-white\">\n      <div className=\"mx-auto grid max-w-6xl gap-6 px-6 py-16 md:grid-cols-3\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl font-bold\">Visit us</h2>\n        <p className=\"text-sm text-white/85\">123 Market Street, Suite 400</p>\n        <p className=\"text-sm text-white/85\"><span className=\"font-semibold text-white\">Hours</span><br />Mon–Fri, 9am–6pm</p>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"import { Zap, Star, Shield, Sparkles, Target, Heart, Award, TrendingUp, Users, Clock, CheckCircle, Compass } from \"lucide-react\";\n\nexport default function Features() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">What Harborview Clinic offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Harborview Clinic does best.</p>\n      </div>\n      <div className=\"mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-3\">\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-violet-100 text-violet-600\">\n            <Zap size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Annual physicals</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Thorough checkups with same-week scheduling.</p>\n        </div>\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-violet-100 text-violet-600\">\n            <Star size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Chronic care management</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Ongoing support for diabetes, hypertension, and more.</p>\n        </div>\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-violet-100 text-violet-600\">\n            <Shield size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Pediatric care</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">From newborn checkups through adolescence.</p>\n        </div>\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-violet-100 text-violet-600\">\n            <Sparkles size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Same-day sick visits</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Reserved slots held open every weekday.</p>\n        </div>\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-violet-100 text-violet-600\">\n            <Target size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Lab & diagnostics</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">On-site bloodwork with results in 24–48 hours.</p>\n        </div>\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-violet-100 text-violet-600\">\n            <Heart size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Telehealth</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Virtual visits for follow-ups and minor concerns.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Features","About","Testimonial","Footer"]},{"name":"Services","path":"/services","slug":"services","sections":["Navbar","PageHeader","Features","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Location","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = 'c1af8158-4e9f-4acc-a18b-ff3ce484cc71'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-4 z-40 mx-auto max-w-4xl px-4\">\n      <nav className=\"flex items-center justify-between gap-4 rounded-full border border-slate-200 bg-white/95 px-6 py-3 shadow-sm backdrop-blur\">\n        <a href=\"/\" className=\"font-['Courier_New',ui-monospace,monospace] text-sm font-bold tracking-tight text-slate-900\">Riverside Health Partners</a>\n        <div className=\"hidden items-center gap-6 md:flex\">\n          <a href=\"/services\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Services</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-full bg-orange-600 px-4 py-1.5 text-xs font-semibold text-white hover:bg-orange-700 transition-colors\">Get started</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-[0.9fr_1.1fr] md:py-28\">\n        <div className=\"aspect-square rounded-sm bg-gradient-to-tr from-indigo-100 to-orange-100 ring-1 ring-orange-100 md:order-1\" />\n        <div className=\"md:order-2\">\n          <span className=\"text-xs font-semibold uppercase tracking-tight text-orange-600\">HEALTHCARE</span>\n          <h1 className=\"font-['Courier_New',ui-monospace,monospace] mt-3 text-4xl md:text-5xl font-bold leading-[1.02] tracking-tight text-slate-900\">Primary care, without the three-week wait.</h1>\n          <p className=\"mt-5 max-w-md text-lg text-slate-600\">Riverside holds same-week appointments open for exactly this reason.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-sm bg-orange-600 px-6 py-3 text-sm font-semibold text-white hover:bg-orange-700 transition-colors\">Talk to us</a>\n            <a href=\"#more\" className=\"text-sm font-semibold text-slate-700 underline decoration-slate-300 underline-offset-4 hover:decoration-slate-600\">See examples</a>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer>\n      <div className=\"bg-orange-600 text-white\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-4 px-6 py-14 text-center md:flex-row md:justify-between md:text-left\">\n          <h2 className=\"font-['Courier_New',ui-monospace,monospace] text-xl md:text-2xl font-bold tracking-tight\">Ready when you are.</h2>\n          <a href=\"/contact\" className=\"rounded-sm bg-white px-6 py-3 text-sm font-semibold text-orange-700 hover:bg-white/90 transition-colors\">Get in touch</a>\n        </div>\n      </div>\n      <div className=\"bg-white\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center justify-between gap-3 px-6 py-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Riverside Health Partners</p>\n          <div className=\"flex gap-6\">\n            <a href=\"/services\" className=\"text-slate-500 hover:text-slate-900\">Services</a>\n            <a href=\"/contact\" className=\"text-slate-500 hover:text-slate-900\">Contact</a>\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto grid max-w-5xl gap-10 px-6 py-20 md:grid-cols-2\">\n        <div>\n          <h2 className=\"font-['Courier_New',ui-monospace,monospace] text-xl md:text-2xl font-bold tracking-tight text-slate-900\">Get in touch</h2>\n          <p className=\"mt-3 text-slate-500\">We usually reply within one business day.</p>\n          <div className=\"mt-8 space-y-4 text-sm text-slate-600\">\n            <p><span className=\"font-semibold text-slate-900\">Address</span><br />123 Market Street, Suite 400</p>\n            <p><span className=\"font-semibold text-slate-900\">Hours</span><br />Mon–Fri, 9am–6pm</p>\n          </div>\n        </div>\n        <form className=\"space-y-4 rounded-sm border border-slate-200 bg-white p-6\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n          <input name=\"name\" required placeholder=\"Your name\" className=\"w-full rounded-sm border border-slate-200 px-4 py-2.5 text-sm focus:border-orange-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full rounded-sm border border-slate-200 px-4 py-2.5 text-sm focus:border-orange-500 focus:outline-none\" />\n          <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-sm border border-slate-200 px-4 py-2.5 text-sm focus:border-orange-500 focus:outline-none\" />\n          <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n          <button type=\"submit\" className=\"w-full rounded-sm bg-orange-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-orange-700 transition-colors\">Send message</button>\n        </form>\n      </div>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-orange-600 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-['Courier_New',ui-monospace,monospace] text-xl md:text-2xl font-bold tracking-tight\">Services</h1>\n        <p className=\"mt-3 max-w-xl text-white/75\">Everything you need to know about how we approach healthcare.</p>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-3xl px-6 py-20 text-center\">\n        <h2 className=\"font-['Courier_New',ui-monospace,monospace] text-xl md:text-2xl font-bold tracking-tight text-slate-900\">About Riverside Health Partners</h2>\n        <p className=\"mx-auto mt-4 max-w-xl text-slate-600\">Riverside Health Partners is built around one idea: healthcare shouldn't be complicated. We keep things clear, direct, and focused on what actually moves the needle.</p>\n        <div className=\"mx-auto mt-10 grid max-w-lg grid-cols-3 gap-6\">\n          <div><p className=\"text-2xl font-bold text-orange-600\">500+</p><p className=\"mt-1 text-xs uppercase tracking-tight text-slate-400\">Clients served</p></div>\n          <div><p className=\"text-2xl font-bold text-orange-600\">10 yrs</p><p className=\"mt-1 text-xs uppercase tracking-tight text-slate-400\">In business</p></div>\n          <div><p className=\"text-2xl font-bold text-orange-600\">4.9/5</p><p className=\"mt-1 text-xs uppercase tracking-tight text-slate-400\">Avg. rating</p></div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-2xl px-6 py-20\">\n        <div className=\"rounded-sm border border-slate-200 bg-white p-8 shadow-sm\">\n          <div className=\"flex gap-0.5 text-orange-500\">{\"★★★★★\"}</div>\n          <p className=\"mt-4 text-lg text-slate-700\">&ldquo;Thorough checkups with same-week scheduling. That's exactly what Riverside Health Partners delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Marcus Webb <span className=\"font-normal text-slate-400\">— Operations Lead</span></p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Location.tsx":"export default function Location() {\n  return (\n    <section className=\"bg-orange-600 text-white\">\n      <div className=\"mx-auto grid max-w-6xl gap-6 px-6 py-16 md:grid-cols-3\">\n        <h2 className=\"font-['Courier_New',ui-monospace,monospace] text-2xl font-bold\">Visit us</h2>\n        <p className=\"text-sm text-white/85\">123 Market Street, Suite 400</p>\n        <p className=\"text-sm text-white/85\"><span className=\"font-semibold text-white\">Hours</span><br />Mon–Fri, 9am–6pm</p>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"export default function Features() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Courier_New',ui-monospace,monospace] text-xl md:text-2xl font-bold tracking-tight text-slate-900\">What Riverside Health Partners offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Riverside Health Partners does best.</p>\n      </div>\n      <div className=\"mt-10 space-y-14\">\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-sm bg-gradient-to-br from-orange-100 to-indigo-50 \" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Annual physicals</h3>\n            <p className=\"mt-2 text-slate-500\">Thorough checkups with same-week scheduling.</p>\n          </div>\n        </div>\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-sm bg-gradient-to-br from-indigo-100 to-orange-50 md:order-2\" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Chronic care management</h3>\n            <p className=\"mt-2 text-slate-500\">Ongoing support for diabetes, hypertension, and more.</p>\n          </div>\n        </div>\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-sm bg-gradient-to-br from-orange-100 to-indigo-50 \" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Pediatric care</h3>\n            <p className=\"mt-2 text-slate-500\">From newborn checkups through adolescence.</p>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Features","About","Testimonial","Footer"]},{"name":"Services","path":"/services","slug":"services","sections":["Navbar","PageHeader","Features","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Location","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '1258d9b7-2ed9-44f1-88d0-9826a6bc82ac'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"bg-teal-600\">\n      <nav className=\"mx-auto flex max-w-6xl flex-wrap items-center justify-between gap-4 px-6 py-4\">\n        <a href=\"/\" className=\"font-['Verdana',ui-sans-serif,sans-serif] text-lg font-bold tracking-tight text-white\">Wellpoint Family Clinic</a>\n        <div className=\"flex items-center gap-6\">\n          <a href=\"/services\" className=\"text-sm font-medium text-white/80 hover:text-white transition-colors\">Services</a>\n          <a href=\"/contact\" className=\"text-sm font-medium text-white/80 hover:text-white transition-colors\">Contact</a>\n          <a href=\"/contact\" className=\"rounded-full bg-white px-4 py-2 text-sm font-semibold text-teal-700 hover:bg-white/90 transition-colors\">Contact</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-4xl px-6 py-24 text-center md:py-28\">\n        <span className=\"inline-block rounded-full bg-white px-3 py-1 text-xs font-semibold uppercase tracking-tight text-teal-700 shadow-sm\">HEALTHCARE</span>\n        <h1 className=\"font-['Verdana',ui-sans-serif,sans-serif] mx-auto mt-5 max-w-3xl text-4xl md:text-6xl font-bold leading-[1.05] tracking-tight text-slate-900\">Family medicine that actually has time for you.</h1>\n        <p className=\"mx-auto mt-5 max-w-xl text-lg text-slate-600\">Wellpoint keeps panel sizes small so every visit gets a full 30 minutes.</p>\n        <div className=\"mt-8 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-full bg-teal-600 px-6 py-3 text-sm font-semibold text-white hover:bg-teal-700 transition-colors\">Start now</a>\n          <a href=\"#more\" className=\"rounded-full border border-slate-300 px-6 py-3 text-sm font-semibold text-slate-700 hover:border-slate-400 transition-colors\">View details</a>\n        </div>\n        <div className=\"mx-auto mt-14 grid max-w-2xl grid-cols-3 gap-6 border-t border-slate-200 pt-8\">\n          <div><p className=\"text-2xl font-bold text-slate-900\">500+</p><p className=\"mt-1 text-xs uppercase tracking-tight text-slate-400\">Clients served</p></div>\n          <div><p className=\"text-2xl font-bold text-slate-900\">10 yrs</p><p className=\"mt-1 text-xs uppercase tracking-tight text-slate-400\">In business</p></div>\n          <div><p className=\"text-2xl font-bold text-slate-900\">4.9/5</p><p className=\"mt-1 text-xs uppercase tracking-tight text-slate-400\">Avg. rating</p></div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"border-t border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto flex max-w-6xl flex-col gap-8 px-6 py-14 md:flex-row md:items-start md:justify-between\">\n        <div className=\"max-w-sm\">\n          <p className=\"font-['Verdana',ui-sans-serif,sans-serif] text-lg font-bold tracking-tight text-slate-900\">Wellpoint Family Clinic</p>\n          <p className=\"mt-2 text-sm text-slate-500\">Wellpoint keeps panel sizes small so every visit gets a full 30 minutes.</p>\n        </div>\n        <div className=\"flex gap-8\">\n          <a href=\"/services\" className=\"text-sm text-slate-500 hover:text-slate-900\">Services</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a>\n        </div>\n      </div>\n      <div className=\"border-t border-slate-200\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center justify-between gap-3 px-6 py-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Wellpoint Family Clinic. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-teal-600\"><span className=\"h-1.5 w-1.5 rounded-full bg-teal-600\" /> Built with webma</div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-['Verdana',ui-sans-serif,sans-serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">We usually reply within one business day.</p>\n      <form className=\"mt-8 space-y-4\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-2xl border border-slate-200 px-4 py-2.5 text-sm focus:border-teal-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-2xl border border-slate-200 px-4 py-2.5 text-sm focus:border-teal-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-2xl border border-slate-200 px-4 py-2.5 text-sm focus:border-teal-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-full bg-teal-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-teal-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14 text-center\">\n        <span className=\"text-xs font-semibold uppercase tracking-tight text-teal-600\">Everything you need to know about how we approach healthcare.</span>\n        <h1 className=\"font-['Verdana',ui-sans-serif,sans-serif] mx-auto mt-3 max-w-2xl text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Services</h1>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-3xl px-6 py-20 text-center\">\n        <h2 className=\"font-['Verdana',ui-sans-serif,sans-serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">About Wellpoint Family Clinic</h2>\n        <p className=\"mx-auto mt-4 max-w-xl text-slate-600\">Wellpoint Family Clinic is built around one idea: healthcare shouldn't be complicated. We keep things clear, direct, and focused on what actually moves the needle.</p>\n        <div className=\"mx-auto mt-10 grid max-w-lg grid-cols-3 gap-6\">\n          <div><p className=\"text-2xl font-bold text-teal-600\">500+</p><p className=\"mt-1 text-xs uppercase tracking-tight text-slate-400\">Clients served</p></div>\n          <div><p className=\"text-2xl font-bold text-teal-600\">10 yrs</p><p className=\"mt-1 text-xs uppercase tracking-tight text-slate-400\">In business</p></div>\n          <div><p className=\"text-2xl font-bold text-teal-600\">4.9/5</p><p className=\"mt-1 text-xs uppercase tracking-tight text-slate-400\">Avg. rating</p></div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-2xl px-6 py-20\">\n        <div className=\"rounded-2xl border border-slate-200 bg-white p-8 shadow-sm\">\n          <div className=\"flex gap-0.5 text-teal-500\">{\"★★★★★\"}</div>\n          <p className=\"mt-4 text-lg text-slate-700\">&ldquo;Thorough checkups with same-week scheduling. That's exactly what Wellpoint Family Clinic delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Owen Clarke <span className=\"font-normal text-slate-400\">— General Manager</span></p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Location.tsx":"export default function Location() {\n  return (\n    <section className=\"bg-teal-600 text-white\">\n      <div className=\"mx-auto grid max-w-6xl gap-6 px-6 py-16 md:grid-cols-3\">\n        <h2 className=\"font-['Verdana',ui-sans-serif,sans-serif] text-2xl font-bold\">Visit us</h2>\n        <p className=\"text-sm text-white/85\">123 Market Street, Suite 400</p>\n        <p className=\"text-sm text-white/85\"><span className=\"font-semibold text-white\">Hours</span><br />Mon–Fri, 9am–6pm</p>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"export default function Features() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Verdana',ui-sans-serif,sans-serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">What Wellpoint Family Clinic offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Wellpoint Family Clinic does best.</p>\n      </div>\n      <div className=\"mt-10 grid gap-8 sm:grid-cols-2 lg:grid-cols-3\">\n        <div>\n          <p className=\"font-['Verdana',ui-sans-serif,sans-serif] text-4xl font-bold text-teal-200\">01</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Annual physicals</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Thorough checkups with same-week scheduling.</p>\n        </div>\n        <div>\n          <p className=\"font-['Verdana',ui-sans-serif,sans-serif] text-4xl font-bold text-teal-200\">02</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Chronic care management</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Ongoing support for diabetes, hypertension, and more.</p>\n        </div>\n        <div>\n          <p className=\"font-['Verdana',ui-sans-serif,sans-serif] text-4xl font-bold text-teal-200\">03</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Pediatric care</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">From newborn checkups through adolescence.</p>\n        </div>\n        <div>\n          <p className=\"font-['Verdana',ui-sans-serif,sans-serif] text-4xl font-bold text-teal-200\">04</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Same-day sick visits</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Reserved slots held open every weekday.</p>\n        </div>\n        <div>\n          <p className=\"font-['Verdana',ui-sans-serif,sans-serif] text-4xl font-bold text-teal-200\">05</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Lab & diagnostics</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">On-site bloodwork with results in 24–48 hours.</p>\n        </div>\n        <div>\n          <p className=\"font-['Verdana',ui-sans-serif,sans-serif] text-4xl font-bold text-teal-200\">06</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Telehealth</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Virtual visits for follow-ups and minor concerns.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Features","About","Testimonial","Footer"]},{"name":"Services","path":"/services","slug":"services","sections":["Navbar","PageHeader","Features","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Location","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = 'df0f3b68-a137-405a-a3e7-6013f8b26143'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-0 z-40 border-b border-slate-100 bg-white/80 backdrop-blur\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-4\">\n        <a href=\"/\" className=\"font-['Georgia',ui-serif,serif] text-lg font-bold tracking-tight text-slate-900\">Birchwood Lodge</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n          <a href=\"/rooms\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Rooms</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-md bg-fuchsia-600 px-4 py-2 text-sm font-semibold text-white hover:bg-fuchsia-700 transition-colors\">Get in touch</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-4xl px-6 py-24 text-center md:py-28\">\n        <span className=\"inline-block rounded-md bg-white px-3 py-1 text-xs font-semibold uppercase tracking-tight text-fuchsia-700 shadow-sm\">HOSPITALITY</span>\n        <h1 className=\"font-['Georgia',ui-serif,serif] mx-auto mt-5 max-w-3xl text-5xl md:text-6xl font-bold leading-[1.05] tracking-tight text-slate-900\">Mountain air, hotel comfort.</h1>\n        <p className=\"mx-auto mt-5 max-w-xl text-lg text-slate-600\">Birchwood pairs alpine views with a bed you won't want to leave.</p>\n        <div className=\"mt-8 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-md bg-fuchsia-600 px-6 py-3 text-sm font-semibold text-white hover:bg-fuchsia-700 transition-colors\">Talk to us</a>\n          <a href=\"#more\" className=\"rounded-md border border-slate-300 px-6 py-3 text-sm font-semibold text-slate-700 hover:border-slate-400 transition-colors\">See examples</a>\n        </div>\n        <div className=\"mx-auto mt-14 grid max-w-2xl grid-cols-3 gap-6 border-t border-slate-200 pt-8\">\n          <div><p className=\"text-2xl font-bold text-slate-900\">500+</p><p className=\"mt-1 text-xs uppercase tracking-tight text-slate-400\">Clients served</p></div>\n          <div><p className=\"text-2xl font-bold text-slate-900\">10 yrs</p><p className=\"mt-1 text-xs uppercase tracking-tight text-slate-400\">In business</p></div>\n          <div><p className=\"text-2xl font-bold text-slate-900\">4.9/5</p><p className=\"mt-1 text-xs uppercase tracking-tight text-slate-400\">Avg. rating</p></div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer>\n      <div className=\"bg-fuchsia-600 text-white\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-4 px-6 py-14 text-center md:flex-row md:justify-between md:text-left\">\n          <h2 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold tracking-tight\">Ready when you are.</h2>\n          <a href=\"/contact\" className=\"rounded-md bg-white px-6 py-3 text-sm font-semibold text-fuchsia-700 hover:bg-white/90 transition-colors\">Get in touch</a>\n        </div>\n      </div>\n      <div className=\"bg-white\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center justify-between gap-3 px-6 py-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Birchwood Lodge</p>\n          <div className=\"flex gap-6\">\n            <a href=\"/rooms\" className=\"text-slate-500 hover:text-slate-900\">Rooms</a>\n            <a href=\"/contact\" className=\"text-slate-500 hover:text-slate-900\">Contact</a>\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-xl px-6 py-24 text-center\">\n      <h2 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Tell us a bit about what you need — we'll take it from there.</p>\n      <form className=\"mt-10 space-y-3 text-left\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <input name=\"name\" required placeholder=\"Your name\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-fuchsia-500 focus:outline-none\" />\n        <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-fuchsia-500 focus:outline-none\" />\n        <textarea name=\"message\" required rows={3} placeholder=\"How can we help?\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-fuchsia-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"mt-4 w-full rounded-md bg-fuchsia-600 px-6 py-3 text-sm font-semibold text-white hover:bg-fuchsia-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14 text-center\">\n        <span className=\"text-xs font-semibold uppercase tracking-tight text-fuchsia-600\">Everything you need to know about how we approach hospitality.</span>\n        <h1 className=\"font-['Georgia',ui-serif,serif] mx-auto mt-3 max-w-2xl text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Rooms</h1>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid gap-10 md:grid-cols-[1fr_1fr]\">\n        <h2 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold leading-tight tracking-tight text-slate-900\">About Birchwood Lodge</h2>\n        <div className=\"space-y-4\">\n          <p className=\"text-slate-600\">We started Birchwood Lodge because the existing options in hospitality were either too slow or too generic. Every decision here is made with our clients' actual outcomes in mind.</p>\n          <div className=\"h-1 w-16 rounded-md bg-gradient-to-r from-fuchsia-500 to-emerald-500\" />\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-2xl px-6 py-20\">\n        <div className=\"rounded-md border border-slate-200 bg-white p-8 shadow-sm\">\n          <div className=\"flex gap-0.5 text-fuchsia-500\">{\"★★★★★\"}</div>\n          <p className=\"mt-4 text-lg text-slate-700\">&ldquo;980 sqft, full kitchen, rooftop access. That's exactly what Birchwood Lodge delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Nadia Farouk <span className=\"font-normal text-slate-400\">— Marketing Director</span></p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Location.tsx":"export default function Location() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 pb-20\">\n      <div className=\"grid gap-6 rounded-md border border-slate-100 p-8 md:grid-cols-2\">\n        <div>\n          <h2 className=\"text-xl font-bold text-slate-900\">Visit us</h2>\n          <p className=\"mt-3 text-sm text-slate-600\">123 Market Street, Suite 400</p>\n          <p className=\"mt-4 text-xs font-semibold uppercase tracking-wider text-fuchsia-600\">Hours</p>\n          <p className=\"mt-1 text-sm text-slate-500\">Mon–Fri, 9am–6pm</p>\n        </div>\n        <div className=\"aspect-[4/3] rounded-md bg-gradient-to-br from-fuchsia-100 to-fuchsia-50\" />\n      </div>\n    </section>\n  );\n}\n","components/Catalog.tsx":"import { Zap, Star, Shield, Sparkles, Target, Heart, Award, TrendingUp, Users, Clock, CheckCircle, Compass } from \"lucide-react\";\n\nexport default function Catalog() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-4xl px-6 py-20\">\n        <h2 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">What we offer</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Birchwood Lodge does best.</p>\n        <div className=\"mt-10 divide-y divide-slate-200\">\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-md bg-white text-fuchsia-600 shadow-sm\"><Zap size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Deluxe King</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">480 sqft, city view, walk-in shower.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-md bg-white text-fuchsia-600 shadow-sm\"><Star size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Garden Suite</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">620 sqft, private terrace, soaking tub.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-md bg-white text-fuchsia-600 shadow-sm\"><Shield size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Standard Queen</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">320 sqft, courtyard view.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-md bg-white text-fuchsia-600 shadow-sm\"><Sparkles size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Penthouse</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">980 sqft, full kitchen, rooftop access.</p>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","About","Testimonial","Footer"]},{"name":"Rooms","path":"/rooms","slug":"rooms","sections":["Navbar","PageHeader","Catalog","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Location","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '85e1b9db-d199-434f-a06c-18fefb906819'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"bg-rose-600\">\n      <nav className=\"mx-auto flex max-w-6xl flex-wrap items-center justify-between gap-4 px-6 py-4\">\n        <a href=\"/\" className=\"font-['Georgia',ui-serif,serif] text-lg font-bold tracking-tight text-white\">Harbor House Inn</a>\n        <div className=\"flex items-center gap-6\">\n          <a href=\"/rooms\" className=\"text-sm font-medium text-white/80 hover:text-white transition-colors\">Rooms</a>\n          <a href=\"/contact\" className=\"text-sm font-medium text-white/80 hover:text-white transition-colors\">Contact</a>\n          <a href=\"/contact\" className=\"rounded-md bg-white px-4 py-2 text-sm font-semibold text-rose-700 hover:bg-white/90 transition-colors\">Contact</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-3xl px-6 py-28 text-center md:py-36\">\n        <span className=\"inline-block rounded-full border border-white/15 px-3 py-1 text-xs font-semibold uppercase tracking-tight text-rose-300\">HOSPITALITY</span>\n        <h1 className=\"font-['Georgia',ui-serif,serif] mt-6 text-5xl md:text-6xl font-bold leading-[1.05] tracking-tight\">Wake up two minutes from the water.</h1>\n        <p className=\"mx-auto mt-5 max-w-xl text-lg text-white/60\">A boutique inn built for people who'd rather explore than sightsee.</p>\n        <div className=\"mt-9 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-md bg-rose-500 px-7 py-3 text-sm font-semibold text-slate-950 hover:bg-rose-400 transition-colors\">Get in touch</a>\n          <a href=\"#more\" className=\"rounded-md border border-white/20 px-7 py-3 text-sm font-semibold hover:border-white/40 transition-colors\">Explore</a>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-white\">\n      <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-4 border-t border-slate-100 px-6 py-10 text-center\">\n        <p className=\"font-['Georgia',ui-serif,serif] text-base font-bold tracking-tight text-slate-900\">Harbor House Inn</p>\n        <div className=\"flex flex-wrap items-center justify-center gap-6\">\n          <a href=\"/rooms\" className=\"text-sm text-slate-500 hover:text-slate-900\">Rooms</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a>\n        </div>\n        <p className=\"text-xs text-slate-400\">&copy; {new Date().getFullYear()} Harbor House Inn &middot; Built with <span className=\"text-rose-600\">webma</span></p>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-xl px-6 py-24 text-center\">\n      <h2 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Tell us a bit about what you need — we'll take it from there.</p>\n      <form className=\"mt-10 space-y-3 text-left\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <input name=\"name\" required placeholder=\"Your name\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-rose-500 focus:outline-none\" />\n        <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-rose-500 focus:outline-none\" />\n        <textarea name=\"message\" required rows={3} placeholder=\"How can we help?\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-rose-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"mt-4 w-full rounded-md bg-rose-600 px-6 py-3 text-sm font-semibold text-white hover:bg-rose-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-rose-600 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold tracking-tight\">Rooms</h1>\n        <p className=\"mt-3 max-w-xl text-white/75\">Everything you need to know about how we approach hospitality.</p>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"grid items-center gap-12 md:grid-cols-2\">\n        <div className=\"aspect-[4/3] rounded-md bg-gradient-to-br from-rose-50 to-slate-50 \" />\n        <div>\n          <h2 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">About Harbor House Inn</h2>\n          <p className=\"mt-4 text-slate-600\">Harbor House Inn is built around one idea: hospitality shouldn't be complicated. We keep things clear, direct, and focused on what actually moves the needle.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-2xl px-6 py-20\">\n        <div className=\"rounded-md border border-slate-200 bg-white p-8 shadow-sm\">\n          <div className=\"flex gap-0.5 text-rose-500\">{\"★★★★★\"}</div>\n          <p className=\"mt-4 text-lg text-slate-700\">&ldquo;480 sqft, city view, walk-in shower. That's exactly what Harbor House Inn delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Priya Shah <span className=\"font-normal text-slate-400\">— Client</span></p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Location.tsx":"export default function Location() {\n  return (\n    <section className=\"bg-rose-600 text-white\">\n      <div className=\"mx-auto grid max-w-6xl gap-6 px-6 py-16 md:grid-cols-3\">\n        <h2 className=\"font-['Georgia',ui-serif,serif] text-2xl font-bold\">Visit us</h2>\n        <p className=\"text-sm text-white/85\">123 Market Street, Suite 400</p>\n        <p className=\"text-sm text-white/85\"><span className=\"font-semibold text-white\">Hours</span><br />Mon–Fri, 9am–6pm</p>\n      </div>\n    </section>\n  );\n}\n","components/Catalog.tsx":"import { Zap, Star, Shield, Sparkles, Target, Heart, Award, TrendingUp, Users, Clock, CheckCircle, Compass } from \"lucide-react\";\n\nexport default function Catalog() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-4xl px-6 py-20\">\n        <h2 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">What we offer</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Harbor House Inn does best.</p>\n        <div className=\"mt-10 divide-y divide-slate-200\">\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-md bg-white text-rose-600 shadow-sm\"><Zap size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Deluxe King</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">480 sqft, city view, walk-in shower.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-md bg-white text-rose-600 shadow-sm\"><Star size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Garden Suite</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">620 sqft, private terrace, soaking tub.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-md bg-white text-rose-600 shadow-sm\"><Shield size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Standard Queen</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">320 sqft, courtyard view.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-md bg-white text-rose-600 shadow-sm\"><Sparkles size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Penthouse</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">980 sqft, full kitchen, rooftop access.</p>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","About","Testimonial","Footer"]},{"name":"Rooms","path":"/rooms","slug":"rooms","sections":["Navbar","PageHeader","Catalog","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Location","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '30aef131-9aa3-4967-8d3f-3d1375c743bc'::uuid;
