ction>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-white\">\n      <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-4 border-t border-slate-100 px-6 py-10 text-center\">\n        <p className=\"font-sans text-base font-bold tracking-wide text-slate-900\">The Ellery</p>\n        <div className=\"flex flex-wrap items-center justify-center gap-6\">\n          <a href=\"/rooms\" className=\"text-sm text-slate-500 hover:text-slate-900\">Rooms</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a>\n        </div>\n        <p className=\"text-xs text-slate-400\">&copy; {new Date().getFullYear()} The Ellery &middot; Built with <span className=\"text-indigo-600\">webma</span></p>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-xl px-6 py-24 text-center\">\n      <h2 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Tell us a bit about what you need — we'll take it from there.</p>\n      <form className=\"mt-10 space-y-3 text-left\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <input name=\"name\" required placeholder=\"Your name\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-indigo-500 focus:outline-none\" />\n        <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-indigo-500 focus:outline-none\" />\n        <textarea name=\"message\" required rows={3} placeholder=\"How can we help?\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-indigo-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"mt-4 w-full rounded-full bg-indigo-600 px-6 py-3 text-sm font-semibold text-white hover:bg-indigo-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14 text-center\">\n        <span className=\"text-xs font-semibold uppercase tracking-wide text-indigo-600\">Everything you need to know about how we approach hospitality.</span>\n        <h1 className=\"font-sans mx-auto mt-3 max-w-2xl text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">Rooms</h1>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"grid items-center gap-12 md:grid-cols-2\">\n        <div className=\"aspect-[4/3] rounded-3xl bg-gradient-to-br from-indigo-50 to-amber-50 \" />\n        <div>\n          <h2 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">About The Ellery</h2>\n          <p className=\"mt-4 text-slate-600\">The Ellery pairs real experience in hospitality with a genuine focus on the people we work with — no jargon, no unnecessary steps, just results.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-2xl px-6 py-20\">\n        <div className=\"rounded-3xl border border-slate-200 bg-white p-8 shadow-sm\">\n          <div className=\"flex gap-0.5 text-indigo-500\">{\"★★★★★\"}</div>\n          <p className=\"mt-4 text-lg text-slate-700\">&ldquo;320 sqft, courtyard view. That's exactly what The Ellery delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Sofia Reyes <span className=\"font-normal text-slate-400\">— Operations Lead</span></p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Location.tsx":"export default function Location() {\n  return (\n    <section className=\"bg-indigo-600 text-white\">\n      <div className=\"mx-auto grid max-w-6xl gap-6 px-6 py-16 md:grid-cols-3\">\n        <h2 className=\"font-sans text-2xl font-bold\">Visit us</h2>\n        <p className=\"text-sm text-white/85\">123 Market Street, Suite 400</p>\n        <p className=\"text-sm text-white/85\"><span className=\"font-semibold text-white\">Hours</span><br />Mon–Fri, 9am–6pm</p>\n      </div>\n    </section>\n  );\n}\n","components/Catalog.tsx":"import { Zap, Star, Shield, Sparkles, Target, Heart, Award, TrendingUp, Users, Clock, CheckCircle, Compass } from \"lucide-react\";\n\nexport default function Catalog() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-4xl px-6 py-20\">\n        <h2 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">What we offer</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what The Ellery does best.</p>\n        <div className=\"mt-10 divide-y divide-slate-200\">\n          <div className=\"flex items-start gap-4 py-5\">\n     