UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"bg-white\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-6\">\n        <a href=\"/\" className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-base font-bold uppercase tracking-tighter text-slate-900\">The Marlowe</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n          <a href=\"/rooms\" className=\"border-b-2 border-transparent pb-1 text-sm font-medium text-slate-500 hover:border-slate-500 hover:text-slate-900 transition-colors\">Rooms</a>\n          <a href=\"/contact\" className=\"border-b-2 border-transparent pb-1 text-sm font-medium text-slate-500 hover:border-slate-500 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-slate-600 text-white\">\n      <div className=\"mx-auto max-w-4xl px-6 py-28 text-center md:py-32\">\n        \n        <h1 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] mt-4 text-5xl md:text-7xl font-bold leading-[0.98] tracking-tighter\">A quiet corner of the city, done right.</h1>\n        <p className=\"mx-auto mt-6 max-w-lg text-lg text-white/85\">The Marlowe is 42 rooms, a rooftop bar, and no detail left to chance.</p>\n        <div className=\"mt-9 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-none bg-white px-7 py-3 text-sm font-semibold text-slate-700 hover:bg-white/90 transition-colors\">Get in touch</a>\n          <a href=\"#more\" className=\"rounded-none border border-white/50 px-7 py-3 text-sm font-semibold hover:border-white transition-colors\">Explore</a>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"border-t border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto flex max-w-6xl flex-col gap-8 px-6 py-14 md:flex-row md:items-start md:justify-between\">\n        <div className=\"max-w-sm\">\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-lg font-bold tracking-tighter text-slate-900\">The Marlowe</p>\n          <p className=\"mt-2 text-sm text-slate-500\">The Marlowe is 42 rooms, a rooftop bar, and no detail left to chance.</p>\n        </div>\n        <div className=\"flex gap-8\">\n          <a href=\"/rooms\" className=\"text-sm text-slate-500 hover:text-slate-900\">Rooms</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a>\n        </div>\n      </div>\n      <div className=\"border-t border-slate-200\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center justify-between gap-3 px-6 py-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} The Marlowe. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-slate-600\"><span className=\"h-1.5 w-1.5 rounded-full bg-slate-600\" /> Built with webma</div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto grid max-w-5xl gap-10 px-6 py-20 md:grid-cols-2\">\n        <div>\n          <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Get in touch</h2>\n          <p className=\"mt-3 text-slate-500\">Tell us a bit about what you need — we'll take it from there.</p>\n          <div className=\"mt-8 space-y-4 text-sm text-slate-600\">\n            <p><span className=\"font-semibold text-slate-900\">Address</span><br />123 Market Street, Suite 400</p>\n            <p><span className=\"font-semibold text-slate-900\">Hours</span><br />Mon–Fri, 9am–6pm</p>\n          </div>\n        </div>\n        <form className=\"space-y-4 rounded-none border border-slate-200 bg-white p-6\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n          <input name=\"name\" required placeholder=\"Your name\" className=\"w-full rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-slate-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-slate-500 focus:outline-none\" />\n          <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-slate-500 focus:outline-none\" />\n          <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n          <button type=\"submit\" className=\"w-full rounded-none bg-slate-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-slate-700 transition-colors\">Send message</button>\n        </form>\n      </div>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14 text-center\">\n        <span className=\"text-xs font-semibold uppercase tracking-tighter text-slate-600\">Everything you need to know about how we approach hospitality.</span>\n        <h1 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] mx-auto mt-3 max-w-2xl text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Rooms</h1>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-3xl px-6 py-20 text-center\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">About The Marlowe</h2>\n        <p className=\"mx-auto mt-4 max-w-xl text-slate-600\">The Marlowe is built around one idea: hospitality shouldn't be complicated. We keep things clear, direct, and focused on what actually moves the needle.</p>\n        <div className=\"mx-auto mt-10 grid max-w-lg grid-cols-3 gap-6\">\n          <div><p className=\"text-2xl font-bold text-slate-600\">500+</p><p className=\"mt-1 text-xs uppercase tracking-tighter text-slate-400\">Clients served</p></div>\n          <div><p className=\"text-2xl font-bold text-slate-600\">10 yrs</p><p className=\"mt-1 text-xs uppercase tracking-tighter text-slate-400\">In business</p></div>\n          <div><p className=\"text-2xl font-bold text-slate-600\">4.9/5</p><p className=\"mt-1 text-xs uppercase tracking-tighter text-slate-400\">Avg. rating</p></div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-2xl px-6 py-20\">\n        <div className=\"rounded-none border border-slate-200 bg-white p-8 shadow-sm\">\n          <div className=\"flex gap-0.5 text-slate-500\">{\"★★★★★\"}</div>\n          <p className=\"mt-4 text-lg text-slate-700\">&ldquo;480 sqft, city view, walk-in shower. That's exactly what The Marlowe delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Sofia Reyes <span className=\"font-normal text-slate-400\">— Operations Lead</span></p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Location.tsx":"export default function Location() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 pb-20\">\n      <div className=\"grid gap-6 rounded-none border border-slate-100 p-8 md:grid-cols-2\">\n        <div>\n          <h2 className=\"text-xl font-bold text-slate-900\">Visit us</h2>\n          <p className=\"mt-3 text-sm text-slate-600\">123 Market Street, Suite 400</p>\n          <p className=\"mt-4 text-xs font-semibold uppercase tracking-wider text-slate-600\">Hours</p>\n          <p className=\"mt-1 text-sm text-slate-500\">Mon–Fri, 9am–6pm</p>\n        </div>\n        <div className=\"aspect-[4/3] rounded-none bg-gradient-to-br from-slate-100 to-slate-50\" />\n      </div>\n    </section>\n  );\n}\n","components/Catalog.tsx":"export default function Catalog() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">What we offer</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what The Marlowe does best.</p>\n      </div>\n      <div className=\"mt-10 space-y-14\">\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-none bg-gradient-to-br from-slate-100 to-amber-50 \" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Deluxe King</h3>\n            <p className=\"mt-2 text-slate-500\">480 sqft, city view, walk-in shower.</p>\n          </div>\n        </div>\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-none bg-gradient-to-br from-amber-100 to-slate-50 md:order-2\" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Garden Suite</h3>\n            <p className=\"mt-2 text-slate-500\">620 sqft, private terrace, soaking tub.</p>\n          </div>\n        </div>\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-none bg-gradient-to-br from-slate-100 to-amber-50 \" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Standard Queen</h3>\n            <p className=\"mt-2 text-slate-500\">320 sqft, courtyard view.</p>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","About","Testimonial","Footer"]},{"name":"Rooms","path":"/rooms","slug":"rooms","sections":["Navbar","PageHeader","Catalog","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Location","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = 'e057f571-e6bf-429e-8f67-dc211afd8140'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-4 z-40 mx-auto max-w-4xl px-4\">\n      <nav className=\"flex items-center justify-between gap-4 rounded-full border border-slate-200 bg-white/95 px-6 py-3 shadow-sm backdrop-blur\">\n        <a href=\"/\" className=\"font-sans text-sm font-bold tracking-wide text-slate-900\">Beacon Launch</a>\n        <div className=\"hidden items-center gap-6 md:flex\">\n          <a href=\"/pricing\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Pricing</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-full bg-teal-600 px-4 py-1.5 text-xs font-semibold text-white hover:bg-teal-700 transition-colors\">Get started</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-[0.9fr_1.1fr] md:py-28\">\n        <div className=\"aspect-square rounded-3xl bg-gradient-to-tr from-rose-100 to-teal-100 ring-1 ring-teal-100 md:order-1\" />\n        <div className=\"md:order-2\">\n          <span className=\"text-xs font-semibold uppercase tracking-wide text-teal-600\">PRODUCT LAUNCH</span>\n          <h1 className=\"font-sans mt-3 text-4xl md:text-5xl font-bold leading-[1.02] tracking-wide text-slate-900\">Ship your launch page in an afternoon.</h1>\n          <p className=\"mt-5 max-w-md text-lg text-slate-600\">Built for the announcement, not the whole website.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-full bg-teal-600 px-6 py-3 text-sm font-semibold text-white hover:bg-teal-700 transition-colors\">Book a call</a>\n            <a href=\"#more\" className=\"text-sm font-semibold text-slate-700 underline decoration-slate-300 underline-offset-4 hover:decoration-slate-600\">Learn more</a>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <div className=\"grid gap-10 md:grid-cols-[1.2fr_1fr]\">\n          <div>\n            <p className=\"font-sans text-xl font-bold tracking-wide\">Beacon Launch</p>\n            <p className=\"mt-2 max-w-sm text-sm text-white/50\">Built for the announcement, not the whole website.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wide text-white/40\">Stay in the loop</p>\n            <form className=\"mt-3 flex gap-2\" onSubmit={(e) => e.preventDefault()}>\n              <input type=\"email\" required placeholder=\"you@email.com\" className=\"w-full rounded-3xl border border-white/15 bg-white/5 px-4 py-2.5 text-sm text-white placeholder:text-white/30 focus:border-teal-400 focus:outline-none\" />\n              <button type=\"submit\" className=\"rounded-full bg-teal-500 px-5 py-2.5 text-sm font-semibold text-slate-950 hover:bg-teal-400 transition-colors\">Join</button>\n            </form>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-3 border-t border-white/10 pt-6 text-xs text-white/40 sm:flex-row\">\n          <div className=\"flex gap-6\">\n            <a href=\"/pricing\" className=\"hover:text-white\">Pricing</a>\n            <a href=\"/contact\" className=\"hover:text-white\">Contact</a>\n          </div>\n          <p>&copy; {new Date().getFullYear()} Beacon Launch</p>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-xl px-6 py-24 text-center\">\n      <h2 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Questions, quotes, or just saying hello — we'd love to hear from you.</p>\n      <form className=\"mt-10 space-y-3 text-left\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <input name=\"name\" required placeholder=\"Your name\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-teal-500 focus:outline-none\" />\n        <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-teal-500 focus:outline-none\" />\n        <textarea name=\"message\" required rows={3} placeholder=\"How can we help?\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-teal-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"mt-4 w-full rounded-full bg-teal-600 px-6 py-3 text-sm font-semibold text-white hover:bg-teal-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-2xl px-6 py-20\">\n        <div className=\"rounded-3xl border border-slate-200 bg-white p-8 shadow-sm\">\n          <div className=\"flex gap-0.5 text-teal-500\">{\"★★★★★\"}</div>\n          <p className=\"mt-4 text-lg text-slate-700\">&ldquo;Real numbers, real logos, real quotes. That's exactly what Beacon Launch delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Alina Novak <span className=\"font-normal text-slate-400\">— Head of Growth</span></p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Pricing.tsx":"import { Check } from \"lucide-react\";\n\nexport default function Pricing() {\n  return (\n    <section id=\"pricing\" className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-3xl px-6 py-20\">\n        <h2 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">Simple, transparent pricing</h2>\n        <p className=\"mt-3 text-slate-500\">Choose the plan that fits — upgrade or cancel any time.</p>\n        <div className=\"mt-10 divide-y divide-slate-200 overflow-hidden rounded-3xl border border-slate-200 bg-white\">\n          <div className=\"flex flex-col gap-4 p-6 sm:flex-row sm:items-center sm:justify-between\">\n            <div>\n              <p className=\"font-semibold text-slate-900\">Starter </p>\n              <p className=\"mt-1 text-sm text-slate-500\">Core features</p>\n            </div>\n            <div className=\"flex items-center gap-4\">\n              <p className=\"text-2xl font-bold text-slate-900\">$29<span className=\"text-sm font-normal text-slate-400\">/mo</span></p>\n              <a href=\"/contact\" className=\"rounded-full bg-teal-600 px-5 py-2 text-sm font-semibold text-white hover:bg-teal-700 transition-colors\">Choose</a>\n            </div>\n          </div>\n          <div className=\"flex flex-col gap-4 p-6 sm:flex-row sm:items-center sm:justify-between\">\n            <div>\n              <p className=\"font-semibold text-slate-900\">Growth <span className=\"ml-2 rounded-full bg-teal-100 px-2 py-0.5 text-[10px] font-semibold uppercase text-teal-700\">Popular</span></p>\n              <p className=\"mt-1 text-sm text-slate-500\">Everything in Starter</p>\n            </div>\n            <div className=\"flex items-center gap-4\">\n              <p className=\"text-2xl font-bold text-slate-900\">$79<span className=\"text-sm font-normal text-slate-400\">/mo</span></p>\n              <a href=\"/contact\" className=\"rounded-full bg-teal-600 px-5 py-2 text-sm font-semibold text-white hover:bg-teal-700 transition-colors\">Choose</a>\n            </div>\n          </div>\n          <div className=\"flex flex-col gap-4 p-6 sm:flex-row sm:items-center sm:justify-between\">\n            <div>\n              <p className=\"font-semibold text-slate-900\">Scale </p>\n              <p className=\"mt-1 text-sm text-slate-500\">Everything in Growth</p>\n            </div>\n            <div className=\"flex items-center gap-4\">\n              <p className=\"text-2xl font-bold text-slate-900\">$199<span className=\"text-sm font-normal text-slate-400\">/mo</span></p>\n              <a href=\"/contact\" className=\"rounded-full bg-teal-600 px-5 py-2 text-sm font-semibold text-white hover:bg-teal-700 transition-colors\">Choose</a>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Stats.tsx":"export default function Stats() {\n  return (\n    <section className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto grid max-w-6xl grid-cols-2 gap-8 px-6 py-16 text-center md:grid-cols-4\">\n        <div><p className=\"text-3xl font-bold text-teal-300 md:text-4xl\">500+</p><p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Clients served</p></div>\n        <div><p className=\"text-3xl font-bold text-teal-300 md:text-4xl\">10 yrs</p><p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">In business</p></div>\n        <div><p className=\"text-3xl font-bold text-teal-300 md:text-4xl\">4.9/5</p><p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Avg. rating</p></div>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"export default function Features() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-sans text-2xl md:text-3xl font-bold tracking-wide text-slate-900\">What Beacon Launch offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Beacon Launch does best.</p>\n      </div>\n      <div className=\"mt-10 grid gap-8 sm:grid-cols-2 lg:grid-cols-3\">\n        <div>\n          <p className=\"font-sans text-4xl font-bold text-teal-200\">01</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">One clear promise</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">A single, sharp value proposition above the fold.</p>\n        </div>\n        <div>\n          <p className=\"font-sans text-4xl font-bold text-teal-200\">02</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Social proof</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Real numbers, real logos, real quotes.</p>\n        </div>\n        <div>\n          <p className=\"font-sans text-4xl font-bold text-teal-200\">03</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Simple pricing</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">No confusing tiers, no hidden fees.</p>\n        </div>\n        <div>\n          <p className=\"font-sans text-4xl font-bold text-teal-200\">04</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Fast load times</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Every second of delay costs conversions.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Stats","Features","Testimonial","Footer"]},{"name":"Pricing","path":"/pricing","slug":"pricing","sections":["Navbar","Pricing","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '0994d264-db2c-4d65-9ac3-163e1c7563ff'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-0 z-40 border-b border-slate-100 bg-white/80 backdrop-blur\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-4\">\n        <a href=\"/\" className=\"font-['Georgia',ui-serif,serif] text-lg font-bold tracking-tight text-slate-900\">Orbit</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n          <a href=\"/pricing\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Pricing</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-md bg-rose-600 px-4 py-2 text-sm font-semibold text-white hover:bg-rose-700 transition-colors\">Get in touch</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-2 md:py-32\">\n        <div>\n          <span className=\"inline-block rounded-md bg-rose-100 px-3 py-1 text-xs font-semibold uppercase tracking-tight text-rose-700\">PRODUCT LAUNCH</span>\n          <h1 className=\"font-['Georgia',ui-serif,serif] mt-5 text-5xl md:text-6xl font-bold leading-[1.05] tracking-tight text-slate-900\">The waitlist that actually converts.</h1>\n          <p className=\"mt-5 max-w-lg text-lg text-slate-600\">Join 4,000+ people getting early access to Orbit.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-md bg-rose-600 px-6 py-3 text-sm font-semibold text-white hover:bg-rose-700 transition-colors\">Get started</a>\n            <a href=\"#more\" className=\"rounded-md border border-slate-200 px-6 py-3 text-sm font-semibold text-slate-700 hover:border-slate-400 transition-colors\">See how it works</a>\n          </div>\n        </div>\n        <div className=\"aspect-[4/3] rounded-md bg-gradient-to-br from-rose-100 via-rose-50 to-slate-50 ring-1 ring-rose-100\" />\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <div className=\"grid gap-10 md:grid-cols-[1.2fr_1fr]\">\n          <div>\n            <p className=\"font-['Georgia',ui-serif,serif] text-xl font-bold tracking-tight\">Orbit</p>\n            <p className=\"mt-2 max-w-sm text-sm text-white/50\">Join 4,000+ people getting early access to Orbit.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-tight text-white/40\">Stay in the loop</p>\n            <form className=\"mt-3 flex gap-2\" onSubmit={(e) => e.preventDefault()}>\n              <input type=\"email\" required placeholder=\"you@email.com\" className=\"w-full rounded-md border border-white/15 bg-white/5 px-4 py-2.5 text-sm text-white placeholder:text-white/30 focus:border-rose-400 focus:outline-none\" />\n              <button type=\"submit\" className=\"rounded-md bg-rose-500 px-5 py-2.5 text-sm font-semibold text-slate-950 hover:bg-rose-400 transition-colors\">Join</button>\n            </form>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-3 border-t border-white/10 pt-6 text-xs text-white/40 sm:flex-row\">\n          <div className=\"flex gap-6\">\n            <a href=\"/pricing\" className=\"hover:text-white\">Pricing</a>\n            <a href=\"/contact\" className=\"hover:text-white\">Contact</a>\n          </div>\n          <p>&copy; {new Date().getFullYear()} Orbit</p>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto grid max-w-5xl gap-10 px-6 py-20 md:grid-cols-2\">\n        <div>\n          <h2 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Get in touch</h2>\n          <p className=\"mt-3 text-slate-500\">Questions, quotes, or just saying hello — we'd love to hear from you.</p>\n          <div className=\"mt-8 space-y-4 text-sm text-slate-600\">\n            <p><span className=\"font-semibold text-slate-900\">Address</span><br />123 Market Street, Suite 400</p>\n            <p><span className=\"font-semibold text-slate-900\">Hours</span><br />Mon–Fri, 9am–6pm</p>\n          </div>\n        </div>\n        <form className=\"space-y-4 rounded-md border border-slate-200 bg-white p-6\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n          <input name=\"name\" required placeholder=\"Your name\" className=\"w-full rounded-md border border-slate-200 px-4 py-2.5 text-sm focus:border-rose-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full rounded-md border border-slate-200 px-4 py-2.5 text-sm focus:border-rose-500 focus:outline-none\" />\n          <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-md border border-slate-200 px-4 py-2.5 text-sm focus:border-rose-500 focus:outline-none\" />\n          <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n          <button type=\"submit\" className=\"w-full rounded-md bg-rose-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-rose-700 transition-colors\">Send message</button>\n        </form>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid items-center gap-10 md:grid-cols-[0.8fr_1.2fr]\">\n        <div className=\"aspect-square rounded-md bg-gradient-to-br from-rose-100 to-slate-100\" />\n        <div>\n          <p className=\"font-['Georgia',ui-serif,serif] text-2xl font-medium leading-snug text-slate-900\">&ldquo;No confusing tiers, no hidden fees. That's exactly what Orbit delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Priya Shah</p>\n          <p className=\"text-xs text-slate-500\">Client</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Pricing.tsx":"import { Check } from \"lucide-react\";\n\nexport default function Pricing() {\n  return (\n    <section id=\"pricing\" className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Georgia',ui-serif,serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Simple, transparent pricing</h2>\n        <p className=\"mt-3 text-slate-500\">Choose the plan that fits — upgrade or cancel any time.</p>\n      </div>\n      <div className=\"mt-10 grid gap-4 md:grid-cols-3\">\n        <div className=\"rounded-md border border-slate-100 p-6\">\n          \n          <p className=\"mt-3 font-semibold text-slate-900\">Starter</p>\n          <p className=\"mt-2 text-3xl font-bold text-slate-900\">$29<span className=\"t