     const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-fuchsia-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-fuchsia-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-none border border-slate-200 px-4 py-2.5 text-sm focus:border-fuchsia-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-none bg-fuchsia-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-fuchsia-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-3xl px-6 py-20 text-center\">\n      <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-medium leading-snug text-slate-900\">&ldquo;No confusing tiers, no hidden fees. That's exactly what Pulseline delivered.&rdquo;</p>\n      <div className=\"mt-6 flex items-center justify-center gap-3\">\n        <div className=\"h-10 w-10 rounded-none bg-fuchsia-100\" />\n        <div className=\"text-left\">\n          <p className=\"text-sm font-semibold text-slate-900\">Priya Shah</p>\n          <p className=\"text-xs text-slate-500\">General Manager</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Pricing.tsx":"import { Check } from \"lucide-react\";\n\nexport default function Pricing() {\n  return (\n    <section id=\"pricing\" className=\"mx-auto max-w-4xl px-6 py-20 text-center\">\n      <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Simple, transparent pricing</h2>\n      <p className=\"mx-auto mt-3 max-w-lg text-slate-500\">Choose the plan that fits — upgrade or cancel any time.</p>\n      <div className=\"mt-10 grid gap-6 sm:grid-cols-2\">\n        <div className=\"rounded-none border border-slate-200 p-8\">\n          <p className=\"font-semibold text-slate-900\">Starter</p>\n          <p className=\"mt-3 text-4xl font-bold\">$29<span className=\"text-sm font-normal text-slate-400\">/mo</span></p>\n          <ul className=\"mt-6 space-y-2 text-left text-sm text-slate-600\">\n            <li className=\"flex items-center gap-2\"><Check size={14} /> Core features</li>\n            <li className=\"flex items-center gap-2\"><Check size={14} /> Email support</li>\n          </ul>\n          <a href=\"/contact\" className=\"mt-6 block rounded-none py-2.5 text-center text-sm font-semibold transition-colors border border-slate-200 text-slate-700 hover:border-slate-400\">Choose Starter</a>\n        </div>\n        <div className=\"rounded-none bg-fuchsia-600 text-white p-8\">\n          <p className=\"font-semibold text-white\">Growth</p>\n          <p className=\"mt-3 text-4xl font-bold\">$79<span className=\"text-sm font-normal text-white/70\">/mo</span></p>\n          <ul className=\"mt-6 space-y-2 text-left text-sm text-white/85\">\n            <li className=\"flex items-center gap-2\"><Check size={14} /> Everything in Starter</li>\n            <li className=\"flex items-center gap-2\"><Check size={14} /> Priority support</li>\n            <li className=\"flex items-center gap-2\"><Check size={14} /> Advanced reporting</li>\n          </ul>\n          <a href=\"/contact\" className=\"mt-6 block rounded-none py-2.5 text-center text-sm font-semibold transition-colors bg-white text-fuchsia-700 hover:bg-white/90\">Choose Growth</a>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Stats.tsx":"export default function Stats() {\n  return (\n    <section className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto grid max-w-6xl grid-cols-2 gap-8 px-6 py-16 text-center md:grid-cols-4\">\n        <div><p className=\"text-3xl font-bold text-fuchsia-300 md:text-4xl\">1,200+</p><p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Projects delivered</p></div>\n        <div><p className=\"text-3xl font-bold text-fuchsia-300 md:text-4xl\">15</p><p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Industries served</p></div>\n        <div><p className=\"text-3xl font-bold text-fuchsia-300 md:text-4xl\">99%</p><p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">On-time delivery</p></div>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"import { Zap, Star, Shield, Sparkles, Target, Heart, Award, TrendingUp, Users, Clock, CheckCircle, Compass } from \"lucide-react\";\n\nexport default function Features() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">What Pulseline offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Pulseline does best.</p>\n      </div>\n      <div className=\"mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-3\">\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-fuchsia-100 text-fuchsia-600\">\n            <Zap size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">One clear promise</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">A single, sharp value proposition above the fold.</p>\n        </div>\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-fuchsia-100 text-fuchsia-600\">\n            <Star size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Social proof</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Real numbers, real logos, real quotes.</p>\n        </div>\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-fuchsia-100 text-fuchsia-600\">\n            <Shield size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Simple pricing</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">No confusing tiers, no hidden fees.</p>\n        </div>\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-fuchsia-100 text-fuchsia-600\">\n            <Sparkles size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Fast load times</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Every second of delay costs conversions.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Stats","Features","Testimonial","Footer"]},{"name":"Pricing","path":"/pricing","slug":"pricing","sections":["Navbar","Pricing","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '953819b7-dce0-4899-a25e-40c6c0e53d3c'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-0 z-40 border-b border-slate-100 bg-white/80 backdrop-blur\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-4\">\n        <a href=\"/\" className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-lg font-bold tracking-tighter text-slate-900\">Harlow Legal</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n          <a href=\"/services\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Services</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-none bg-emerald-600 px-4 py-2 text-sm font-semibold text-white hover:bg-emerald-700 transition-colors\">Get in touch</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-emerald-600 text-white\">\n      <div className=\"mx-auto max-w-4xl px-6 py-28 text-center md:py-32\">\n        \n        <h1 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] mt-4 text-5xl md:text-7xl font-bold leading-[0.98] tracking-tighter\">Plain-language advice, not legal jargon.</h1>\n        <p className=\"mx-auto mt-6 max-w-lg text-lg text-white/85\">Harlow explains every option in terms you can actually act on.</p>\n        <div className=\"mt-9 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-none bg-white px-7 py-3 text-sm font-semibold text-emerald-700 hover:bg-white/90 transition-colors\">Talk to us</a>\n          <a href=\"#more\" className=\"rounded-none border border-white/50 px-7 py-3 text-sm font-semibold hover:border-white transition-colors\">See examples</a>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"border-t border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto flex max-w-6xl flex-col gap-8 px-6 py-14 md:flex-row md:items-start md:justify-between\">\n        <div className=\"max-w-sm\">\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-lg font-bold tracking-tighter text-slate-900\">Harlow Legal</p>\n          <p className=\"mt-2 text-sm text-slate-500\">Harlow explains every option in terms you can actually act on.</p>\n        </div>\n        <div className=\"flex gap-8\">\n          <a href=\"/services\" className=\"text-sm text-slate-500 hover:text-slate-900\">Services</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a>\n        </div>\n      </div>\n      <div className=\"border-t border-slate-200\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center justify-between gap-3 px-6 py-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Harlow Legal. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-emerald-600\"><span className=\"h-1.5 w-1.5 rounded-full bg-emerald-600\" /> Built with webma</div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-xl px-6 py-24 text-center\">\n      <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Tell us a bit about what you need — we'll take it from there.</p>\n      <form className=\"mt-10 space-y-3 text-left\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <input name=\"name\" required placeholder=\"Your name\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-emerald-500 focus:outline-none\" />\n        <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-emerald-500 focus:outline-none\" />\n        <textarea name=\"message\" required rows={3} placeholder=\"How can we help?\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-emerald-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"mt-4 w-full rounded-none bg-emerald-600 px-6 py-3 text-sm font-semibold text-white hover:bg-emerald-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"border-b border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Services</h1>\n        <p className=\"mt-3 max-w-xl text-slate-500\">A closer look at what we do and how we do it.</p>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid gap-10 md:grid-cols-[1fr_1fr]\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold leading-tight tracking-tighter text-slate-900\">About Harlow Legal</h2>\n        <div className=\"space-y-4\">\n          <p className=\"text-slate-600\">Harlow Legal is built around one idea: legal services shouldn't be complicated. We keep things clear, direct, and focused on what actually moves the needle.</p>\n          <div className=\"h-1 w-16 rounded-none bg-gradient-to-r from-emerald-500 to-orange-500\" />\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid items-center gap-10 md:grid-cols-[0.8fr_1.2fr]\">\n        <div className=\"aspect-square rounded-none bg-gradient-to-br from-emerald-100 to-orange-100\" />\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl font-medium leading-snug text-slate-900\">&ldquo;Wills, trusts, and succession planning. That's exactly what Harlow Legal delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Sofia Reyes</p>\n          <p className=\"text-xs text-slate-500\">Founder</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"import { Zap, Star, Shield, Sparkles, Target, Heart, Award, TrendingUp, Users, Clock, CheckCircle, Compass } from \"lucide-react\";\n\nexport default function Features() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">What Harlow Legal offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Harlow Legal does best.</p>\n      </div>\n      <div className=\"mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-3\">\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-emerald-100 text-emerald-600\">\n            <Zap size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Corporate law</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Formation, contracts, and governance.</p>\n        </div>\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-emerald-100 text-emerald-600\">\n            <Star size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Litigation</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Civil disputes handled with a trial-ready posture.</p>\n        </div>\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-emerald-100 text-emerald-600\">\n            <Shield size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Estate planning</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Wills, trusts, and succession planning.</p>\n        </div>\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-emerald-100 text-emerald-600\">\n            <Sparkles size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Contract review</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Clear terms before you sign anything.</p>\n        </div>\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-emerald-100 text-emerald-600\">\n            <Target size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Employment law</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Policy review and workplace dispute resolution.</p>\n        </div>\n        <div className=\"rounded-none border border-slate-100 p-6\">\n          <div className=\"flex h-10 w-10 items-center justify-center rounded-none bg-emerald-100 text-emerald-600\">\n            <Heart size={18} />\n          </div>\n          <h3 className=\"mt-4 font-semibold text-slate-900\">Real estate law</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Closings, leases, and title review.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Features","About","Testimonial","Footer"]},{"name":"Services","path":"/services","slug":"services","sections":["Navbar","PageHeader","Features","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '0cae3f66-4c7a-45b6-94dd-2c53d22f8af2'::uuid;
