n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-white\">\n      <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-4 border-t border-slate-100 px-6 py-10 text-center\">\n        <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-base font-bold tracking-tighter text-slate-900\">Prescott & Marsh</p>\n        <div className=\"flex flex-wrap items-center justify-center gap-6\">\n          <a href=\"/services\" className=\"text-sm text-slate-500 hover:text-slate-900\">Services</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a>\n        </div>\n        <p className=\"text-xs text-slate-400\">&copy; {new Date().getFullYear()} Prescott & Marsh &middot; Built with <span className=\"text-sky-600\">webma</span></p>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-xl px-6 py-24 text-center\">\n      <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Tell us a bit about what you need — we'll take it from there.</p>\n      <form className=\"mt-10 space-y-3 text-left\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <input name=\"name\" required placeholder=\"Your name\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-sky-500 focus:outline-none\" />\n        <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-sky-500 focus:outline-none\" />\n        <textarea name=\"message\" required rows={3} placeholder=\"How can we help?\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-sky-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"mt-4 w-full rounded-none bg-sky-600 px-6 py-3 text-sm font-semibold text-white hover:bg-sky-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-sky-600 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter\">Services</h1>\n        <p className=\"mt-3 max-w-xl text-white/75\">A closer look at what we do and how we do it.</p>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"grid items-center gap-12 md:grid-cols-2\">\n        <div className=\"aspect-[4/3] rounded-none bg-gradient-to-br from-sky-50 to-fuchsia-50 \" />\n        <div>\n          <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">About Prescott & Marsh</h2>\n          <p className=\"mt-4 text-slate-600\">We started Prescott & Marsh because the existing options in legal services were either too slow or too generic. Every decision here is made with our clients' actual outcomes in mind.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid items-center gap-10 md:grid-cols-[0.8fr_1.2fr]\">\n        <div className=\"aspect-square rounded-none bg-gradient-to-br from-sky-100 to-fuchsia-100\" />\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl font-medium leading-snug text-slate-900\">&ldquo;Civil disputes handled with a trial-ready posture. That's exactly what Prescott & Marsh delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Nadia Farouk</p>\n          <p className=\"text-xs text-slate-500\">Head of Growth</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"export default function Features() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">What Prescott & Marsh offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Prescott & Marsh does best.</p>\n      </div>\n      <div className=\"mt-10 grid gap-8 sm:grid-cols-2 lg:grid-cols-3\">\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-4xl font-bold text-sky-200\">01</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Corporate law</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Formation, contracts, and governance.</p>\n        </div>\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-4xl font-bold text-sky-200\">02</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Litigation</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Civil disputes handled with a trial-ready posture.</p>\n        </div>\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-4xl font-bold text-sky-200\">03</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Estate planning</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Wills, trusts, and succession planning.</p>\n        </div>\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-4xl font-bold text-sky-200\">04</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Contract review</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Clear terms before you sign anything.</p>\n        </div>\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-4xl font-bold text-sky-200\">05</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Employment law</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Policy review and workplace dispute resolution.</p>\n        </div>\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-4xl font-bold text-sky-200\">06</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Real estate law</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Closings, leases, and title review.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Features","About","Testimonial","Footer"]},{"name":"Services","path":"/services","slug":"services","sections":["Navbar","PageHeader","Features","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '4bfcffde-c6eb-49de-998f-5c22311f4bc3'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"bg-white\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-6\">\n        <a href=\"/\" className=\"font-['Palatino',ui-serif,serif] text-base font-bold uppercase tracking-normal text-slate-900\">Sterling Law Group</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n          <a href=\"/services\" className=\"border-b-2 border-transparent pb-1 text-sm font-medium text-slate-500 hover:border-orange-500 hover:text-slate-900 transition-colors\">Services</a>\n          <a href=\"/contact\" className=\"border-b-2 border-transparent pb-1 text-sm font-medium text-slate-500 hover:border-orange-500 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"relative overflow-hidden bg-gradient-to-br from-orange-600 via-orange-500 to-indigo-500 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-24 md:py-32\">\n        <div className=\"max-w-2xl\">\n          \n          <h1 className=\"font-['Palatino',ui-serif,serif] mt-5 text-4xl md:text-5xl font-bold leading-[1.05] tracking-normal\">Counsel that picks up the phone.</h1>\n          <p className=\"mt-5 max-w-lg text-lg text-white/80\">Sterling keeps caseloads small enough that clients actually reach their attorney.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-lg bg-white px-6 py-3 text-sm font-semibold text-orange-700 hover:bg-white/90 transition-colors\">Get started</a>\n            <a href=\"#more\" className=\"rounded-lg border border-white/40 px-6 py-3 text-sm font-semibold text-white hover:border-white transition-colors\">See how it works</a>\n          </div>\n        </div>\n        <div className=\"mt-16 hidden max-w-sm rounded-lg border border-white/20 bg-white/10 p-6 backdrop-blur md:block\">\n          <p className=\"text-sm text-white/70\">Trusted by teams who need it to just work.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <div className=\"grid gap-10 md:grid-cols-[1.2fr_1fr]\">\n          <div>\n            <p className=\"font-['Palatino',ui-serif,serif] text-xl font-bold tracking-normal\">Sterling Law Group</p>\n            <p className=\"mt-2 max-w-sm text-sm text-white/50\">Sterling keeps caseloads small enough that clients actually reach their attorney.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-normal text-white/40\">Stay in the loop</p>\n            <form className=\"mt-3 flex gap-2\" onSubmit={(e) => e.preventDefault()}>\n              <input type=\"email\" required placeholder=\"you@email.com\" className=\"w-full rounded-lg border border-white/15 bg-white/5 px-4 py-2.5 text-sm text-white placeholder:text-white/30 focus:border-orange-400 focus:outline-none\" />\n              <button type=\"submit\" className=\"rounded-lg bg-orange-500 px-5 py-2.5 text-sm font-semibold text-slate-950 hover:bg-orange-400 transition-colors\">Join</button>\n            </form>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-3 border-t border-white/10 pt-6 text-xs text-white/40 sm:flex-row\">\n          <div className=\"flex gap-6\">\n            <a href=\"/services\" className=\"hover:text-white\">Services</a>\n            <a href=\"/contact\" className=\"hover:text-white\">Contact</a>\n          </div>\n          <p>&copy; {new Date().getFullYear()} Sterling Law Group</p>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto grid max-w-5xl gap-10 px-6 py-20 md:grid-cols-2\">\n        <div>\n          <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">Get in touch</h2>\n          <p className=\"mt-3 text-slate-500\">Tell us a bit about what you need — we'll take it from there.</p>\n          <div className=\"mt-8 space-y-4 text-sm text-slate-600\">\n            <p><span className=\"font-semibold text-slate-900\">Address</span><br />123 Market Street, Suite 400</p>\n            <p><span className=\"font-semibold text-slate-900\">Hours</span><br />Mon–Fri, 9am–6pm</p>\n          </div>\n        </div>\n        <form className=\"space-y-4 rounded-lg border border-slate-200 bg-white p-6\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n          <input name=\"name\" required placeholder=\"Your name\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-orange-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-orange-500 focus:outline-none\" />\n          <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-orange-500 focus:outline-none\" />\n          <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n          <button type=\"submit\" className=\"w-full rounded-lg bg-orange-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-orange-700 transition-colors\">Send message</button>\n        </form>\n      </div>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14 text-center\">\n        <span className=\"text-xs font-semibold uppercase tracking-normal text-orange-600\">A closer look at what we do and how we do it.</span>\n        <h1 className=\"font-['Palatino',ui-serif,serif] mx-auto mt-3 max-w-2xl text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">Services</h1>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"grid gap-10 md:grid-cols-[1fr_1fr]\">\n        <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold leading-tight tracking-normal text-slate-900\">About Sterling Law Group</h2>\n        <div className=\"space-y-4\">\n          <p className=\"text-slate-600\">We started Sterling Law Group because the existing options in legal services were either too slow or too generic. Every decision here is made with our clients' actual outcomes in mind.</p>\n          <div className=\"h-1 w-16 rounded-lg bg-gradient-to-r from-orange-500 to-indigo-500\" />\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-3xl px-6 py-20 text-center\">\n      <p className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-medium leading-snug text-slate-900\">&ldquo;Wills, trusts, and succession planning. That's exactly what Sterling Law Group delivered.&rdquo;</p>\n      <div className=\"mt-6 flex items-center justify-center gap-3\">\n        <div className=\"h-10 w-10 rounded-lg bg-orange-100\" />\n        <div className=\"text-left\">\n          <p className=\"text-sm font-semibold text-slate-900\">Priya Shah</p>\n          <p className=\"text-xs text-slate-500\">Operations Lead</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"export default function Features() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">What Sterling Law Group offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Sterling Law Group does best.</p>\n      </div>\n      <div className=\"mt-10 space-y-14\">\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-lg bg-gradient-to-br from-orange-100 to-indigo-50 \" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Corporate law</h3>\n            <p className=\"mt-2 text-slate-500\">Formation, contracts, and governance.</p>\n          </div>\n        </div>\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-lg bg-gradient-to-br from-indigo-100 to-orange-50 md:order-2\" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Litigation</h3>\n            <p className=\"mt-2 text-slate-500\">Civil disputes handled with a trial-ready posture.</p>\n          </div>\n        </div>\n        <div className=\"grid items-center gap-8 md:grid-cols-2\">\n          <div className=\"aspect-[4/3] rounded-lg bg-gradient-to-br from-orange-100 to-indigo-50 \" />\n          <div>\n            <h3 className=\"text-xl font-semibold text-slate-900\">Estate planning</h3>\n            <p className=\"mt-2 text-slate-500\">Wills, trusts, and succession planning.</p>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Features","About","Testimonial","Footer"]},{"name":"Services","path":"/services","slug":"services","sections":["Navbar","PageHeader","Features","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = 'f034027b-022a-4607-ab0d-a3d755e08f61'::uuid;
