    <div className=\"mt-8 space-y-4 text-sm text-slate-600\">\n            <p><span className=\"font-semibold text-slate-900\">Address</span><br />123 Market Street, Suite 400</p>\n            <p><span className=\"font-semibold text-slate-900\">Hours</span><br />Mon–Fri, 9am–6pm</p>\n          </div>\n        </div>\n        <form className=\"space-y-4 rounded-2xl border border-slate-200 bg-white p-6\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n          <input name=\"name\" required placeholder=\"Your name\" className=\"w-full rounded-2xl border border-slate-200 px-4 py-2.5 text-sm focus:border-teal-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full rounded-2xl border border-slate-200 px-4 py-2.5 text-sm focus:border-teal-500 focus:outline-none\" />\n          <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-2xl border border-slate-200 px-4 py-2.5 text-sm focus:border-teal-500 focus:outline-none\" />\n          <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n          <button type=\"submit\" className=\"w-full rounded-full bg-teal-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-teal-700 transition-colors\">Send message</button>\n        </form>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-2xl px-6 py-20\">\n        <div className=\"rounded-2xl border border-slate-200 bg-white p-8 shadow-sm\">\n          <div className=\"flex gap-0.5 text-teal-500\">{\"★★★★★\"}</div>\n          <p className=\"mt-4 text-lg text-slate-700\">&ldquo;Give every team its own space without losing shared context. That's exactly what Circuitry delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Theo Kwan <span className=\"font-normal text-slate-400\">— Founder</span></p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Pricing.tsx":"import { Check } from \"lucide-react\";\n\nexport default function Pricing() {\n  return (\n    <section id=\"pricing\" className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-3xl px-6 py-20\">\n        <h2 className=\"font-['Verdana',ui-sans-serif,sans-serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Simple, transparent pricing</h2>\n        <p className=\"mt-3 text-slate-500\">Choose the plan that fits — upgrade or cancel any time.</p>\n        <div className=\"mt-10 divide-y divide-slate-200 overflow-hidden rounded-2xl border border-slate-200 bg-white\">\n          <div className=\"flex flex-col gap-4 p-6 sm:flex-row sm:items-center sm:justify-between\">\n            <div>\n              <p className=\"font-semibold text-slate-900\">Starter </p>\n              <p className=\"mt-1 text-sm text-slate-500\">Core features</p>\n            </div>\n            <div className=\"flex items-center gap-4\">\n              <p className=\"text-2xl font-bold text-slate-900\">$29<span className=\"text-sm font-normal text-slate-400\">/mo</span></p>\n              <a href=\"/contact\" className=\"rounded-full bg-teal-600 px-5 py-2 text-sm font-semibold text-white hover:bg-teal-