UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-4 z-40 mx-auto max-w-4xl px-4\">\n      <nav className=\"flex items-center justify-between gap-4 rounded-full border border-slate-200 bg-white/95 px-6 py-3 shadow-sm backdrop-blur\">\n        <a href=\"/\" className=\"font-['Verdana',ui-sans-serif,sans-serif] text-sm font-bold tracking-tight text-slate-900\">Kindling</a>\n        <div className=\"hidden items-center gap-6 md:flex\">\n          <a href=\"/pricing\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Pricing</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-full bg-rose-600 px-4 py-1.5 text-xs font-semibold text-white hover:bg-rose-700 transition-colors\">Get started</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-[0.9fr_1.1fr] md:py-28\">\n        <div className=\"aspect-square rounded-2xl bg-gradient-to-tr from-slate-100 to-rose-100 ring-1 ring-rose-100 md:order-1\" />\n        <div className=\"md:order-2\">\n          <span className=\"text-xs font-semibold uppercase tracking-tight text-rose-600\">STARTUP</span>\n          <h1 className=\"font-['Verdana',ui-sans-serif,sans-serif] mt-3 text-4xl md:text-6xl font-bold leading-[1.02] tracking-tight text-slate-900\">For the team of five that acts like fifty.</h1>\n          <p className=\"mt-5 max-w-md text-lg text-slate-600\">Kindling is built for the earliest, scrappiest stage of a company.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-full bg-rose-600 px-6 py-3 text-sm font-semibold text-white hover:bg-rose-700 transition-colors\">Book a call</a>\n            <a href=\"#more\" className=\"text-sm font-semibold text-slate-700 underline decoration-slate-300 underline-offset-4 hover:decoration-slate-600\">Learn more</a>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-white\">\n      <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-4 border-t border-slate-100 px-6 py-10 text-center\">\n        <p className=\"font-['Verdana',ui-sans-serif,sans-serif] text-base font-bold tracking-tight text-slate-900\">Kindling</p>\n        <div className=\"flex flex-wrap items-center justify-center gap-6\">\n          <a href=\"/pricing\" className=\"text-sm text-slate-500 hover:text-slate-900\">Pricing</a>\n          <a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a>\n        </div>\n        <p className=\"text-xs text-slate-400\">&copy; {new Date().getFullYear()} Kindling &middot; Built with <span className=\"text-rose-600\">webma</span></p>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto grid max-w-5xl gap-10 px-6 py-20 md:grid-cols-2\">\n        <div>\n          <h2 className=\"font-['Verdana',ui-sans-serif,sans-serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Get in touch</h2>\n          <p className=\"mt-3 text-slate-500\">Tell us a bit about what you need — we'll take it from there.</p>\n          <div className=\"mt-8 space-y-4 text-sm text-slate-600\">\n            <p><span className=\"font-semibold text-slate-900\">Address</span><br />123 Market Street, Suite 400</p>\n            <p><span className=\"font-semibold text-slate-900\">Hours</span><br />Mon–Fri, 9am–6pm</p>\n          </div>\n        </div>\n        <form className=\"space-y-4 rounded-2xl border border-slate-200 bg-white p-6\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n          <input name=\"name\" required placeholder=\"Your name\" className=\"w-full rounded-2xl border border-slate-200 px-4 py-2.5 text-sm focus:border-rose-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full rounded-2xl border border-slate-200 px-4 py-2.5 text-sm focus:border-rose-500 focus:outline-none\" />\n          <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-2xl border border-slate-200 px-4 py-2.5 text-sm focus:border-rose-500 focus:outline-none\" />\n          <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n          <button type=\"submit\" className=\"w-full rounded-full bg-rose-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-rose-700 transition-colors\">Send message</button>\n        </form>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-2xl px-6 py-20\">\n        <div className=\"rounded-2xl border border-slate-200 bg-white p-8 shadow-sm\">\n          <div className=\"flex gap-0.5 text-rose-500\">{\"★★★★★\"}</div>\n          <p className=\"mt-4 text-lg text-slate-700\">&ldquo;A native experience on every device your team uses. That's exactly what Kindling delivered.&rdquo;</p>\n          <p className=\"mt-4 text-sm font-semibold text-slate-900\">Sofia Reyes <span className=\"font-normal text-slate-400\">— Marketing Director</span></p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Pricing.tsx":"import { Check } from \"lucide-react\";\n\nexport default function Pricing() {\n  return (\n    <section id=\"pricing\" className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-3xl px-6 py-20\">\n        <h2 className=\"font-['Verdana',ui-sans-serif,sans-serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">Simple, transparent pricing</h2>\n        <p className=\"mt-3 text-slate-500\">Choose the plan that fits — upgrade or cancel any time.</p>\n        <div className=\"mt-10 divide-y divide-slate-200 overflow-hidden rounded-2xl border border-slate-200 bg-white\">\n          <div className=\"flex flex-col gap-4 p-6 sm:flex-row sm:items-center sm:justify-between\">\n            <div>\n              <p className=\"font-semibold text-slate-900\">Starter </p>\n              <p className=\"mt-1 text-sm text-slate-500\">Core features</p>\n            </div>\n            <div className=\"flex items-center gap-4\">\n              <p className=\"text-2xl font-bold text-slate-900\">$29<span className=\"text-sm font-normal text-slate-400\">/mo</span></p>\n              <a href=\"/contact\" className=\"rounded-full bg-rose-600 px-5 py-2 text-sm font-semibold text-white hover:bg-rose-700 transition-colors\">Choose</a>\n            </div>\n          </div>\n          <div className=\"flex flex-col gap-4 p-6 sm:flex-row sm:items-center sm:justify-between\">\n            <div>\n              <p className=\"font-semibold text-slate-900\">Growth <span className=\"ml-2 rounded-full bg-rose-100 px-2 py-0.5 text-[10px] font-semibold uppercase text-rose-700\">Popular</span></p>\n              <p className=\"mt-1 text-sm text-slate-500\">Everything in Starter</p>\n            </div>\n            <div className=\"flex items-center gap-4\">\n              <p className=\"text-2xl font-bold text-slate-900\">$79<span className=\"text-sm font-normal text-slate-400\">/mo</span></p>\n              <a href=\"/contact\" className=\"rounded-full bg-rose-600 px-5 py-2 text-sm font-semibold text-white hover:bg-rose-700 transition-colors\">Choose</a>\n            </div>\n          </div>\n          <div className=\"flex flex-col gap-4 p-6 sm:flex-row sm:items-center sm:justify-between\">\n            <div>\n              <p className=\"font-semibold text-slate-900\">Scale </p>\n              <p className=\"mt-1 text-sm text-slate-500\">Everything in Growth</p>\n            </div>\n            <div className=\"flex items-center gap-4\">\n              <p className=\"text-2xl font-bold text-slate-900\">$199<span className=\"text-sm font-normal text-slate-400\">/mo</span></p>\n              <a href=\"/contact\" className=\"rounded-full bg-rose-600 px-5 py-2 text-sm font-semibold text-white hover:bg-rose-700 transition-colors\">Choose</a>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Stats.tsx":"export default function Stats() {\n  return (\n    <section className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto grid max-w-6xl grid-cols-2 gap-8 px-6 py-16 text-center md:grid-cols-4\">\n        <div><p className=\"text-3xl font-bold text-rose-300 md:text-4xl\">98%</p><p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Satisfaction</p></div>\n        <div><p className=\"text-3xl font-bold text-rose-300 md:text-4xl\">24/7</p><p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Support</p></div>\n        <div><p className=\"text-3xl font-bold text-rose-300 md:text-4xl\">50+</p><p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Team members</p></div>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"import { Zap, Star, Shield, Sparkles, Target, Heart, Award, TrendingUp, Users, Clock, CheckCircle, Compass } from \"lucide-react\";\n\nexport default function Features() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-4xl px-6 py-20\">\n        <h2 className=\"font-['Verdana',ui-sans-serif,sans-serif] text-3xl md:text-4xl font-bold tracking-tight text-slate-900\">What Kindling offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Kindling does best.</p>\n        <div className=\"mt-10 divide-y divide-slate-200\">\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-2xl bg-white text-rose-600 shadow-sm\"><Zap size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Fast onboarding</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">New customers see value in their first five minutes.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-2xl bg-white text-rose-600 shadow-sm\"><Star size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Usage-based pricing</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Pay for what you use, scale as you grow.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-2xl bg-white text-rose-600 shadow-sm\"><Shield size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Built-in collaboration</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Invite your whole team, no seat limits on the free tier.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-2xl bg-white text-rose-600 shadow-sm\"><Sparkles size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Mobile-first</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">A native experience on every device your team uses.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-2xl bg-white text-rose-600 shadow-sm\"><Target size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Open API</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Extend the product however your workflow needs.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-2xl bg-white text-rose-600 shadow-sm\"><Heart size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">24/7 support</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">A real person, not a bot, within the hour.</p>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Stats","Features","Testimonial","Footer"]},{"name":"Pricing","path":"/pricing","slug":"pricing","sections":["Navbar","Pricing","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base6