UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"border-b border-slate-100 bg-white\">\n      <nav className=\"mx-auto grid max-w-6xl grid-cols-3 items-center px-6 py-5\">\n        <div className=\"flex items-center gap-6\">\n          <a href=\"/pricing\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Pricing</a>\n        </div>\n        <a href=\"/\" className=\"font-['Palatino',ui-serif,serif] text-center text-xl font-bold tracking-normal text-slate-900\">Launchpad</a>\n        <div className=\"flex items-center justify-end gap-6\">\n          <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n          <a href=\"/contact\" className=\"text-sm font-semibold text-indigo-600 hover:text-indigo-700\">Contact →</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-4xl px-6 py-24 text-center md:py-28\">\n        \n        <h1 className=\"font-['Palatino',ui-serif,serif] mx-auto mt-5 max-w-3xl text-4xl md:text-5xl font-bold leading-[1.05] tracking-normal text-slate-900\">Ship your product before your competitors finish their roadmap meeting.</h1>\n        <p className=\"mx-auto mt-5 max-w-xl text-lg text-slate-600\">Launchpad gives your team one place to plan, build, and ship.</p>\n        <div className=\"mt-8 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-lg bg-indigo-600 px-6 py-3 text-sm font-semibold text-white hover:bg-indigo-700 transition-colors\">Get in touch</a>\n          <a href=\"#more\" className=\"rounded-lg border border-slate-300 px-6 py-3 text-sm font-semibold text-slate-700 hover:border-slate-400 transition-colors\">Explore</a>\n        </div>\n        <div className=\"mx-auto mt-14 grid max-w-2xl grid-cols-3 gap-6 border-t border-slate-200 pt-8\">\n          <div><p className=\"text-2xl font-bold text-slate-900\">98%</p><p className=\"mt-1 text-xs uppercase tracking-normal text-slate-400\">Satisfaction</p></div>\n          <div><p className=\"text-2xl font-bold text-slate-900\">24/7</p><p className=\"mt-1 text-xs uppercase tracking-normal text-slate-400\">Support</p></div>\n          <div><p className=\"text-2xl font-bold text-slate-900\">50+</p><p className=\"mt-1 text-xs uppercase tracking-normal text-slate-400\">Team members</p></div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <div className=\"grid gap-10 md:grid-cols-[1.2fr_1fr]\">\n          <div>\n            <p className=\"font-['Palatino',ui-serif,serif] text-xl font-bold tracking-normal\">Launchpad</p>\n            <p className=\"mt-2 max-w-sm text-sm text-white/50\">Launchpad gives your team one place to plan, build, and ship.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-normal text-white/40\">Stay in the loop</p>\n            <form className=\"mt-3 flex gap-2\" onSubmit={(e) => e.preventDefault()}>\n              <input type=\"email\" required placeholder=\"you@email.com\" className=\"w-full rounded-lg border border-white/15 bg-white/5 px-4 py-2.5 text-sm text-white placeholder:text-white/30 focus:border-indigo-400 focus:outline-none\" />\n              <button type=\"submit\" className=\"rounded-lg bg-indigo-500 px-5 py-2.5 text-sm font-semibold text-slate-950 hover:bg-indigo-400 transition-colors\">Join</button>\n            </form>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-3 border-t border-white/10 pt-6 text-xs text-white/40 sm:flex-row\">\n          <div className=\"flex gap-6\">\n            <a href=\"/pricing\" className=\"hover:text-white\">Pricing</a>\n            <a href=\"/contact\" className=\"hover:text-white\">Contact</a>\n          </div>\n          <p>&copy; {new Date().getFullYear()} Launchpad</p>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto grid max-w-5xl gap-10 px-6 py-20 md:grid-cols-2\">\n        <div>\n          <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">Get in touch</h2>\n          <p className=\"mt-3 text-slate-500\">Tell us a bit about what you need — we'll take it from there.</p>\n          <div className=\"mt-8 space-y-4 text-sm text-slate-600\">\n            <p><span className=\"font-semibold text-slate-900\">Address</span><br />123 Market Street, Suite 400</p>\n            <p><span className=\"font-semibold text-slate-900\">Hours</span><br />Mon–Fri, 9am–6pm</p>\n          </div>\n        </div>\n        <form className=\"space-y-4 rounded-lg border border-slate-200 bg-white p-6\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n          <input name=\"name\" required placeholder=\"Your name\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-indigo-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-indigo-500 focus:outline-none\" />\n          <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-indigo-500 focus:outline-none\" />\n          <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n          <button type=\"submit\" className=\"w-full rounded-lg bg-indigo-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-indigo-700 transition-colors\">Send message</button>\n        </form>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-3xl px-6 py-20 text-center\">\n      <p className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-medium leading-snug text-slate-900\">&ldquo;A real person, not a bot, within the hour. That's exactly what Launchpad delivered.&rdquo;</p>\n      <div className=\"mt-6 flex items-center justify-center gap-3\">\n        <div className=\"h-10 w-10 rounded-lg bg-indigo-100\" />\n        <div className=\"text-left\">\n          <p className=\"text-sm font-semibold text-slate-900\">Marcus Webb</p>\n          <p className=\"text-xs text-slate-500\">Client</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Pricing.tsx":"import { Check } from \"lucide-react\";\n\nexport default function Pricing() {\n  return (\n    <section id=\"pricing\" className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-3xl px-6 py-20\">\n        <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">Simple, transparent pricing</h2>\n        <p className=\"mt-3 text-slate-500\">Choose the plan that fits — upgrade or cancel any time.</p>\n        <div className=\"mt-10 divide-y divide-slate-200 overflow-hidden rounded-lg border border-slate-200 bg-white\">\n          <div className=\"flex flex-col gap-4 p-6 sm:flex-row sm:items-center sm:justify-between\">\n            <div>\n              <p className=\"font-semibold text-slate-900\">Starter </p>\n              <p className=\"mt-1 text-sm text-slate-500\">Core features</p>\n            </div>\n            <div className=\"flex items-center gap-4\">\n              <p className=\"text-2xl font-bold text-slate-900\">$29<span className=\"text-sm font-normal text-slate-400\">/mo</span></p>\n              <a href=\"/contact\" className=\"rounded-lg bg-indigo-600 px-5 py-2 text-sm font-semibold text-white hover:bg-indigo-700 transition-colors\">Choose</a>\n            </div>\n          </div>\n          <div className=\"flex flex-col gap-4 p-6 sm:flex-row sm:items-center sm:justify-between\">\n            <div>\n              <p className=\"font-semibold text-slate-900\">Growth <span className=\"ml-2 rounded-lg bg-indigo-100 px-2 py-0.5 text-[10px] font-semibold uppercase text-indigo-700\">Popular</span></p>\n              <p className=\"mt-1 text-sm text-slate-500\">Everything in Starter</p>\n            </div>\n            <div className=\"flex items-center gap-4\">\n              <p className=\"text-2xl font-bold text-slate-900\">$79<span className=\"text-sm font-normal text-slate-400\">/mo</span></p>\n              <a href=\"/contact\" className=\"rounded-lg bg-indigo-600 px-5 py-2 text-sm font-semibold text-white hover:bg-indigo-700 transition-colors\">Choose</a>\n            </div>\n          </div>\n          <div className=\"flex flex-col gap-4 p-6 sm:flex-row sm:items-center sm:justify-between\">\n            <div>\n              <p className=\"font-semibold text-slate-900\">Scale </p>\n              <p className=\"mt-1 text-sm text-slate-500\">Everything in Growth</p>\n            </div>\n            <div className=\"flex items-center gap-4\">\n              <p className=\"text-2xl font-bold text-slate-900\">$199<span className=\"text-sm font-normal text-slate-400\">/mo</span></p>\n              <a href=\"/contact\" className=\"rounded-lg bg-indigo-600 px-5 py-2 text-sm font-semibold text-white hover:bg-indigo-700 transition-colors\">Choose</a>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Stats.tsx":"export default function Stats() {\n  return (\n    <section className=\"border-y border-slate-100 bg-white\">\n      <div className=\"mx-auto grid max-w-6xl grid-cols-2 gap-6 px-6 py-12 md:grid-cols-4\">\n        <div className=\"rounded-lg bg-indigo-50 py-6 text-center\"><p className=\"text-2xl font-bold text-indigo-700\">98%</p><p className=\"mt-1 text-xs uppercase tracking-wider text-indigo-600/70\">Satisfaction</p></div>\n        <div className=\"rounded-lg bg-indigo-50 py-6 text-center\"><p className=\"text-2xl font-bold text-indigo-700\">24/7</p><p className=\"mt-1 text-xs uppercase tracking-wider text-indigo-600/70\">Support</p></div>\n        <div className=\"rounded-lg bg-indigo-50 py-6 text-center\"><p className=\"text-2xl font-bold text-indigo-700\">50+</p><p className=\"mt-1 text-xs uppercase tracking-wider text-indigo-600/70\">Team members</p></div>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"import { Zap, Star, Shield, Sparkles, Target, Heart, Award, TrendingUp, Users, Clock, CheckCircle, Compass } from \"lucide-react\";\n\nexport default function Features() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-4xl px-6 py-20\">\n        <h2 className=\"font-['Palatino',ui-serif,serif] text-2xl md:text-3xl font-bold tracking-normal text-slate-900\">What Launchpad offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Launchpad does best.</p>\n        <div className=\"mt-10 divide-y divide-slate-200\">\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-lg bg-white text-indigo-600 shadow-sm\"><Zap size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Fast onboarding</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">New customers see value in their first five minutes.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-lg bg-white text-indigo-600 shadow-sm\"><Star size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Usage-based pricing</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Pay for what you use, scale as you grow.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-lg bg-white text-indigo-600 shadow-sm\"><Shield size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Built-in collaboration</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Invite your whole team, no seat limits on the free tier.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-lg bg-white text-indigo-600 shadow-sm\"><Sparkles size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Mobile-first</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">A native experience on every device your team uses.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-lg bg-white text-indigo-600 shadow-sm\"><Target size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">Open API</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">Extend the product however your workflow needs.</p>\n            </div>\n          </div>\n          <div className=\"flex items-start gap-4 py-5\">\n            <div className=\"flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-lg bg-white text-indigo-600 shadow-sm\"><Heart size={16} /></div>\n            <div>\n              <h3 className=\"font-semibold text-slate-900\">24/7 support</h3>\n              <p className=\"mt-1 text-sm text-slate-500\">A real person, not a bot, within the hour.</p>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Stats","Features","Testimonial","Footer"]},{"name":"Pricing","path":"/pricing","slug":"pricing","sections":["Navbar","Pricing","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '38cac347-f403-40d0-81ae-aac287da929f'::uuid;
UPDATE templates SET structure = $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"bg-white\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-6\">\n        <a href=\"/\" className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-base font-bold uppercase tracking-tighter text-slate-900\">Voyage</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n          <a href=\"/pricing\" className=\"border-b-2 border-transparent pb-1 text-sm font-medium text-slate-500 hover:border-sky-500 hover:text-slate-900 transition-colors\">Pricing</a>\n          <a href=\"/contact\" className=\"border-b-2 border-transparent pb-1 text-sm font-medium text-slate-500 hover:border-sky-500 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-4xl px-6 py-24 text-center md:py-28\">\n        \n        <h1 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] mx-auto mt-5 max-w-3xl text-5xl md:text-7xl font-bold leading-[1.05] tracking-tighter text-slate-900\">From idea to launch in weeks, not quarters.</h1>\n        <p className=\"mx-auto mt-5 max-w-xl text-lg text-slate-600\">Voyage strips away everything that isn't directly getting you to your first customer.</p>\n        <div className=\"mt-8 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-none bg-sky-600 px-6 py-3 text-sm font-semibold text-white hover:bg-sky-700 transition-colors\">Talk to us</a>\n          <a href=\"#more\" className=\"rounded-none border border-slate-300 px-6 py-3 text-sm font-semibold text-slate-700 hover:border-slate-400 transition-colors\">See examples</a>\n        </div>\n        <div className=\"mx-auto mt-14 grid max-w-2xl grid-cols-3 gap-6 border-t border-slate-200 pt-8\">\n          <div><p className=\"text-2xl font-bold text-slate-900\">500+</p><p className=\"mt-1 text-xs uppercase tracking-tighter text-slate-400\">Clients served</p></div>\n          <div><p className=\"text-2xl font-bold text-slate-900\">10 yrs</p><p className=\"mt-1 text-xs uppercase tracking-tighter text-slate-400\">In business</p></div>\n          <div><p className=\"text-2xl font-bold text-slate-900\">4.9/5</p><p className=\"mt-1 text-xs uppercase tracking-tighter text-slate-400\">Avg. rating</p></div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer>\n      <div className=\"bg-sky-600 text-white\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-4 px-6 py-14 text-center md:flex-row md:justify-between md:text-left\">\n          <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter\">Ready when you are.</h2>\n          <a href=\"/contact\" className=\"rounded-none bg-white px-6 py-3 text-sm font-semibold text-sky-700 hover:bg-white/90 transition-colors\">Get in touch</a>\n        </div>\n      </div>\n      <div className=\"bg-white\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center justify-between gap-3 px-6 py-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Voyage</p>\n          <div className=\"flex gap-6\">\n            <a href=\"/pricing\" className=\"text-slate-500 hover:text-slate-900\">Pricing</a>\n            <a href=\"/contact\" className=\"text-slate-500 hover:text-slate-900\">Contact</a>\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-xl px-6 py-24 text-center\">\n      <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Get in touch</h2>\n      <p className=\"mt-3 text-slate-500\">Tell us a bit about what you need — we'll take it from there.</p>\n      <form className=\"mt-10 space-y-3 text-left\" onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}>\n        <input name=\"name\" required placeholder=\"Your name\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-sky-500 focus:outline-none\" />\n        <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-sky-500 focus:outline-none\" />\n        <textarea name=\"message\" required rows={3} placeholder=\"How can we help?\" className=\"w-full border-b border-slate-300 bg-transparent px-1 py-3 text-sm focus:border-sky-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"mt-4 w-full rounded-none bg-sky-600 px-6 py-3 text-sm font-semibold text-white hover:bg-sky-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-3xl px-6 py-20 text-center\">\n      <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-medium leading-snug text-slate-900\">&ldquo;A real person, not a bot, within the hour. That's exactly what Voyage delivered.&rdquo;</p>\n      <div className=\"mt-6 flex items-center justify-center gap-3\">\n        <div className=\"h-10 w-10 rounded-none bg-sky-100\" />\n        <div className=\"text-left\">\n          <p className=\"text-sm font-semibold text-slate-900\">Owen Clarke</p>\n          <p className=\"text-xs text-slate-500\">Founder</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Pricing.tsx":"import { Check } from \"lucide-react\";\n\nexport default function Pricing() {\n  return (\n    <section id=\"pricing\" className=\"bg-slate-50\">\n      <div className=\"mx-auto max-w-3xl px-6 py-20\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">Simple, transparent pricing</h2>\n        <p className=\"mt-3 text-slate-500\">Choose the plan that fits — upgrade or cancel any time.</p>\n        <div className=\"mt-10 divide-y divide-slate-200 overflow-hidden rounded-none border border-slate-200 bg-white\">\n          <div className=\"flex flex-col gap-4 p-6 sm:flex-row sm:items-center sm:justify-between\">\n            <div>\n              <p className=\"font-semibold text-slate-900\">Starter </p>\n              <p className=\"mt-1 text-sm text-slate-500\">Core features</p>\n            </div>\n            <div className=\"flex items-center gap-4\">\n              <p className=\"text-2xl font-bold text-slate-900\">$29<span className=\"text-sm font-normal text-slate-400\">/mo</span></p>\n              <a href=\"/contact\" className=\"rounded-none bg-sky-600 px-5 py-2 text-sm font-semibold text-white hover:bg-sky-700 transition-colors\">Choose</a>\n            </div>\n          </div>\n          <div className=\"flex flex-col gap-4 p-6 sm:flex-row sm:items-center sm:justify-between\">\n            <div>\n              <p className=\"font-semibold text-slate-900\">Growth <span className=\"ml-2 rounded-none bg-sky-100 px-2 py-0.5 text-[10px] font-semibold uppercase text-sky-700\">Popular</span></p>\n              <p className=\"mt-1 text-sm text-slate-500\">Everything in Starter</p>\n            </div>\n            <div className=\"flex items-center gap-4\">\n              <p className=\"text-2xl font-bold text-slate-900\">$79<span className=\"text-sm font-normal text-slate-400\">/mo</span></p>\n              <a href=\"/contact\" className=\"rounded-none bg-sky-600 px-5 py-2 text-sm font-semibold text-white hover:bg-sky-700 transition-colors\">Choose</a>\n            </div>\n          </div>\n          <div className=\"flex flex-col gap-4 p-6 sm:flex-row sm:items-center sm:justify-between\">\n            <div>\n              <p className=\"font-semibold text-slate-900\">Scale </p>\n              <p className=\"mt-1 text-sm text-slate-500\">Everything in Growth</p>\n            </div>\n            <div className=\"flex items-center gap-4\">\n              <p className=\"text-2xl font-bold text-slate-900\">$199<span className=\"text-sm font-normal text-slate-400\">/mo</span></p>\n              <a href=\"/contact\" className=\"rounded-none bg-sky-600 px-5 py-2 text-sm font-semibold text-white hover:bg-sky-700 transition-colors\">Choose</a>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Stats.tsx":"export default function Stats() {\n  return (\n    <section className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto grid max-w-6xl grid-cols-2 gap-8 px-6 py-16 text-center md:grid-cols-4\">\n        <div><p className=\"text-3xl font-bold text-sky-300 md:text-4xl\">500+</p><p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Clients served</p></div>\n        <div><p className=\"text-3xl font-bold text-sky-300 md:text-4xl\">10 yrs</p><p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">In business</p></div>\n        <div><p className=\"text-3xl font-bold text-sky-300 md:text-4xl\">4.9/5</p><p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Avg. rating</p></div>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"export default function Features() {\n  return (\n    <section className=\"mx-auto max-w-5xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-2xl md:text-3xl font-bold tracking-tighter text-slate-900\">What Voyage offers</h2>\n        <p className=\"mt-3 text-slate-500\">A closer look at what Voyage does best.</p>\n      </div>\n      <div className=\"mt-10 grid gap-8 sm:grid-cols-2 lg:grid-cols-3\">\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-4xl font-bold text-sky-200\">01</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Fast onboarding</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">New customers see value in their first five minutes.</p>\n        </div>\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-4xl font-bold text-sky-200\">02</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Usage-based pricing</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Pay for what you use, scale as you grow.</p>\n        </div>\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-4xl font-bold text-sky-200\">03</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Built-in collaboration</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Invite your whole team, no seat limits on the free tier.</p>\n        </div>\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-4xl font-bold text-sky-200\">04</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Mobile-first</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">A native experience on every device your team uses.</p>\n        </div>\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-4xl font-bold text-sky-200\">05</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">Open API</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">Extend the product however your workflow needs.</p>\n        </div>\n        <div>\n          <p className=\"font-['Trebuchet_MS',ui-sans-serif,sans-serif] text-4xl font-bold text-sky-200\">06</p>\n          <h3 className=\"mt-2 font-semibold text-slate-900\">24/7 support</h3>\n          <p className=\"mt-1.5 text-sm text-slate-500\">A real person, not a bot, within the hour.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"name":"Home","path":"/","slug":"index","sections":["Navbar","Hero","Stats","Features","Testimonial","Footer"]},{"name":"Pricing","path":"/pricing","slug":"pricing","sections":["Navbar","Pricing","Footer"]},{"name":"Contact","path":"/contact","slug":"contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb, thumbnail = $thumb$data:image/svg+xml;base64,$thumb$ WHERE id = '2dc285c8-1173-4c7d-9d8d-2a0bae0553fb'::uuid;
